#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum BuildProfile {
    Research,
    Editor,
    DevelopmentGameplay,
    PerformanceTest,
    Shipping,
    ReferenceRender,
}

impl BuildProfile {
    pub fn label(self) -> &'static str {
        match self {
            Self::Research => "research",
            Self::Editor => "editor",
            Self::DevelopmentGameplay => "development_gameplay",
            Self::PerformanceTest => "performance_test",
            Self::Shipping => "shipping",
            Self::ReferenceRender => "reference_render",
        }
    }

    pub fn default_quality(self) -> QualityTier {
        match self {
            Self::Research | Self::Editor | Self::DevelopmentGameplay => QualityTier::NormalRuntime,
            Self::PerformanceTest | Self::Shipping => QualityTier::HeroHighFidelityRuntime,
            Self::ReferenceRender => QualityTier::ReferenceOfflineValidation,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum ValidationLevel {
    Smoke,
    Runtime,
    Editor,
    Reference,
}

impl ValidationLevel {
    pub fn minimum_score(self) -> f32 {
        match self {
            Self::Smoke => 0.25,
            Self::Runtime => 0.65,
            Self::Editor => 0.8,
            Self::Reference => 0.93,
        }
    }
}

