#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AssetValidationReport {
    pub passed: bool,
    pub level: ValidationLevel,
    pub score_basis_points: u16,
    pub issues: Vec<AssetValidationIssue>,
}

impl AssetValidationReport {
    pub fn new(level: ValidationLevel, score_basis_points: u16) -> Self {
        Self {
            passed: true,
            level,
            score_basis_points,
            issues: Vec::new(),
        }
    }

    pub fn score(&self) -> f32 {
        self.score_basis_points as f32 / 10_000.0
    }

    pub fn add_issue(
        &mut self,
        severity: ToolIssueSeverity,
        code: impl Into<String>,
        message: impl Into<String>,
    ) {
        if severity == ToolIssueSeverity::Error {
            self.passed = false;
        }
        self.issues.push(AssetValidationIssue {
            severity,
            code: code.into(),
            message: message.into(),
        });
    }

    pub fn merge(&mut self, other: AssetValidationReport) {
        self.passed &= other.passed;
        self.issues.extend(other.issues);
        self.score_basis_points = self.score_basis_points.min(other.score_basis_points);
    }
}

