#[derive(Clone, Debug, Default, PartialEq)]
pub struct StreamingDebuggerReport {
    pub frames: Vec<StreamingFrameDebug>,
    pub requesters: Vec<StreamingRequesterDebug>,
    pub completions: Vec<StreamingCompletionDebug>,
    pub replay_events: Vec<StreamingReplayEventDebug>,
    pub issues: Vec<StreamingDebuggerIssue>,
    pub frame_count: usize,
    pub latest_total_registered_assets: usize,
    pub latest_resident_assets: usize,
    pub latest_pending_assets: usize,
    pub peak_pending_assets: usize,
    pub peak_bytes_pending: u64,
    pub peak_bytes_streamed: u64,
    pub total_bytes_streamed: u64,
    pub total_completed_assets: usize,
    pub request_event_count: usize,
    pub resident_event_count: usize,
    pub requester_count: usize,
}

impl StreamingDebuggerReport {
    pub fn is_empty(&self) -> bool {
        self.frames.is_empty() && self.replay_events.is_empty()
    }

    pub fn passed(&self) -> bool {
        self.critical_issue_count() == 0
    }

    pub fn critical_issue_count(&self) -> usize {
        self.issues
            .iter()
            .filter(|issue| issue.severity == ToolIssueSeverity::Error)
            .count()
    }

    pub fn requester(&self, requester: ModuleId) -> Option<&StreamingRequesterDebug> {
        self.requesters
            .iter()
            .find(|lane| lane.requester == requester)
    }
}

