pub fn build_runtime_package(
    request: &AssetBuildRequest,
    source: &SourceAsset,
    schemas: &SchemaRegistry,
) -> AssetBuildResult {
    let asset_id = asset_id_for_build(request, source);
    let dependencies = source.dependencies.clone();
    let schema_hash = schema_hash(&source.schema_name, source.schema_version);
    let source_id_bytes = source.id.to_le_bytes();
    let source_byte_len_bytes = source.byte_len.to_le_bytes();
    let chunk = AssetChunk {
        chunk_id: 1,
        usage: chunk_usage_for_kind(&request.target_kind),
        compression: CompressionKind::None,
        uncompressed_size: source.byte_len,
        compressed_size: source.byte_len,
        content_hash: stable_hash128([
            source_id_bytes.as_slice(),
            source.label.as_bytes(),
            request.build_profile.label().as_bytes(),
            source_byte_len_bytes.as_slice(),
        ]),
    };
    let package = AssetPackage {
        header: AssetPackageHeader {
            magic: ASSET_PACKAGE_MAGIC,
            version_major: ASSET_PACKAGE_VERSION_MAJOR,
            version_minor: ASSET_PACKAGE_VERSION_MINOR,
            asset_id,
            asset_kind: request.target_kind.clone(),
            dependency_count: dependencies.len().try_into().unwrap_or(u32::MAX),
            chunk_table_offset: 128,
            schema_hash,
        },
        label: source.label.clone(),
        provenance: format!(
            "{};source={};profile={}",
            source.provenance,
            source.id,
            request.build_profile.label()
        ),
        schema_name: source.schema_name.clone(),
        source_asset: source.id,
        dependencies,
        chunks: vec![chunk],
        validation_score_basis_points: validation_score_for_profile(request.build_profile),
        quality_tier: request.build_profile.default_quality(),
    };

    let mut validation_report = validate_asset_build_package(request, &package, schemas);
    if request.source_asset != source.id {
        validation_report.add_issue(
            ToolIssueSeverity::Error,
            "source_asset_mismatch",
            "build request source asset does not match the provided source asset",
        );
    }
    let asset_id_bytes = asset_id.to_le_bytes();
    let build_log = stable_hash128([
        asset_id_bytes.as_slice(),
        request.build_profile.label().as_bytes(),
        b"build-log",
    ]);

    AssetBuildResult {
        asset_id,
        package_path: format!(
            "build/{}/{asset_id:032x}.afpkg",
            request.build_profile.label()
        ),
        dependencies: package.dependencies.clone(),
        validation_report,
        build_log,
        package,
    }
}

pub fn validate_asset_build_package(
    request: &AssetBuildRequest,
    package: &AssetPackage,
    schemas: &SchemaRegistry,
) -> AssetValidationReport {
    let mut report = validate_asset_package(package, request.validation_level);
    if package.header.asset_kind != request.target_kind {
        report.add_issue(
            ToolIssueSeverity::Error,
            "target_kind_mismatch",
            "package asset kind does not match the build request",
        );
    }

    match request.dependency_policy {
        DependencyPolicy::AllowMissing => {}
        DependencyPolicy::RequireDeclared => {
            if package.dependencies.is_empty() {
                report.add_issue(
                    ToolIssueSeverity::Error,
                    "missing_dependencies",
                    "build request requires declared dependencies",
                );
            }
        }
        DependencyPolicy::ForbidExternal => {
            if !package.dependencies.is_empty() {
                report.add_issue(
                    ToolIssueSeverity::Error,
                    "external_dependencies_forbidden",
                    "build request forbids external dependencies",
                );
            }
        }
    }

    if package.dependencies.contains(&0) {
        report.add_issue(
            ToolIssueSeverity::Error,
            "invalid_dependency",
            "asset package contains a zero dependency handle",
        );
    }

    let schema_report = schemas.check_requirements(&[SchemaRequirement::required(
        TOOLS_SYSTEM_ID,
        package_schema_name(package),
        package_schema_version(package),
        "asset package must match a registered runtime schema",
    )]);
    merge_schema_report(&mut report, schema_report);

    report
}

pub fn validate_asset_package(
    package: &AssetPackage,
    level: ValidationLevel,
) -> AssetValidationReport {
    let mut report =
        AssetValidationReport::new(level, package.validation_score_basis_points.min(10_000));
    if package.header.magic != ASSET_PACKAGE_MAGIC {
        report.add_issue(
            ToolIssueSeverity::Error,
            "bad_magic",
            "asset package magic does not identify an Ashfall package",
        );
    }
    if package.header.version_major == 0 {
        report.add_issue(
            ToolIssueSeverity::Error,
            "bad_version",
            "asset package major version must be nonzero",
        );
    }
    if package.header.asset_id == 0 {
        report.add_issue(
            ToolIssueSeverity::Error,
            "missing_asset_id",
            "asset package must carry a stable asset id",
        );
    }
    if package.header.dependency_count as usize != package.dependencies.len() {
        report.add_issue(
            ToolIssueSeverity::Error,
            "dependency_count_mismatch",
            "asset package header dependency count does not match dependency table",
        );
    }
    if package.header.chunk_table_offset == 0 {
        report.add_issue(
            ToolIssueSeverity::Error,
            "missing_chunk_table",
            "asset package must point to a chunk table",
        );
    }
    if package.header.schema_hash == 0 {
        report.add_issue(
            ToolIssueSeverity::Error,
            "missing_schema_hash",
            "asset package must record the schema hash used for validation",
        );
    }
    if package.chunks.is_empty() {
        report.add_issue(
            ToolIssueSeverity::Error,
            "missing_chunks",
            "asset package must contain at least one runtime chunk",
        );
    }

    let mut chunk_ids = BTreeSet::new();
    for chunk in &package.chunks {
        if !chunk_ids.insert(chunk.chunk_id) {
            report.add_issue(
                ToolIssueSeverity::Error,
                "duplicate_chunk_id",
                format!("asset package repeats chunk id {}", chunk.chunk_id),
            );
        }
        if chunk.uncompressed_size == 0 {
            report.add_issue(
                ToolIssueSeverity::Error,
                "empty_chunk",
                format!("asset chunk {} has no runtime bytes", chunk.chunk_id),
            );
        }
        if chunk.compressed_size > chunk.uncompressed_size {
            report.add_issue(
                ToolIssueSeverity::Error,
                "bad_compression_size",
                format!("asset chunk {} is larger when compressed", chunk.chunk_id),
            );
        }
        if chunk.compression == CompressionKind::None
            && chunk.compressed_size != chunk.uncompressed_size
        {
            report.add_issue(
                ToolIssueSeverity::Error,
                "uncompressed_size_mismatch",
                format!(
                    "asset chunk {} is marked uncompressed but sizes differ",
                    chunk.chunk_id
                ),
            );
        }
        if chunk.content_hash == 0 {
            report.add_issue(
                ToolIssueSeverity::Error,
                "missing_chunk_hash",
                format!("asset chunk {} is missing a content hash", chunk.chunk_id),
            );
        }
    }

    if report.score() < level.minimum_score() {
        report.add_issue(
            ToolIssueSeverity::Error,
            "validation_score_too_low",
            format!(
                "asset validation score {:.2} is below {:?} minimum {:.2}",
                report.score(),
                level,
                level.minimum_score()
            ),
        );
    }

    report
}

pub fn shared_validation_report_from_asset_validation(
    asset_id: AssetId,
    component: ModuleId,
    report: &AssetValidationReport,
) -> SharedValidationReport {
    let mut shared =
        SharedValidationReport::for_asset(asset_id, component, VALIDATION_REPORT_SCHEMA);
    shared.passed = report.passed;
    let subject = format!("asset:{asset_id:032x}");

    for issue in &report.issues {
        match issue.severity {
            ToolIssueSeverity::Info | ToolIssueSeverity::Warning => {
                shared.add_warning(issue.code.clone(), issue.message.clone(), subject.clone());
            }
            ToolIssueSeverity::Error => {
                shared.add_error(issue.code.clone(), issue.message.clone(), subject.clone());
            }
        }
    }

    if !report.passed && shared.errors.is_empty() {
        shared.add_error(
            "validation_failed",
            "tool validation report failed without a specific error issue",
            subject,
        );
    }

    shared.add_metric(
        "validation_score",
        report.score() as f64,
        "ratio",
        Some(report.level.minimum_score() as f64),
    );
    shared.add_metric("issue_count", report.issues.len() as f64, "count", None);
    shared
}

pub fn asset_package_manifest_from_build_result(result: &AssetBuildResult) -> AssetPackageManifest {
    let package = &result.package;
    AssetPackageManifest {
        package_asset: result.asset_id,
        manifest_schema_version: ASSET_PACKAGE_MANIFEST_SCHEMA_VERSION,
        asset_kind: package.header.asset_kind.clone(),
        label: package.label.clone(),
        provenance: package.provenance.clone(),
        schema_name: package_schema_name(package),
        schema_version: package_schema_version(package),
        dependencies: package.dependencies.clone(),
        chunks: package
            .chunks
            .iter()
            .map(|chunk| AssetPackageChunkManifest {
                chunk_id: chunk.chunk_id,
                usage_label: asset_chunk_usage_label(chunk.usage).to_string(),
                uncompressed_size: chunk.uncompressed_size,
                compressed_size: chunk.compressed_size,
                content_hash: chunk.content_hash,
            })
            .collect(),
        total_uncompressed_bytes: package.total_uncompressed_bytes(),
        generated: true,
        quality_tier: package.quality_tier,
        validation: result.validation_report_v4(),
    }
}

pub fn register_built_asset(
    registry: &mut AssetRegistry,
    result: &AssetBuildResult,
) -> Option<AssetId> {
    if !result.validation_report.passed {
        return None;
    }
    registry.register_known(result.asset_record());
    Some(result.asset_id)
}

pub fn summarize_asset_pipeline(results: &[AssetBuildResult]) -> AssetPipelineReport {
    let mut issues = Vec::new();
    let mut total_uncompressed_bytes = 0_u64;
    let mut passed_assets = 0_usize;
    for result in results {
        if result.validation_report.passed {
            passed_assets += 1;
        }
        total_uncompressed_bytes =
            total_uncompressed_bytes.saturating_add(result.package.total_uncompressed_bytes());
        issues.extend(result.validation_report.issues.clone());
    }
    AssetPipelineReport {
        built_assets: results.len(),
        passed_assets,
        failed_assets: results.len().saturating_sub(passed_assets),
        total_uncompressed_bytes,
        issues,
    }
}

pub fn inventory_registered_assets(registry: &AssetRegistry) -> AssetInventoryReport {
    let mut report = AssetInventoryReport::default();
    let mut by_kind = std::collections::BTreeMap::<String, AssetKindInventory>::new();

    for asset in registry.all() {
        report.total_assets += 1;
        if asset.generated {
            report.generated_assets += 1;
        }
        report.total_known_bytes = report
            .total_known_bytes
            .saturating_add(asset.byte_len.unwrap_or(0));
        match asset.load_state {
            AssetLoadState::Unloaded => report.unloaded_assets += 1,
            AssetLoadState::Queued => report.queued_assets += 1,
            AssetLoadState::Loading => report.loading_assets += 1,
            AssetLoadState::Resident => report.resident_assets += 1,
            AssetLoadState::Failed => report.failed_assets += 1,
        }

        let kind_label = asset_kind_label(&asset.kind);
        let kind_entry = by_kind
            .entry(kind_label.clone())
            .or_insert_with(|| AssetKindInventory {
                kind_label,
                asset_count: 0,
                known_bytes: 0,
            });
        kind_entry.asset_count += 1;
        kind_entry.known_bytes = kind_entry
            .known_bytes
            .saturating_add(asset.byte_len.unwrap_or(0));

        for dependency in &asset.dependencies {
            if registry.get(*dependency).is_none() {
                report.missing_dependency_edges.push(AssetDependencyIssue {
                    asset_id: asset.id,
                    missing_dependency: *dependency,
                });
            }
        }
    }

    report.by_kind = by_kind.into_values().collect();
    report
}

pub fn asset_browser_report_from_pipeline(
    asset_results: &[AssetBuildResult],
) -> AssetBrowserReport {
    asset_browser_report(asset_results, None)
}

pub fn asset_browser_report_from_runtime(
    asset_results: &[AssetBuildResult],
    registry: &AssetRegistry,
) -> AssetBrowserReport {
    asset_browser_report(asset_results, Some(registry))
}

fn asset_browser_report(
    asset_results: &[AssetBuildResult],
    registry: Option<&AssetRegistry>,
) -> AssetBrowserReport {
    let mut report = AssetBrowserReport::default();
    let mut by_kind = BTreeMap::<String, AssetBrowserKindSummary>::new();
    let mut by_schema = BTreeMap::<(String, u32), AssetBrowserSchemaAccumulator>::new();
    let package_ids = asset_results
        .iter()
        .map(|result| result.asset_id)
        .collect::<BTreeSet<_>>();
    let runtime_ids = registry
        .map(|registry| {
            registry
                .all()
                .map(|asset| asset.id)
                .collect::<BTreeSet<_>>()
        })
        .unwrap_or_default();
    let packages_by_id = asset_results
        .iter()
        .map(|result| (result.asset_id, result))
        .collect::<BTreeMap<_, _>>();

    for result in asset_results {
        let package = &result.package;
        let kind_label = asset_kind_label(&package.header.asset_kind);
        let schema_name = package_schema_name(package);
        let schema_version = package_schema_version(package);
        let package_bytes = package.total_uncompressed_bytes();
        let validation_error_count = result
            .validation_report
            .issues
            .iter()
            .filter(|issue| issue.severity == ToolIssueSeverity::Error)
            .count();

        report.total_package_bytes = report.total_package_bytes.saturating_add(package_bytes);
        report.validation_error_count += validation_error_count;
        report.packages.push(AssetBrowserPackageEntry {
            asset_id: result.asset_id,
            label: package.label.clone(),
            kind_label: kind_label.clone(),
            package_path: result.package_path.clone(),
            source_asset: package.source_asset,
            provenance: package.provenance.clone(),
            schema_name: schema_name.clone(),
            schema_version,
            quality_tier: package.quality_tier,
            dependency_count: package.dependencies.len(),
            chunk_count: package.chunks.len(),
            total_uncompressed_bytes: package_bytes,
            validation_passed: result.validation_report.passed,
            validation_issue_count: result.validation_report.issues.len(),
        });

        let kind = by_kind
            .entry(kind_label.clone())
            .or_insert_with(|| AssetBrowserKindSummary {
                kind_label,
                package_count: 0,
                runtime_asset_count: 0,
                generated_runtime_asset_count: 0,
                resident_runtime_asset_count: 0,
                known_bytes: 0,
            });
        kind.package_count += 1;
        kind.known_bytes = kind.known_bytes.saturating_add(package_bytes);

        let schema = by_schema.entry((schema_name, schema_version)).or_default();
        schema.package_count += 1;
        schema.validation_error_count += validation_error_count;

        for issue in &result.validation_report.issues {
            push_asset_browser_issue(
                &mut report,
                issue.severity,
                format!("package_{}", issue.code),
                format!("asset:{:032x}", result.asset_id),
                issue.message.clone(),
            );
        }

        for dependency in &package.dependencies {
            report.dependencies.push(AssetBrowserDependencyEdge {
                asset_id: result.asset_id,
                dependency: *dependency,
                source: AssetDependencySource::Package,
                resolved_in_runtime: runtime_ids.contains(dependency),
                resolved_in_package_set: package_ids.contains(dependency),
            });
        }
    }

    if let Some(registry) = registry {
        for asset in registry.all() {
            let kind_label = asset_kind_label(&asset.kind);
            let known_bytes = asset.byte_len.unwrap_or(0);
            let package = packages_by_id.get(&asset.id).copied();
            let schema_name = package.map(|result| package_schema_name(&result.package));
            let schema_version = package.map(|result| package_schema_version(&result.package));

            report.total_runtime_known_bytes =
                report.total_runtime_known_bytes.saturating_add(known_bytes);
            if asset.generated {
                report.generated_runtime_asset_count += 1;
            }
            if asset.load_state == AssetLoadState::Resident {
                report.resident_runtime_asset_count += 1;
            }

            report.runtime_assets.push(AssetBrowserRuntimeAssetEntry {
                asset_id: asset.id,
                label: asset.label.clone(),
                kind_label: kind_label.clone(),
                provenance: asset.provenance.clone(),
                generated: asset.generated,
                quality_tier: asset.quality_tier,
                load_state: asset.load_state,
                dependency_count: asset.dependencies.len(),
                known_bytes,
                built_package_path: package.map(|result| result.package_path.clone()),
                schema_name: schema_name.clone(),
            });

            let kind =
                by_kind
                    .entry(kind_label.clone())
                    .or_insert_with(|| AssetBrowserKindSummary {
                        kind_label,
                        package_count: 0,
                        runtime_asset_count: 0,
                        generated_runtime_asset_count: 0,
                        resident_runtime_asset_count: 0,
                        known_bytes: 0,
                    });
            kind.runtime_asset_count += 1;
            kind.known_bytes = kind.known_bytes.saturating_add(known_bytes);
            if asset.generated {
                kind.generated_runtime_asset_count += 1;
            }
            if asset.load_state == AssetLoadState::Resident {
                kind.resident_runtime_asset_count += 1;
            }

            if let (Some(schema_name), Some(schema_version)) = (schema_name, schema_version) {
                by_schema
                    .entry((schema_name, schema_version))
                    .or_default()
                    .runtime_asset_count += 1;
            }

            for dependency in &asset.dependencies {
                let resolved_in_runtime = runtime_ids.contains(dependency);
                report.dependencies.push(AssetBrowserDependencyEdge {
                    asset_id: asset.id,
                    dependency: *dependency,
                    source: AssetDependencySource::RuntimeRegistry,
                    resolved_in_runtime,
                    resolved_in_package_set: package_ids.contains(dependency),
                });
                if !resolved_in_runtime {
                    report.missing_runtime_dependency_count += 1;
                    push_asset_browser_issue(
                        &mut report,
                        ToolIssueSeverity::Error,
                        "missing_runtime_dependency",
                        format!("asset:{:032x}", asset.id),
                        format!(
                            "runtime asset {} depends on missing asset {}",
                            asset.id, dependency
                        ),
                    );
                }
            }
        }
    }

    report.package_count = report.packages.len();
    report.runtime_asset_count = report.runtime_assets.len();
    report.dependency_edge_count = report.dependencies.len();
    report.schema_count = by_schema.len();
    report.by_kind = by_kind.into_values().collect();
    report.schemas = by_schema
        .into_iter()
        .map(
            |((schema_name, schema_version), accumulator)| AssetBrowserSchemaEntry {
                schema_name,
                schema_version,
                package_count: accumulator.package_count,
                runtime_asset_count: accumulator.runtime_asset_count,
                validation_error_count: accumulator.validation_error_count,
            },
        )
        .collect();

    report.packages.sort_by_key(|package| package.asset_id);
    report.runtime_assets.sort_by_key(|asset| asset.asset_id);
    report
        .dependencies
        .sort_by_key(|edge| (edge.asset_id, edge.dependency, edge.source));
    report
}

#[derive(Default)]
struct AssetBrowserSchemaAccumulator {
    package_count: usize,
    runtime_asset_count: usize,
    validation_error_count: usize,
}

fn push_asset_browser_issue(
    report: &mut AssetBrowserReport,
    severity: ToolIssueSeverity,
    code: impl Into<String>,
    subject: impl Into<String>,
    message: impl Into<String>,
) {
    report.issues.push(AssetBrowserIssue {
        severity,
        code: code.into(),
        subject: subject.into(),
        message: message.into(),
    });
}

pub fn schema_inspector_report_from_pipeline(
    asset_results: &[AssetBuildResult],
) -> SchemaInspectorReport {
    schema_inspector_report(asset_results, None, None, &[])
}

pub fn schema_inspector_report_from_runtime(
    asset_results: &[AssetBuildResult],
    schemas: &SchemaRegistry,
    module_registry: &ModuleRegistryReport,
    frame_reports: &[FrameReport],
) -> SchemaInspectorReport {
    schema_inspector_report(
        asset_results,
        Some(schemas),
        Some(module_registry),
        frame_reports,
    )
}

fn schema_inspector_report(
    asset_results: &[AssetBuildResult],
    schemas: Option<&SchemaRegistry>,
    module_registry: Option<&ModuleRegistryReport>,
    frame_reports: &[FrameReport],
) -> SchemaInspectorReport {
    let mut report = SchemaInspectorReport::default();
    let mut owners = BTreeSet::<ModuleId>::new();
    let mut required_by_count = BTreeMap::<String, usize>::new();
    let mut package_count = BTreeMap::<String, usize>::new();
    let mut migration_count = BTreeMap::<String, usize>::new();

    for result in asset_results {
        let schema_name = package_schema_name(&result.package);
        let schema_version = package_schema_version(&result.package);
        let registered = schemas.and_then(|schemas| schemas.get(&schema_name));
        let validation_error_count = result
            .validation_report
            .issues
            .iter()
            .filter(|issue| issue.severity == ToolIssueSeverity::Error)
            .count();
        *package_count.entry(schema_name.clone()).or_default() += 1;
        report.package_schemas.push(PackageSchemaDebugEntry {
            asset_id: result.asset_id,
            package_path: result.package_path.clone(),
            schema_name,
            schema_version,
            registered_version: registered.map(|schema| schema.version.version),
            owner: registered.map(|schema| schema.owner),
            validation_passed: result.validation_report.passed,
            validation_error_count,
        });

        for issue in &result.validation_report.issues {
            push_schema_inspector_issue(
                &mut report,
                schema_inspector_severity_from_tool(issue.severity),
                format!("package_{}", issue.code),
                format!("asset:{:032x}", result.asset_id),
                issue.message.clone(),
            );
        }
    }

    if let Some(module_registry) = module_registry {
        for module in &module_registry.modules {
            for requirement in &module.schema_requirements {
                *required_by_count
                    .entry(requirement.schema_name.clone())
                    .or_default() += 1;
            }
        }

        for module in &module_registry.modules {
            for requirement in &module.schema_requirements {
                let registered = schemas.and_then(|schemas| schemas.get(&requirement.schema_name));
                let migration_available = registered.is_some_and(|registered| {
                    registered.version.version < requirement.minimum_version
                        && schemas.is_some_and(|schemas| {
                            schemas
                                .migration_path(
                                    &requirement.schema_name,
                                    registered.version.version,
                                    requirement.minimum_version,
                                )
                                .is_some_and(|path| path.iter().all(|step| step.lossless))
                        })
                });
                let satisfied = registered.is_some_and(|registered| {
                    registered.version.version >= requirement.minimum_version || migration_available
                });

                report
                    .module_requirements
                    .push(SchemaRequirementDebugEntry {
                        requester: requirement.requester,
                        schema_name: requirement.schema_name.clone(),
                        minimum_version: requirement.minimum_version,
                        optional: requirement.optional,
                        registered_version: registered.map(|schema| schema.version.version),
                        owner: registered.map(|schema| schema.owner),
                        satisfied,
                        migration_available,
                        reason: requirement.reason.clone(),
                    });
            }
        }

        for issue in &module_registry.schema_compatibility.issues {
            push_schema_compatibility_issue(&mut report, "module_registry", issue);
        }
    }

    if let Some(schemas) = schemas {
        for step in &schemas.migration_plan().steps {
            *migration_count.entry(step.schema_name.clone()).or_default() += 1;
            report.migrations.push(SchemaMigrationDebugEntry {
                schema_name: step.schema_name.clone(),
                from_version: step.from_version,
                to_version: step.to_version,
                lossless: step.lossless,
                description: step.description.clone(),
            });
        }

        for registered in schemas.all() {
            owners.insert(registered.owner);
            report.registered_schemas.push(SchemaRegistryDebugEntry {
                schema_name: registered.version.name.to_string(),
                version: registered.version.version,
                owner: registered.owner,
                required_by_count: required_by_count
                    .get(registered.version.name)
                    .copied()
                    .unwrap_or_default(),
                package_count: package_count
                    .get(registered.version.name)
                    .copied()
                    .unwrap_or_default(),
                migration_step_count: migration_count
                    .get(registered.version.name)
                    .copied()
                    .unwrap_or_default(),
            });
        }
    }

    for frame_report in frame_reports {
        for issue in &frame_report.schema_compatibility.issues {
            push_schema_compatibility_issue(
                &mut report,
                format!("frame:{}", frame_report.frame_id),
                issue,
            );
        }
    }

    report.registered_schema_count = report.registered_schemas.len();
    report.module_requirement_count = report.module_requirements.len();
    report.package_schema_count = report.package_schemas.len();
    report.owner_count = owners.len();
    report.optional_requirement_count = report
        .module_requirements
        .iter()
        .filter(|requirement| requirement.optional)
        .count();
    report.compatibility_issue_count = report.issues.len();
    report.migration_step_count = report.migrations.len();
    report
        .registered_schemas
        .sort_by(|left, right| left.schema_name.cmp(&right.schema_name));
    report
        .module_requirements
        .sort_by_key(|requirement| (requirement.requester, requirement.schema_name.clone()));
    report
        .package_schemas
        .sort_by_key(|package| (package.schema_name.clone(), package.asset_id));
    report
}

fn push_schema_compatibility_issue(
    report: &mut SchemaInspectorReport,
    subject_prefix: impl Into<String>,
    issue: &ashfall_core::schema::SchemaCompatibilityIssue,
) {
    let subject_prefix = subject_prefix.into();
    push_schema_inspector_issue(
        report,
        schema_inspector_severity_from_schema(issue.severity),
        issue.code.clone(),
        format!(
            "{subject_prefix}:{}@v{}",
            issue.schema_name, issue.minimum_version
        ),
        issue.message.clone(),
    );
}

fn push_schema_inspector_issue(
    report: &mut SchemaInspectorReport,
    severity: SchemaInspectorSeverity,
    code: impl Into<String>,
    subject: impl Into<String>,
    message: impl Into<String>,
) {
    if severity == SchemaInspectorSeverity::Error {
        report.validation_error_count += 1;
    }
    report.issues.push(SchemaInspectorIssue {
        severity,
        code: code.into(),
        subject: subject.into(),
        message: message.into(),
    });
}

fn schema_inspector_severity_from_schema(
    severity: SchemaCompatibilitySeverity,
) -> SchemaInspectorSeverity {
    match severity {
        SchemaCompatibilitySeverity::Info => SchemaInspectorSeverity::Info,
        SchemaCompatibilitySeverity::Warning => SchemaInspectorSeverity::Warning,
        SchemaCompatibilitySeverity::Error => SchemaInspectorSeverity::Error,
    }
}

fn schema_inspector_severity_from_tool(severity: ToolIssueSeverity) -> SchemaInspectorSeverity {
    match severity {
        ToolIssueSeverity::Info => SchemaInspectorSeverity::Info,
        ToolIssueSeverity::Warning => SchemaInspectorSeverity::Warning,
        ToolIssueSeverity::Error => SchemaInspectorSeverity::Error,
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct ProfilingSample {
    pub frame: FrameId,
    pub system: SystemId,
    pub name: String,
    pub cpu_time_us: u64,
    pub gpu_time_us: Option<u64>,
    pub memory_bytes: u64,
    pub counter_value: Option<f64>,
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct ProfilerTimeline {
    pub samples: Vec<ProfilingSample>,
}

impl ProfilerTimeline {
    pub fn new(samples: Vec<ProfilingSample>) -> Self {
        Self { samples }
    }

    pub fn total_cpu_time_us(&self) -> u64 {
        self.samples.iter().map(|sample| sample.cpu_time_us).sum()
    }

    pub fn total_gpu_time_us(&self) -> u64 {
        self.samples
            .iter()
            .filter_map(|sample| sample.gpu_time_us)
            .sum()
    }

    pub fn peak_memory_bytes(&self) -> u64 {
        self.samples
            .iter()
            .map(|sample| sample.memory_bytes)
            .max()
            .unwrap_or(0)
    }

    pub fn samples_for_system(&self, system: SystemId) -> Vec<&ProfilingSample> {
        self.samples
            .iter()
            .filter(|sample| sample.system == system)
            .collect()
    }
}

