impl BuildAutomationStageKind {
    pub fn label(self) -> &'static str {
        match self {
            Self::RustCompileChecks => "Rust compile checks",
            Self::FormatAndLintChecks => "formatting and lint checks",
            Self::SchemaValidation => "schema validation",
            Self::ShaderSpirvValidation => "shader compile and SPIR-V validation",
            Self::AssetPackageValidation => "asset package validation",
            Self::CacheKeyTests => "cache key tests",
            Self::UnitTests => "unit tests",
            Self::ReplayTests => "replay tests",
            Self::ConformanceTests => "conformance tests",
            Self::GoldenSceneHeadlessRenders => "golden scene headless renders",
            Self::PerformanceBudgetSmokeTests => "performance budget smoke tests",
        }
    }

    pub fn mandate(self) -> &'static str {
        match self {
            Self::RustCompileChecks => {
                "CI must prove the Rust workspace compiles as the production runtime."
            }
            Self::FormatAndLintChecks => {
                "CI must run formatting and lint policy without hidden build-script bridges."
            }
            Self::SchemaValidation => {
                "CI must validate registered schemas, migrations, and shared interface coverage."
            }
            Self::ShaderSpirvValidation => {
                "CI must validate shader contracts, reflected layouts, and Vulkan-ready artifacts."
            }
            Self::AssetPackageValidation => {
                "CI must validate versioned asset packages, manifests, dependencies, and runtime inventory."
            }
            Self::CacheKeyTests => {
                "CI must prove generated caches are rebuildable from truth and not treated as primary truth."
            }
            Self::UnitTests => {
                "CI must keep component unit-test evidence connected to R&D acceptance gates."
            }
            Self::ReplayTests => {
                "CI must keep replay capture, deterministic fingerprints, and inspection exports available."
            }
            Self::ConformanceTests => {
                "CI must run conformance fixtures for cross-component outputs."
            }
            Self::GoldenSceneHeadlessRenders => {
                "CI must exercise golden scenes and compare gameplay output against reference evidence."
            }
            Self::PerformanceBudgetSmokeTests => {
                "CI must smoke-test CPU, GPU, memory, streaming, and failure-mode budget behavior."
            }
        }
    }

    pub fn subject(self) -> &'static str {
        match self {
            Self::RustCompileChecks => "rust_compile",
            Self::FormatAndLintChecks => "format_lint",
            Self::SchemaValidation => "schema_validation",
            Self::ShaderSpirvValidation => "shader_spirv",
            Self::AssetPackageValidation => "asset_package",
            Self::CacheKeyTests => "cache_keys",
            Self::UnitTests => "unit_tests",
            Self::ReplayTests => "replay_tests",
            Self::ConformanceTests => "conformance_tests",
            Self::GoldenSceneHeadlessRenders => "golden_scene_headless",
            Self::PerformanceBudgetSmokeTests => "performance_budget_smoke",
        }
    }

    pub fn is_rust_stage(self) -> bool {
        matches!(self, Self::RustCompileChecks | Self::FormatAndLintChecks)
    }

    pub fn is_shader_stage(self) -> bool {
        self == Self::ShaderSpirvValidation
    }

    pub fn is_validation_stage(self) -> bool {
        matches!(
            self,
            Self::SchemaValidation
                | Self::AssetPackageValidation
                | Self::CacheKeyTests
                | Self::UnitTests
                | Self::ReplayTests
                | Self::ConformanceTests
        )
    }

    pub fn is_scene_stage(self) -> bool {
        self == Self::GoldenSceneHeadlessRenders
    }

    pub fn is_performance_stage(self) -> bool {
        self == Self::PerformanceBudgetSmokeTests
    }
}

