#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct OpenResearchReport {
    pub packages: Vec<OpenResearchPackageReport>,
    pub issues: Vec<OpenResearchIssue>,
    pub package_count: usize,
    pub ready_package_count: usize,
    pub blocked_package_count: usize,
    pub signal_count: usize,
    pub passed_signal_count: usize,
    pub measured_prototype_count: usize,
    pub schema_proposal_count: usize,
    pub performance_data_count: usize,
    pub debug_view_count: usize,
    pub fallback_behavior_count: usize,
    pub golden_integration_plan_count: usize,
    pub issue_count: usize,
}

impl OpenResearchReport {
    pub fn is_empty(&self) -> bool {
        self.packages.is_empty()
    }

    pub fn passed(&self) -> bool {
        !self.is_empty()
            && self.package_count == self.ready_package_count
            && self
                .issues
                .iter()
                .all(|issue| issue.severity != ToolIssueSeverity::Error)
    }

    pub fn critical_issue_count(&self) -> usize {
        self.issues
            .iter()
            .filter(|issue| issue.severity == ToolIssueSeverity::Error)
            .count()
    }

    pub fn package(&self, kind: OpenResearchPackageKind) -> Option<&OpenResearchPackageReport> {
        self.packages.iter().find(|package| package.kind == kind)
    }
}

