#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum ProductionRisk {
    ScopeIsEnormous,
    PhotorealismOnlyGraphics,
    TexturelessSelfDestructive,
    PhysicsDestroysPerformance,
    HumansUncannyValley,
    AiHallucinatesOrBreaksWorld,
    VoiceAnnoyingOrInconsistent,
    RustOnlySlowsSystems,
    VulkanoFeatureGap,
    LooseInterfaces,
    ToolingDelayed,
    EngineClone,
    NoObjectiveQualityTarget,
}

impl ProductionRisk {
    pub fn label(self) -> &'static str {
        match self {
            Self::ScopeIsEnormous => "Risk: scope is enormous",
            Self::PhotorealismOnlyGraphics => "Risk: photorealism becomes only graphics",
            Self::TexturelessSelfDestructive => "Risk: textureless becomes self-destructive",
            Self::PhysicsDestroysPerformance => "Risk: physics destroys performance",
            Self::HumansUncannyValley => "Risk: humans fall into the uncanny valley",
            Self::AiHallucinatesOrBreaksWorld => "Risk: AI hallucinates or breaks the world",
            Self::VoiceAnnoyingOrInconsistent => "Risk: voice becomes annoying or inconsistent",
            Self::RustOnlySlowsSystems => "Risk: Rust-only slows certain systems",
            Self::VulkanoFeatureGap => "Risk: Vulkano feature gap",
            Self::LooseInterfaces => "Risk: interfaces are followed loosely",
            Self::ToolingDelayed => "Risk: tooling is delayed",
            Self::EngineClone => "Risk: engine becomes a clone",
            Self::NoObjectiveQualityTarget => "Risk: no objective quality target",
        }
    }

    pub fn problem(self) -> &'static str {
        match self {
            Self::ScopeIsEnormous => {
                "renderer, physics, materials, humans, AI, voice, and city streaming are each large projects"
            }
            Self::PhotorealismOnlyGraphics => {
                "a beautiful renderer can still look fake if motion, audio, AI, humans, or scale are wrong"
            }
            Self::TexturelessSelfDestructive => {
                "forbidding generated texture/cache sampling wastes performance and loses quality"
            }
            Self::PhysicsDestroysPerformance => {
                "fracture, fluids, gases, cloth, and heat can become too expensive"
            }
            Self::HumansUncannyValley => {
                "faces, eyes, skin, voice, and motion can look almost right but uncomfortable"
            }
            Self::AiHallucinatesOrBreaksWorld => {
                "generative AI can invent facts or mutate world state without validation"
            }
            Self::VoiceAnnoyingOrInconsistent => {
                "synthetic voice can become tiring, mistimed, or emotionally inconsistent"
            }
            Self::RustOnlySlowsSystems => {
                "some graphics, ML, and tools ecosystems are stronger outside Rust"
            }
            Self::VulkanoFeatureGap => {
                "advanced Vulkan rendering may need controls not exposed by a high-level wrapper"
            }
            Self::LooseInterfaces => {
                "teams can bypass schemas, pass unbounded data, or make private assumptions"
            }
            Self::ToolingDelayed => {
                "photoreal systems become impossible to debug without tools from the start"
            }
            Self::EngineClone => {
                "copying public feature names can hide weak data paths and weak architecture"
            }
            Self::NoObjectiveQualityTarget => {
                "quality arguments become subjective without measured reference scenes"
            }
        }
    }

    pub fn mitigation(self) -> &'static str {
        match self {
            Self::ScopeIsEnormous => {
                "prove a small alley vertical slice first with quality tiers and stable interfaces"
            }
            Self::PhotorealismOnlyGraphics => {
                "treat photorealism as the full chain of scale, lighting, geometry, materials, color, motion, humans, audio, AI, and consequence"
            }
            Self::TexturelessSelfDestructive => {
                "use physical/procedural truth plus generated cache pages as performance data"
            }
            Self::PhysicsDestroysPerformance => {
                "use simulation quality tiers, dormant summaries, GPU compute, hero-only detail, and strict budgets"
            }
            Self::HumansUncannyValley => {
                "treat humans as performance systems tested under harsh moving light"
            }
            Self::AiHallucinatesOrBreaksWorld => {
                "AI emits intents only; the engine validates actions and grounds dialogue in known facts"
            }
            Self::VoiceAnnoyingOrInconsistent => {
                "use persona tests, caching, emotion control, speech timing, fallback lines, and provenance"
            }
            Self::RustOnlySlowsSystems => {
                "keep runtime Rust-only, isolate tool-only exceptions, and build Rust-native caches/interfaces"
            }
            Self::VulkanoFeatureGap => {
                "keep Vulkan ownership inside GPU Services with stable component APIs and a Rust-owned escape hatch"
            }
            Self::LooseInterfaces => {
                "require schemas, validation, conformance tests, profiling, and review gates"
            }
            Self::ToolingDelayed => {
                "ship profiler, replay, labs, inspectors, and debug panels alongside each feature"
            }
            Self::EngineClone => {
                "prove the unique physical/procedural consequence loop instead of feature checkboxes"
            }
            Self::NoObjectiveQualityTarget => {
                "use reference renders, standard scenes, performance captures, and review checklists"
            }
        }
    }
}

