#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum ArchitectureContractRule {
    RustRuntime,
    VulkanGpuBackend,
    CentralizedGpuOwnership,
    SharedIdsUnitsSchemas,
    HandleBasedLargeData,
    SnapshotCommandDeltaEventFlow,
    NoSecretPrivateMutation,
    DeclaredBudgets,
    DebugViewsAndConformance,
    QualityTiersAndFailureBehavior,
    VersionedSchemas,
    TruthVersusCache,
}

impl ArchitectureContractRule {
    pub fn label(self) -> &'static str {
        match self {
            Self::RustRuntime => "Rust production runtime",
            Self::VulkanGpuBackend => "Vulkan production GPU backend",
            Self::CentralizedGpuOwnership => "centralized GPU ownership",
            Self::SharedIdsUnitsSchemas => "shared IDs, units, and schemas",
            Self::HandleBasedLargeData => "handle-based large data movement",
            Self::SnapshotCommandDeltaEventFlow => "snapshot, command, delta, and event flow",
            Self::NoSecretPrivateMutation => "no secret private-state mutation",
            Self::DeclaredBudgets => "declared performance budgets",
            Self::DebugViewsAndConformance => "debug views and conformance tests",
            Self::QualityTiersAndFailureBehavior => "quality tiers and failure behavior",
            Self::VersionedSchemas => "versioned schemas and migration behavior",
            Self::TruthVersusCache => "truth versus rebuildable cache",
        }
    }

    pub fn mandate(self) -> &'static str {
        match self {
            Self::RustRuntime => "production runtime components are Rust-owned engine modules",
            Self::VulkanGpuBackend => {
                "production graphics and compute run through Vulkan GPU services"
            }
            Self::CentralizedGpuOwnership => {
                "components submit GPU work to the shared GPU graph instead of owning global Vulkan state"
            }
            Self::SharedIdsUnitsSchemas => {
                "components use shared IDs, units, handles, and schema-owned contracts"
            }
            Self::HandleBasedLargeData => {
                "hot paths pass handles, pages, deltas, and GPU references instead of giant payload copies"
            }
            Self::SnapshotCommandDeltaEventFlow => {
                "systems read snapshots and write commands, deltas, and events into the ledger"
            }
            Self::NoSecretPrivateMutation => {
                "state changes remain inspectable through validation, source links, and deterministic replay"
            }
            Self::DeclaredBudgets => {
                "every component publishes CPU, GPU, memory, streaming, latency, and debug budget data"
            }
            Self::DebugViewsAndConformance => {
                "features ship with debug views, replay, validation, and automated acceptance gates"
            }
            Self::QualityTiersAndFailureBehavior => {
                "expensive systems expose quality tiers and deterministic fallback behavior"
            }
            Self::VersionedSchemas => {
                "schemas and packages are versioned, validated, and reject unsupported layouts"
            }
            Self::TruthVersusCache => {
                "saved truth is versioned while generated cache data remains rebuildable"
            }
        }
    }
}

