#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct GoldenSceneArtifacts {
    pub screenshot_count: usize,
    pub video_capture_count: usize,
    pub frame_capture_count: usize,
    pub timing_sample_count: usize,
    pub memory_sample_count: usize,
    pub streaming_capture_count: usize,
    pub debug_overlay_count: usize,
    pub reference_comparison_count: usize,
    pub pass_fail_recorded: bool,
    pub ci_runnable: bool,
}

impl GoldenSceneArtifacts {
    pub fn artifact_count(&self) -> usize {
        self.screenshot_count
            .saturating_add(self.video_capture_count)
            .saturating_add(self.frame_capture_count)
            .saturating_add(self.timing_sample_count)
            .saturating_add(self.memory_sample_count)
            .saturating_add(self.streaming_capture_count)
            .saturating_add(self.debug_overlay_count)
            .saturating_add(self.reference_comparison_count)
            .saturating_add(usize::from(self.pass_fail_recorded))
    }

    pub fn complete_for_ci(&self) -> bool {
        self.screenshot_count > 0
            && self.video_capture_count > 0
            && self.frame_capture_count > 0
            && self.timing_sample_count > 0
            && self.memory_sample_count > 0
            && self.streaming_capture_count > 0
            && self.debug_overlay_count > 0
            && self.reference_comparison_count > 0
            && self.pass_fail_recorded
            && self.ci_runnable
    }
}

