#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum RuntimeDependencyPolicyCheckKind {
    StaticRustWorkspace,
    RustFirstRuntimeDependencies,
    VulkanoIsolation,
    WinitPlatformBoundary,
    HiddenGpuBackendBoundary,
    RustOwnedShaderPipeline,
    RustAiVoiceLibraries,
    DynamicModuleBoundary,
    SchemaBackbone,
    ReproducibleAutomatedValidation,
}

impl RuntimeDependencyPolicyCheckKind {
    pub fn label(self) -> &'static str {
        match self {
            Self::StaticRustWorkspace => "static Rust workspace",
            Self::RustFirstRuntimeDependencies => "Rust-first runtime dependencies",
            Self::VulkanoIsolation => "Vulkano isolated inside GPU/rendering services",
            Self::WinitPlatformBoundary => "winit hidden behind the platform/window layer",
            Self::HiddenGpuBackendBoundary => {
                "no hidden production GPU backend in ML, UI, or helpers"
            }
            Self::RustOwnedShaderPipeline => "Rust-owned Vulkan shader pipeline",
            Self::RustAiVoiceLibraries => "Rust AI and voice dependency policy",
            Self::DynamicModuleBoundary => "stable dynamic module boundary",
            Self::SchemaBackbone => "schema crate backbone",
            Self::ReproducibleAutomatedValidation => "reproducible automated validation",
        }
    }

    pub fn mandate(self) -> &'static str {
        match self {
            Self::StaticRustWorkspace => {
                "early production uses one Rust workspace with separate static component crates"
            }
            Self::RustFirstRuntimeDependencies => {
                "runtime dependencies are Rust-first or explicitly isolated platform/driver boundaries"
            }
            Self::VulkanoIsolation => {
                "Vulkano may exist inside GPU/rendering services but must not leak across component APIs"
            }
            Self::WinitPlatformBoundary => {
                "winit may handle windows/input behind an engine platform layer, not gameplay APIs"
            }
            Self::HiddenGpuBackendBoundary => {
                "ML, UI, and helper crates must not create a second production GPU device or backend"
            }
            Self::RustOwnedShaderPipeline => {
                "shader source, generated artifacts, contracts, and validation stay reproducible through Rust-owned Vulkan tooling"
            }
            Self::RustAiVoiceLibraries => {
                "AI and voice use Rust libraries with bounded runtime policy instead of non-Rust engines"
            }
            Self::DynamicModuleBoundary => {
                "dynamic plugins use versioned C-compatible ABI tables and never expose Rust trait objects"
            }
            Self::SchemaBackbone => {
                "shared IDs, units, schemas, commands, events, packages, and fixtures remain centralized"
            }
            Self::ReproducibleAutomatedValidation => {
                "dependency choices remain testable through deterministic validation and conformance"
            }
        }
    }
}

