impl ReferenceAnchorKind {
    pub fn label(self) -> &'static str {
        match self {
            Self::NaniteVirtualizedGeometry => "Nanite-like virtualized geometry anchor",
            Self::LumenDynamicLighting => "Lumen-like dynamic GI/reflection anchor",
            Self::VirtualShadowMaps => "virtual shadow maps anchor",
            Self::SubstrateStyleMaterials => "Substrate/OpenPBR material anchor",
            Self::WorldPartitionStreaming => "World Partition streaming anchor",
            Self::MetahumanDigitalHumans => "MetaHuman-class digital human anchor",
            Self::VulkanRustPlatform => "Vulkan and Rust platform anchor",
            Self::OpenMaterialSceneStandards => "OpenPBR, MaterialX, and USD scene anchor",
            Self::PhysicsResearchFamilies => "real-time physics research anchor",
            Self::UniqueAshfallDirection => "unique Ashfall physical-procedural direction",
        }
    }

    pub fn purpose(self) -> &'static str {
        match self {
            Self::NaniteVirtualizedGeometry => {
                "prove dense visible geometry is represented through clusters, culling, indirect draws, and streaming feedback"
            }
            Self::LumenDynamicLighting => {
                "prove dynamic lighting and reflection goals are tied to gameplay/reference rendering evidence"
            }
            Self::VirtualShadowMaps => {
                "prove high-detail shadowing uses tracked virtual pages, dirty page lists, and lighting reads"
            }
            Self::SubstrateStyleMaterials => {
                "prove material richness comes from stateful physical material programs and generated caches"
            }
            Self::WorldPartitionStreaming => {
                "prove city state is divided into streamable cells with renderer, gameplay, and persistence visibility"
            }
            Self::MetahumanDigitalHumans => {
                "prove humans are treated as full performance objects with skin, eyes, hair, cloth, voice, and face sync"
            }
            Self::VulkanRustPlatform => {
                "prove runtime platform choices follow Rust, Vulkan, Vulkano, winit, AI, and voice dependency policy"
            }
            Self::OpenMaterialSceneStandards => {
                "prove material and scene schemas remain portable, versioned, and validation-backed"
            }
            Self::PhysicsResearchFamilies => {
                "prove physical consequence systems cover constraints, fracture, fluids, gas, and bounded simulation LOD"
            }
            Self::UniqueAshfallDirection => {
                "prove the project is not cloning a public engine but combining physical material truth, consequence, AI memory, voice, and city state"
            }
        }
    }

    pub fn is_unreal_class(self) -> bool {
        matches!(
            self,
            Self::NaniteVirtualizedGeometry
                | Self::LumenDynamicLighting
                | Self::VirtualShadowMaps
                | Self::SubstrateStyleMaterials
                | Self::WorldPartitionStreaming
                | Self::MetahumanDigitalHumans
        )
    }
}

