#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ExecutiveSanityAuditReport {
    pub checks: Vec<ExecutiveSanityCheck>,
    pub issues: Vec<ExecutiveSanityIssue>,
    pub check_count: usize,
    pub passed_check_count: usize,
    pub blocked_check_count: usize,
    pub signal_count: usize,
    pub passed_signal_count: usize,
    pub runtime_platform_signal_count: usize,
    pub photoreal_chain_signal_count: usize,
    pub physical_loop_signal_count: usize,
    pub production_readiness_signal_count: usize,
    pub measured_artifact_count: usize,
    pub issue_count: usize,
}

impl ExecutiveSanityAuditReport {
    pub fn is_empty(&self) -> bool {
        self.checks.is_empty()
    }

    pub fn passed(&self) -> bool {
        !self.is_empty()
            && self.check_count == self.passed_check_count
            && self
                .issues
                .iter()
                .all(|issue| issue.severity != ToolIssueSeverity::Error)
    }

    pub fn check(&self, kind: ExecutiveSanityCheckKind) -> Option<&ExecutiveSanityCheck> {
        self.checks.iter().find(|check| check.kind == kind)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ExecutiveSanityCheck {
    pub kind: ExecutiveSanityCheckKind,
    pub label: String,
    pub mandate: String,
    pub passed: bool,
    pub signal_count: usize,
    pub passed_signal_count: usize,
    pub signals: Vec<ExecutiveSanitySignal>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum ExecutiveSanityCheckKind {
    RustVulkanRuntimeFoundation,
    PhotorealChain,
    TruthCacheBoundary,
    PhysicalProceduralLoop,
    CrossSystemConsequenceMemory,
    ProductionAcceptanceGates,
    ToolsReplayValidation,
    VerticalSliceScope,
}

impl ExecutiveSanityCheckKind {
    pub fn label(self) -> &'static str {
        match self {
            Self::RustVulkanRuntimeFoundation => "Rust/Vulkan runtime foundation",
            Self::PhotorealChain => "full photorealism chain",
            Self::TruthCacheBoundary => "truth versus generated cache boundary",
            Self::PhysicalProceduralLoop => "physical-procedural consequence loop",
            Self::CrossSystemConsequenceMemory => "cross-system consequence memory",
            Self::ProductionAcceptanceGates => "production acceptance gates",
            Self::ToolsReplayValidation => "tools, replay, and validation as engine systems",
            Self::VerticalSliceScope => "small vertical slice scope control",
        }
    }

    pub fn mandate(self) -> &'static str {
        match self {
            Self::RustVulkanRuntimeFoundation => {
                "Rust owns runtime code, Vulkan/GPU Services owns GPU work, and platform wrappers stay isolated"
            }
            Self::PhotorealChain => {
                "photoreal quality is proved as a chain of scale, geometry, lighting, materials, color, motion, humans, sound, AI, and persistence"
            }
            Self::TruthCacheBoundary => {
                "stable physical/procedural truth survives while generated texture, geometry, lighting, speech, and navigation data remain rebuildable caches"
            }
            Self::PhysicalProceduralLoop => {
                "physical events modify material state and propagate through renderer, audio, AI, story, city state, and persistence"
            }
            Self::CrossSystemConsequenceMemory => {
                "world consequences are recorded as shared events and remembered by AI, story, city, audio, and replay systems"
            }
            Self::ProductionAcceptanceGates => {
                "features declare budgets, quality tiers, failure behavior, stress scenes, reference comparisons, and readiness gates"
            }
            Self::ToolsReplayValidation => {
                "debug tools, replay inspection, schema inspection, and conformance are first-class runtime outputs"
            }
            Self::VerticalSliceScope => {
                "the rainy alley slice remains the objective integration target before the project expands"
            }
        }
    }

    fn is_runtime_platform(self) -> bool {
        matches!(self, Self::RustVulkanRuntimeFoundation)
    }

    fn is_photoreal_chain(self) -> bool {
        matches!(self, Self::PhotorealChain)
    }

    fn is_physical_loop(self) -> bool {
        matches!(
            self,
            Self::TruthCacheBoundary
                | Self::PhysicalProceduralLoop
                | Self::CrossSystemConsequenceMemory
        )
    }

    fn is_production_readiness(self) -> bool {
        matches!(
            self,
            Self::ProductionAcceptanceGates
                | Self::ToolsReplayValidation
                | Self::VerticalSliceScope
        )
    }
}

