#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ReplayInspectionSession {
    pub selected_frame: Option<ReplayFrameInspection>,
    pub visible_events: Vec<ReplayEventInspectionRow>,
    pub filters: ReplayInspectionFilters,
    pub exports: Vec<ReplayInspectionExport>,
    pub issues: Vec<ReplayInspectionIssue>,
    pub total_frame_count: usize,
    pub visible_frame_count: usize,
    pub visible_event_count: usize,
}

impl ReplayInspectionSession {
    pub fn is_empty(&self) -> bool {
        self.selected_frame.is_none() && self.visible_events.is_empty()
    }

    pub fn critical_issue_count(&self) -> usize {
        self.issues
            .iter()
            .filter(|issue| issue.severity == ReplayDebuggerIssueSeverity::Error)
            .count()
    }

    pub fn events_for_frame(&self, frame: FrameId) -> Vec<&ReplayEventInspectionRow> {
        self.visible_events
            .iter()
            .filter(|event| event.frame == frame)
            .collect()
    }

    pub fn export(&self, format: ReplayInspectionExportFormat) -> Option<&ReplayInspectionExport> {
        self.exports.iter().find(|export| export.format == format)
    }
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ReplayInspectionFilters {
    pub event_kind: Option<String>,
    pub category: Option<ReplayEventCategory>,
    pub require_source_link: bool,
    pub frame_window: Option<ReplayFrameWindow>,
}

impl ReplayInspectionFilters {
    pub fn with_event_kind(mut self, event_kind: impl Into<String>) -> Self {
        self.event_kind = Some(event_kind.into());
        self
    }

    pub fn with_category(mut self, category: ReplayEventCategory) -> Self {
        self.category = Some(category);
        self
    }

    pub fn requiring_source_link(mut self) -> Self {
        self.require_source_link = true;
        self
    }

    pub fn with_frame_window(mut self, start: FrameId, end: FrameId) -> Self {
        let (start, end) = if start <= end {
            (start, end)
        } else {
            (end, start)
        };
        self.frame_window = Some(ReplayFrameWindow { start, end });
        self
    }
}

