fn human_bundle_request_targets_hero(request: &HumanBundleRequestDebug) -> bool {
    request.runtime_bundle
        && human_bundle_reason_contains(
            request,
            &[
                "human", "face", "facial", "hair", "eye", "eyes", "body", "rig",
            ],
        )
}

fn human_bundle_request_targets_body(request: &HumanBundleRequestDebug) -> bool {
    request.runtime_bundle && human_bundle_reason_contains(request, &["body", "rig", "clothing"])
}

fn human_bundle_reason_contains(request: &HumanBundleRequestDebug, needles: &[&str]) -> bool {
    let reason = request.reason.to_ascii_lowercase();
    needles.iter().any(|needle| reason.contains(needle))
}

fn unique_human_bundle_quality_count(human_lab: &HumanLabReport) -> usize {
    let mut qualities = Vec::new();
    for request in &human_lab.bundle_requests {
        if !qualities.contains(&request.requested_quality) {
            qualities.push(request.requested_quality);
        }
    }
    qualities.len()
}

fn human_acceptance_gate(
    kind: HumanAcceptanceGateKind,
    passed: bool,
    evidence: impl Into<String>,
) -> HumanAcceptanceGate {
    HumanAcceptanceGate {
        kind,
        label: kind.label().to_string(),
        passed,
        evidence: evidence.into(),
    }
}

