fn golden_scene_metrics_from_capture(
    capture: &ReplayDebugCapture,
    kind: GoldenSceneKind,
) -> GoldenSceneMetrics {
    let total_cpu_time_us = capture
        .performance_heatmap
        .total_cpu_time_us
        .max(capture.profiler.total_cpu_time_us());
    let total_gpu_time_us = capture
        .performance_heatmap
        .total_module_gpu_time_us
        .max((capture.performance_heatmap.peak_frame_gpu_wall_milliseconds * 1_000.0) as u64);
    let peak_vram_bytes = capture
        .performance_heatmap
        .total_gpu_resource_bytes
        .max(capture.profiler.peak_memory_bytes())
        .max(
            capture
                .frame_graphs
                .iter()
                .map(|graph| graph.transient_memory_bytes)
                .max()
                .unwrap_or(0),
        );
    let total_streaming_bytes = capture
        .performance_heatmap
        .total_streaming_bytes
        .max(capture.streaming_debugger.total_bytes_streamed)
        .max(capture.city_streaming.requested_streaming_bytes);
    let dropped_frame_count = capture.performance_heatmap.critical_budget_pressure_count;
    let temporal_stability_score_basis_points = if capture.frame_graphs.iter().any(|graph| {
        graph.temporal_stability.reconstruction_active() && graph.temporal_stability.passed()
    }) {
        10_000
    } else if capture
        .frame_graphs
        .iter()
        .any(|graph| graph.temporal_stability.reconstruction_active())
    {
        5_000
    } else {
        0
    };
    let allocation_count = capture
        .frame_graphs
        .iter()
        .map(|graph| graph.declared_resource_count)
        .sum::<usize>();
    let visible_pop_count = capture.streaming_debugger.critical_issue_count()
        + capture
            .frame_graphs
            .iter()
            .map(|graph| graph.temporal_stability.issue_count)
            .sum::<usize>();
    let reference_comparison_score_basis_points = if capture.reference_comparison.passed() {
        10_000
    } else if capture.reference_comparison.comparison_pass_count > 0 {
        5_000
    } else {
        0
    };
    let replay_hash = golden_scene_replay_hash(capture);

    GoldenSceneMetrics {
        cpu_time_us: total_cpu_time_us,
        gpu_time_us: total_gpu_time_us,
        vram_bytes: peak_vram_bytes,
        streaming_bytes: total_streaming_bytes,
        dropped_frame_count,
        temporal_stability_score_basis_points,
        allocation_count,
        visible_pop_count,
        reference_comparison_score_basis_points,
        replay_hash,
        manual_art_review_note: format!(
            "{} carries automatic v6 proxy evidence; final production acceptance still requires human art review notes",
            kind.label()
        ),
    }
}

fn golden_scene_artifacts_from_capture(
    capture: &ReplayDebugCapture,
    metrics: &GoldenSceneMetrics,
) -> GoldenSceneArtifacts {
    let screenshot_count = capture
        .frame_graphs
        .iter()
        .filter(|graph| {
            graph.render_outputs.screenshot_target_present
                && graph.render_outputs.capture_writes_screenshot
        })
        .count();
    let video_capture_count = capture
        .frame_graphs
        .iter()
        .filter(|graph| {
            graph.render_outputs.cinematic_target_present
                && graph.render_outputs.capture_writes_cinematic
        })
        .count()
        .max(usize::from(
            capture
                .replay_inspection
                .export(ReplayInspectionExportFormat::TimelineCsv)
                .is_some()
                && !capture.replay.frame_summaries.is_empty(),
        ));
    let frame_capture_count = capture
        .frame_graphs
        .iter()
        .filter(|graph| {
            graph.render_outputs.frame_capture_manifest_present
                && graph.render_outputs.capture_export_pass_present
                && graph.render_outputs.capture_writes_manifest
        })
        .count();
    let timing_sample_count = capture
        .profiler
        .samples
        .len()
        .saturating_add(capture.performance_heatmap.frame_count)
        .saturating_add(usize::from(metrics.cpu_time_us > 0))
        .saturating_add(usize::from(metrics.gpu_time_us > 0));
    let memory_sample_count = capture
        .profiler
        .samples
        .iter()
        .filter(|sample| sample.memory_bytes > 0)
        .count()
        .saturating_add(usize::from(metrics.vram_bytes > 0))
        .saturating_add(usize::from(
            capture.performance_heatmap.total_gpu_resource_bytes > 0,
        ));
    let streaming_capture_count = capture
        .streaming_debugger
        .frame_count
        .saturating_add(capture.streaming_debugger.request_event_count)
        .saturating_add(capture.streaming_debugger.resident_event_count)
        .saturating_add(capture.city_streaming.cell_count)
        .saturating_add(usize::from(metrics.streaming_bytes > 0));
    let debug_overlay_count = capture
        .frame_graphs
        .iter()
        .map(|graph| {
            graph
                .debug_label_count
                .saturating_add(usize::from(graph.render_outputs.picking_buffer_present))
                .saturating_add(usize::from(graph.render_outputs.picking_readback_present))
                .saturating_add(usize::from(
                    graph.render_outputs.perception_entity_id_buffer_present,
                ))
                .saturating_add(usize::from(
                    graph.render_outputs.perception_material_id_buffer_present,
                ))
                .saturating_add(usize::from(
                    graph.render_outputs.perception_depth_pyramid_present,
                ))
                .saturating_add(usize::from(
                    graph.render_outputs.perception_hazard_buffer_present,
                ))
                .saturating_add(usize::from(graph.render_outputs.picking_pass_present))
                .saturating_add(usize::from(graph.render_outputs.perception_pass_present))
        })
        .sum::<usize>();
    let reference_comparison_count = capture.reference_comparison.comparison_pass_count;
    let pass_fail_recorded = true;
    let ci_runnable = metrics.replay_hash != 0
        && !capture.replay_inspection.exports.is_empty()
        && screenshot_count > 0
        && video_capture_count > 0
        && frame_capture_count > 0
        && timing_sample_count > 0
        && memory_sample_count > 0
        && streaming_capture_count > 0
        && debug_overlay_count > 0
        && reference_comparison_count > 0;

    GoldenSceneArtifacts {
        screenshot_count,
        video_capture_count,
        frame_capture_count,
        timing_sample_count,
        memory_sample_count,
        streaming_capture_count,
        debug_overlay_count,
        reference_comparison_count,
        pass_fail_recorded,
        ci_runnable,
    }
}

fn golden_scene_replay_hash(capture: &ReplayDebugCapture) -> u128 {
    let mut parts = Vec::new();
    for frame in &capture.replay.frame_summaries {
        parts.push(
            format!(
                "{:?}:{:?}:{}:{}",
                frame.frame_id, frame.tick, frame.queued_command_count, frame.event_count
            )
            .into_bytes(),
        );
        for command in &frame.queued_command_fingerprints {
            parts.push(command.as_bytes().to_vec());
        }
        for event in &frame.event_fingerprints {
            parts.push(event.kind_label.as_bytes().to_vec());
            parts.push(event.kind_fingerprint.as_bytes().to_vec());
        }
    }
    for export in &capture.replay_inspection.exports {
        parts.push(export.deterministic_hash.to_le_bytes().to_vec());
    }

    if parts.is_empty() {
        0
    } else {
        stable_hash128(parts.iter().map(Vec::as_slice))
    }
}

fn golden_scene_measurement_evidence(
    metrics: &GoldenSceneMetrics,
    replay_ready: bool,
    reference_ready: bool,
) -> String {
    format!(
        "{} CPU us, {} GPU us, {} VRAM bytes, {} streaming bytes, {} allocation record(s), {} dropped frame(s), {} visible pop(s), temporal {} bp, reference {} bp, replay hash {}, replay ready {}, reference ready {}, note present {}",
        metrics.cpu_time_us,
        metrics.gpu_time_us,
        metrics.vram_bytes,
        metrics.streaming_bytes,
        metrics.allocation_count,
        metrics.dropped_frame_count,
        metrics.visible_pop_count,
        metrics.temporal_stability_score_basis_points,
        metrics.reference_comparison_score_basis_points,
        metrics.replay_hash,
        replay_ready,
        reference_ready,
        !metrics.manual_art_review_note.is_empty()
    )
}

fn golden_scene_check(
    kind: GoldenSceneKind,
    metrics: GoldenSceneMetrics,
    artifacts: GoldenSceneArtifacts,
    signals: Vec<GoldenSceneSignal>,
) -> GoldenSceneCheck {
    let signal_count = signals.len();
    let passed_signal_count = signals.iter().filter(|signal| signal.passed).count();

    GoldenSceneCheck {
        kind,
        label: kind.label().to_string(),
        purpose: kind.purpose().to_string(),
        passed: signal_count > 0
            && passed_signal_count == signal_count
            && artifacts.complete_for_ci(),
        signal_count,
        passed_signal_count,
        metrics,
        artifacts,
        signals,
    }
}

fn golden_scene_signal(
    label: impl Into<String>,
    passed: bool,
    evidence: impl Into<String>,
) -> GoldenSceneSignal {
    GoldenSceneSignal {
        label: label.into(),
        passed,
        evidence: evidence.into(),
    }
}

fn golden_scene_report_from_scenes(scenes: Vec<GoldenSceneCheck>) -> GoldenSceneReport {
    let mut issues = Vec::new();
    for scene in &scenes {
        for signal in &scene.signals {
            if !signal.passed {
                issues.push(GoldenSceneIssue {
                    severity: ToolIssueSeverity::Error,
                    code: "golden_scene_signal_failed".to_string(),
                    subject: scene.label.clone(),
                    message: format!("{}: {}", signal.label, signal.evidence),
                });
            }
        }
        if !scene.artifacts.complete_for_ci() {
            issues.push(GoldenSceneIssue {
                severity: ToolIssueSeverity::Error,
                code: "golden_scene_artifacts_incomplete".to_string(),
                subject: scene.label.clone(),
                message: format!(
                    "{} screenshot(s), {} video capture(s), {} frame capture(s), {} timing sample(s), {} memory sample(s), {} streaming capture(s), {} debug overlay item(s), {} reference comparison(s), pass/fail {}, CI runnable {}",
                    scene.artifacts.screenshot_count,
                    scene.artifacts.video_capture_count,
                    scene.artifacts.frame_capture_count,
                    scene.artifacts.timing_sample_count,
                    scene.artifacts.memory_sample_count,
                    scene.artifacts.streaming_capture_count,
                    scene.artifacts.debug_overlay_count,
                    scene.artifacts.reference_comparison_count,
                    scene.artifacts.pass_fail_recorded,
                    scene.artifacts.ci_runnable
                ),
            });
        }
    }

    let scene_count = scenes.len();
    let passed_scene_count = scenes.iter().filter(|scene| scene.passed).count();
    let blocked_scene_count = scene_count.saturating_sub(passed_scene_count);
    let signal_count = scenes.iter().map(|scene| scene.signal_count).sum();
    let passed_signal_count = scenes.iter().map(|scene| scene.passed_signal_count).sum();
    let artifact_count = scenes
        .iter()
        .map(|scene| scene.artifacts.artifact_count())
        .sum();
    let screenshot_count = scenes
        .iter()
        .map(|scene| scene.artifacts.screenshot_count)
        .sum();
    let video_capture_count = scenes
        .iter()
        .map(|scene| scene.artifacts.video_capture_count)
        .sum();
    let frame_capture_count = scenes
        .iter()
        .map(|scene| scene.artifacts.frame_capture_count)
        .sum();
    let timing_sample_count = scenes
        .iter()
        .map(|scene| scene.artifacts.timing_sample_count)
        .sum();
    let memory_sample_count = scenes
        .iter()
        .map(|scene| scene.artifacts.memory_sample_count)
        .sum();
    let streaming_capture_count = scenes
        .iter()
        .map(|scene| scene.artifacts.streaming_capture_count)
        .sum();
    let debug_overlay_count = scenes
        .iter()
        .map(|scene| scene.artifacts.debug_overlay_count)
        .sum();
    let reference_comparison_count = scenes
        .iter()
        .map(|scene| scene.artifacts.reference_comparison_count)
        .sum();
    let ci_ready_scene_count = scenes
        .iter()
        .filter(|scene| scene.artifacts.complete_for_ci())
        .count();
    let issue_count = issues.len();
    let total_cpu_time_us = scenes
        .iter()
        .map(|scene| scene.metrics.cpu_time_us)
        .max()
        .unwrap_or(0);
    let total_gpu_time_us = scenes
        .iter()
        .map(|scene| scene.metrics.gpu_time_us)
        .max()
        .unwrap_or(0);
    let peak_vram_bytes = scenes
        .iter()
        .map(|scene| scene.metrics.vram_bytes)
        .max()
        .unwrap_or(0);
    let total_streaming_bytes = scenes
        .iter()
        .map(|scene| scene.metrics.streaming_bytes)
        .max()
        .unwrap_or(0);
    let replay_hash = scenes
        .iter()
        .map(|scene| scene.metrics.replay_hash)
        .find(|hash| *hash != 0)
        .unwrap_or(0);

    GoldenSceneReport {
        scenes,
        issues,
        scene_count,
        passed_scene_count,
        blocked_scene_count,
        signal_count,
        passed_signal_count,
        artifact_count,
        screenshot_count,
        video_capture_count,
        frame_capture_count,
        timing_sample_count,
        memory_sample_count,
        streaming_capture_count,
        debug_overlay_count,
        reference_comparison_count,
        ci_ready_scene_count,
        issue_count,
        total_cpu_time_us,
        total_gpu_time_us,
        peak_vram_bytes,
        total_streaming_bytes,
        replay_hash,
    }
}

