fn interface_schema_section(
    kind: InterfaceSchemaSectionKind,
    signals: Vec<InterfaceSchemaSignal>,
) -> InterfaceSchemaSectionReport {
    let signal_count = signals.len();
    let passed_signal_count = signals.iter().filter(|signal| signal.passed).count();

    InterfaceSchemaSectionReport {
        kind,
        label: kind.label().to_string(),
        contract: kind.contract().to_string(),
        passed: signal_count > 0 && signal_count == passed_signal_count,
        signal_count,
        passed_signal_count,
        signals,
    }
}

fn interface_schema_signal(
    label: impl Into<String>,
    passed: bool,
    evidence: impl Into<String>,
) -> InterfaceSchemaSignal {
    InterfaceSchemaSignal {
        label: label.into(),
        passed,
        evidence: evidence.into(),
    }
}

#[derive(Clone, Copy, Debug, Default)]
struct InterfaceSchemaCoverageCounts {
    core_id_alias_count: usize,
    source_file_count: usize,
    package_contract_count: usize,
    world_contract_count: usize,
    material_contract_count: usize,
    gpu_contract_count: usize,
    rendering_contract_count: usize,
    simulation_contract_count: usize,
    ai_voice_contract_count: usize,
    city_contract_count: usize,
    conformance_contract_count: usize,
    runtime_schema_count: usize,
}

fn interface_schema_coverage_report_from_sections(
    counts: InterfaceSchemaCoverageCounts,
    sections: Vec<InterfaceSchemaSectionReport>,
) -> InterfaceSchemaCoverageReport {
    let mut issues = Vec::new();
    for section in &sections {
        for signal in &section.signals {
            if !signal.passed {
                issues.push(InterfaceSchemaIssue {
                    severity: ToolIssueSeverity::Error,
                    code: "interface_schema_signal_failed".to_string(),
                    subject: section.label.clone(),
                    message: format!("{}: {}", signal.label, signal.evidence),
                });
            }
        }
    }

    let section_count = sections.len();
    let passed_section_count = sections.iter().filter(|section| section.passed).count();
    let blocked_section_count = section_count.saturating_sub(passed_section_count);
    let signal_count = sections.iter().map(|section| section.signal_count).sum();
    let passed_signal_count = sections
        .iter()
        .map(|section| section.passed_signal_count)
        .sum();
    let issue_count = issues.len();

    InterfaceSchemaCoverageReport {
        sections,
        issues,
        section_count,
        passed_section_count,
        blocked_section_count,
        signal_count,
        passed_signal_count,
        core_id_alias_count: counts.core_id_alias_count,
        source_file_count: counts.source_file_count,
        package_contract_count: counts.package_contract_count,
        world_contract_count: counts.world_contract_count,
        material_contract_count: counts.material_contract_count,
        gpu_contract_count: counts.gpu_contract_count,
        rendering_contract_count: counts.rendering_contract_count,
        simulation_contract_count: counts.simulation_contract_count,
        ai_voice_contract_count: counts.ai_voice_contract_count,
        city_contract_count: counts.city_contract_count,
        conformance_contract_count: counts.conformance_contract_count,
        runtime_schema_count: counts.runtime_schema_count,
        issue_count,
    }
}

