fn executive_sanity_check(
    kind: ExecutiveSanityCheckKind,
    signals: Vec<ExecutiveSanitySignal>,
) -> ExecutiveSanityCheck {
    let signal_count = signals.len();
    let passed_signal_count = signals.iter().filter(|signal| signal.passed).count();

    ExecutiveSanityCheck {
        kind,
        label: kind.label().to_string(),
        mandate: kind.mandate().to_string(),
        passed: signal_count > 0 && signal_count == passed_signal_count,
        signal_count,
        passed_signal_count,
        signals,
    }
}

fn executive_sanity_signal(
    label: impl Into<String>,
    passed: bool,
    evidence: impl Into<String>,
) -> ExecutiveSanitySignal {
    ExecutiveSanitySignal {
        label: label.into(),
        passed,
        evidence: evidence.into(),
    }
}

fn executive_sanity_report_from_checks(
    measured_artifact_count: usize,
    checks: Vec<ExecutiveSanityCheck>,
) -> ExecutiveSanityAuditReport {
    let mut issues = Vec::new();
    for check in &checks {
        for signal in &check.signals {
            if !signal.passed {
                issues.push(ExecutiveSanityIssue {
                    severity: ToolIssueSeverity::Error,
                    code: "executive_sanity_signal_failed".to_string(),
                    subject: check.label.clone(),
                    message: format!("{}: {}", signal.label, signal.evidence),
                });
            }
        }
    }

    let check_count = checks.len();
    let passed_check_count = checks.iter().filter(|check| check.passed).count();
    let blocked_check_count = check_count.saturating_sub(passed_check_count);
    let signal_count = checks.iter().map(|check| check.signal_count).sum();
    let passed_signal_count = checks.iter().map(|check| check.passed_signal_count).sum();
    let runtime_platform_signal_count = checks
        .iter()
        .filter(|check| check.kind.is_runtime_platform())
        .map(|check| check.passed_signal_count)
        .sum();
    let photoreal_chain_signal_count = checks
        .iter()
        .filter(|check| check.kind.is_photoreal_chain())
        .map(|check| check.passed_signal_count)
        .sum();
    let physical_loop_signal_count = checks
        .iter()
        .filter(|check| check.kind.is_physical_loop())
        .map(|check| check.passed_signal_count)
        .sum();
    let production_readiness_signal_count = checks
        .iter()
        .filter(|check| check.kind.is_production_readiness())
        .map(|check| check.passed_signal_count)
        .sum();
    let issue_count = issues.len();

    ExecutiveSanityAuditReport {
        checks,
        issues,
        check_count,
        passed_check_count,
        blocked_check_count,
        signal_count,
        passed_signal_count,
        runtime_platform_signal_count,
        photoreal_chain_signal_count,
        physical_loop_signal_count,
        production_readiness_signal_count,
        measured_artifact_count,
        issue_count,
    }
}

fn count_present_schema_patterns(patterns: &[(&str, &str)]) -> usize {
    patterns
        .iter()
        .filter(|(source, pattern)| source.contains(pattern))
        .count()
}

