fn team_handoff_ai_story_checks(capture: &ReplayDebugCapture) -> Vec<TeamHandoffSignal> {
    vec![
        team_handoff_signal(
            "action validation and rejection of impossible actions",
            !capture.ai_story.is_empty()
                && capture.ai_story.accepted_intent_count > 0
                && capture.ai_story.rejected_intent_count > 0,
            format!(
                "{} accepted intent(s), {} rejected intent(s)",
                capture.ai_story.accepted_intent_count, capture.ai_story.rejected_intent_count
            ),
        ),
        team_handoff_signal(
            "memory update and event-ledger reading",
            !capture.ai_story.agent_memories.is_empty()
                && !capture.ai_story.agent_decisions.is_empty()
                && capture
                    .ai_story
                    .agent_decisions
                    .iter()
                    .any(|decision| decision.source_event.is_some()),
            format!(
                "{} memory item(s), {} decision trace(s)",
                capture.ai_story.agent_memories.len(),
                capture.ai_story.agent_decisions.len()
            ),
        ),
        team_handoff_signal(
            "grounded dialogue and conversation replay",
            capture.ai_story.conversation_replay.passed
                && !capture.ai_story.dialogue_grounding.is_empty()
                && capture
                    .ai_story
                    .dialogue_grounding
                    .iter()
                    .all(|line| line.grounded),
            format!(
                "{} grounded line(s), {} ungrounded line(s)",
                capture.ai_story.conversation_replay.grounded_line_count,
                capture.ai_story.conversation_replay.ungrounded_line_count
            ),
        ),
        team_handoff_signal(
            "relationship, faction, rumor, and opportunity state",
            !capture.ai_story.faction_events.is_empty()
                && capture.ai_story.rumor_network.passed()
                && capture.ai_story.opportunity_network.passed(),
            format!(
                "{} faction event(s), {} rumor pass(es), {} opportunity pass(es)",
                capture.ai_story.faction_events.len(),
                capture.ai_story.rumor_network.propagation_pass_count,
                capture.ai_story.opportunity_network.index_pass_count
            ),
        ),
    ]
}

fn team_handoff_voice_audio_checks(capture: &ReplayDebugCapture) -> Vec<TeamHandoffSignal> {
    vec![
        team_handoff_signal(
            "speech request/result timing",
            !capture.voice_audio.is_empty()
                && capture.voice_audio.synced_speech_count > 0
                && capture.voice_audio.unsynced_speech_count == 0,
            format!(
                "{} synced speech event(s), {} unsynced speech event(s)",
                capture.voice_audio.synced_speech_count, capture.voice_audio.unsynced_speech_count
            ),
        ),
        team_handoff_signal(
            "voice provenance and cache policy",
            capture.voice_audio.performance.passed
                && capture.voice_audio.performance_capture_count
                    == capture.voice_audio.validated_performance_capture_count,
            format!(
                "{} validated capture(s) of {}",
                capture.voice_audio.validated_performance_capture_count,
                capture.voice_audio.performance_capture_count
            ),
        ),
        team_handoff_signal(
            "spatial and material-aware audio response",
            capture.voice_audio.material_aware_sound_count > 0
                && capture.voice_audio.physics_sound_count > 0
                && capture.voice_audio.peak_active_sound_count > 0,
            format!(
                "{} material-aware sound(s), {} physics sound(s), {} peak active",
                capture.voice_audio.material_aware_sound_count,
                capture.voice_audio.physics_sound_count,
                capture.voice_audio.peak_active_sound_count
            ),
        ),
        team_handoff_signal(
            "long-listening comfort",
            capture.voice_audio.critical_issue_count() == 0 && capture.voice_audio.comfort.passed,
            format!(
                "comfort {:.2}, {} comfort issue(s), {} critical issue(s)",
                capture.voice_audio.comfort.projected_ten_minute_score,
                capture.voice_audio.comfort_issue_count(),
                capture.voice_audio.critical_issue_count()
            ),
        ),
    ]
}

