fn team_handoff_frame_graphs_pass(capture: &ReplayDebugCapture) -> bool {
    !capture.frame_graphs.is_empty()
        && capture
            .frame_graphs
            .iter()
            .all(|frame_graph| frame_graph.passed())
}

fn team_handoff_signals_pass(signals: &[TeamHandoffSignal]) -> bool {
    !signals.is_empty() && signals.iter().all(|signal| signal.passed)
}

fn team_handoff_signal(
    label: impl Into<String>,
    passed: bool,
    evidence: impl Into<String>,
) -> TeamHandoffSignal {
    TeamHandoffSignal {
        label: label.into(),
        passed,
        evidence: evidence.into(),
    }
}

pub fn replay_debugger_report_from_capture(capture: &ReplayCapture) -> ReplayDebuggerReport {
    let mut report = ReplayDebuggerReport::default();
    let mut kind_accumulators = BTreeMap::<String, ReplayEventKindAccumulator>::new();

    for frame in &capture.frame_summaries {
        let unique_event_kinds = frame
            .event_fingerprints
            .iter()
            .map(|event| event.kind_label.clone())
            .collect::<BTreeSet<_>>();
        let source_link_count = frame
            .event_fingerprints
            .iter()
            .filter(|event| replay_event_has_source_link(event))
            .count();

        report.command_count += frame.queued_command_count;
        report.event_count += frame.event_count;
        report.source_link_count += source_link_count;
        report.deterministic_fingerprint_count +=
            frame.queued_command_fingerprints.len() + frame.event_fingerprints.len();

        if frame.queued_command_count == 0 {
            push_replay_debugger_issue(
                &mut report,
                ReplayDebuggerIssueSeverity::Warning,
                ReplayDebuggerIssueCategory::CaptureCoverage,
                "frame_without_queued_commands",
                format!("frame:{}", frame.frame_id),
                "debug replay frame has no queued command fingerprint to explain player/system input",
            );
        }
        if frame.event_count == 0 {
            push_replay_debugger_issue(
                &mut report,
                ReplayDebuggerIssueSeverity::Error,
                ReplayDebuggerIssueCategory::CaptureCoverage,
                "frame_without_events",
                format!("frame:{}", frame.frame_id),
                "debug replay frame must include event fingerprints",
            );
        }

        report.frames.push(ReplayFrameDebug {
            frame: frame.frame_id,
            tick: frame.tick,
            queued_command_count: frame.queued_command_count,
            event_count: frame.event_count,
            unique_event_kind_count: unique_event_kinds.len(),
            source_link_count,
            first_event_kind: frame
                .event_fingerprints
                .first()
                .map(|event| event.kind_label.clone()),
        });

        for event in &frame.event_fingerprints {
            replay_debugger_count_event(&mut report, event);
            let accumulator = kind_accumulators
                .entry(event.kind_label.clone())
                .or_default();
            accumulator.count += 1;
            accumulator.frames.insert(frame.frame_id);
            accumulator.evidence_count += event.evidence_count;
            accumulator.narrative_tag_count += event.narrative_tags.len();
            accumulator.source_link_count += usize::from(replay_event_has_source_link(event));
        }
    }

    report.frame_count = report.frames.len();
    report.unique_event_kind_count = kind_accumulators.len();
    report.event_kinds = kind_accumulators
        .into_iter()
        .map(|(kind_label, accumulator)| ReplayEventKindDebug {
            kind_label,
            count: accumulator.count,
            frame_count: accumulator.frames.len(),
            evidence_count: accumulator.evidence_count,
            narrative_tag_count: accumulator.narrative_tag_count,
            source_link_count: accumulator.source_link_count,
        })
        .collect();
    report.event_kinds.sort_by(|left, right| {
        right
            .count
            .cmp(&left.count)
            .then_with(|| left.kind_label.cmp(&right.kind_label))
    });
    report.modes = replay_debug_modes(&report);

    if report.frame_count == 0 {
        push_replay_debugger_issue(
            &mut report,
            ReplayDebuggerIssueSeverity::Error,
            ReplayDebuggerIssueCategory::CaptureCoverage,
            "missing_replay_debug_frames",
            "replay",
            "debug report needs at least one captured replay frame",
        );
    }
    if report.deterministic_fingerprint_count == 0 {
        push_replay_debugger_issue(
            &mut report,
            ReplayDebuggerIssueSeverity::Error,
            ReplayDebuggerIssueCategory::FingerprintCoverage,
            "missing_replay_fingerprints",
            "replay",
            "debug report needs deterministic command or event fingerprints",
        );
    }

    report
}

#[derive(Default)]
struct ReplayEventKindAccumulator {
    count: usize,
    frames: BTreeSet<FrameId>,
    evidence_count: usize,
    narrative_tag_count: usize,
    source_link_count: usize,
}

fn replay_debugger_count_event(report: &mut ReplayDebuggerReport, event: &ReplayEventFingerprint) {
    if replay_event_is_physics(&event.kind_label) {
        report.physics_event_count += 1;
    }
    if replay_event_is_material(&event.kind_label) {
        report.material_event_count += 1;
    }
    if replay_event_is_ai_story(&event.kind_label) {
        report.ai_story_event_count += 1;
    }
    if replay_event_is_voice(&event.kind_label, &event.kind_fingerprint) {
        report.voice_event_count += 1;
    }
    if replay_event_is_asset(&event.kind_label) {
        report.asset_event_count += 1;
    }
}

fn replay_debug_modes(report: &ReplayDebuggerReport) -> Vec<ReplayDebugModeStatus> {
    [
        (
            ReplayDebugMode::FullLocal,
            report.frame_count > 0 && report.command_count > 0 && report.event_count > 0,
            report.frame_count,
            report.event_count,
        ),
        (
            ReplayDebugMode::ReducedEvent,
            report.event_count > 0,
            report.frame_count,
            report.event_count,
        ),
        (
            ReplayDebugMode::PhysicsOnly,
            report.physics_event_count > 0,
            report.frame_count,
            report.physics_event_count,
        ),
        (
            ReplayDebugMode::AiConversation,
            report.ai_story_event_count > 0 || report.voice_event_count > 0,
            report.frame_count,
            report.ai_story_event_count + report.voice_event_count,
        ),
        (
            ReplayDebugMode::RenderingCapture,
            report.asset_event_count > 0 || report.material_event_count > 0,
            report.frame_count,
            report.asset_event_count + report.material_event_count,
        ),
    ]
    .into_iter()
    .map(
        |(mode, available, frame_count, event_count)| ReplayDebugModeStatus {
            mode,
            available,
            frame_count,
            event_count,
        },
    )
    .collect()
}

fn replay_event_has_source_link(event: &ReplayEventFingerprint) -> bool {
    matches!(
        event.kind_label.as_str(),
        "AgentDecisionExplained"
            | "AgentIntentProposed"
            | "AgentMemoryUpdated"
            | "NpcHeardSound"
            | "NpcWitnessedCrime"
            | "SecurityAlertRaised"
            | "SurveillanceIncreased"
    ) || event.kind_fingerprint.contains("source_event: Some(")
}

fn replay_event_is_physics(kind_label: &str) -> bool {
    matches!(
        kind_label,
        "ForceApplied"
            | "DamageApplied"
            | "MeshReplaced"
            | "MaterialStateChanged"
            | "GlassWallFractured"
            | "MetalBent"
            | "FlexibleConstraintResolved"
            | "PowerTransformerOverheated"
            | "StreetFlooded"
            | "ToxicGasReleased"
            | "SoundEmitted"
    )
}

fn replay_event_is_material(kind_label: &str) -> bool {
    matches!(kind_label, "MaterialStateChanged")
}

fn replay_event_is_ai_story(kind_label: &str) -> bool {
    matches!(
        kind_label,
        "AgentDecisionExplained"
            | "AgentIntentProposed"
            | "AgentMemoryUpdated"
            | "NpcHeardSound"
            | "NpcWitnessedCrime"
            | "StoryEventEmitted"
            | "SecurityAlertRaised"
            | "FactionReputationChanged"
            | "SurveillanceIncreased"
            | "PlayerIdentityExposed"
    )
}

fn replay_event_is_voice(kind_label: &str, kind_fingerprint: &str) -> bool {
    matches!(
        kind_label,
        "DialogueEmitted"
            | "VoiceLineSpoken"
            | "SpeechSynthesized"
            | "FacialAnimationApplied"
            | "AudioFrameMixed"
    ) || (kind_label == "SoundEmitted" && kind_fingerprint.contains("VoiceSpeech"))
}

fn replay_event_is_asset(kind_label: &str) -> bool {
    matches!(
        kind_label,
        "AssetStreamingRequested" | "AssetBecameResident"
    )
}

fn push_replay_debugger_issue(
    report: &mut ReplayDebuggerReport,
    severity: ReplayDebuggerIssueSeverity,
    category: ReplayDebuggerIssueCategory,
    code: impl Into<String>,
    subject: impl Into<String>,
    message: impl Into<String>,
) {
    report.issues.push(ReplayDebuggerIssue {
        severity,
        category,
        code: code.into(),
        subject: subject.into(),
        message: message.into(),
    });
}

pub fn replay_inspection_session_from_capture(
    capture: &ReplayCapture,
    filters: &ReplayInspectionFilters,
    selected_frame: Option<FrameId>,
) -> ReplayInspectionSession {
    let mut session = ReplayInspectionSession {
        filters: filters.clone(),
        total_frame_count: capture.len(),
        ..ReplayInspectionSession::default()
    };

    if capture.is_empty() {
        push_replay_inspection_issue(
            &mut session,
            ReplayDebuggerIssueSeverity::Error,
            "empty_replay_capture",
            "replay",
            "replay inspection needs at least one captured frame",
        );
        return session;
    }

    let candidate_frames = capture
        .frame_summaries
        .iter()
        .enumerate()
        .filter(|(_, frame)| replay_inspection_frame_matches(filters, frame))
        .collect::<Vec<_>>();

    if candidate_frames.is_empty() {
        push_replay_inspection_issue(
            &mut session,
            ReplayDebuggerIssueSeverity::Warning,
            "frame_window_matched_no_frames",
            "filters",
            "replay inspection frame window matched no captured frames",
        );
        return session;
    }

    let selected_index = selected_frame
        .and_then(|frame_id| {
            candidate_frames
                .iter()
                .position(|(_, frame)| frame.frame_id == frame_id)
        })
        .unwrap_or(0);

    if selected_frame.is_some_and(|frame_id| {
        !candidate_frames
            .iter()
            .any(|(_, frame)| frame.frame_id == frame_id)
    }) {
        push_replay_inspection_issue(
            &mut session,
            ReplayDebuggerIssueSeverity::Warning,
            "selected_frame_not_visible",
            format!("frame:{}", selected_frame.unwrap_or_default()),
            "requested replay inspection frame was not available after filtering",
        );
    }

    let (_, selected_summary) = candidate_frames[selected_index];
    let visible_events = candidate_frames
        .iter()
        .flat_map(|(_, frame)| replay_inspection_rows_for_frame(filters, frame))
        .collect::<Vec<_>>();
    let visible_frames = visible_events
        .iter()
        .map(|event| event.frame)
        .collect::<BTreeSet<_>>();
    let selected_visible_event_count = visible_events
        .iter()
        .filter(|event| event.frame == selected_summary.frame_id)
        .count();

    session.visible_frame_count = visible_frames.len();
    session.visible_event_count = visible_events.len();
    session.selected_frame = Some(ReplayFrameInspection {
        index: selected_index,
        frame: selected_summary.frame_id,
        tick: selected_summary.tick,
        queued_command_count: selected_summary.queued_command_count,
        event_count: selected_summary.event_count,
        visible_event_count: selected_visible_event_count,
        deterministic_fingerprint_count: selected_summary.queued_command_fingerprints.len()
            + selected_summary.event_fingerprints.len(),
        previous_frame: selected_index.checked_sub(1).map(|index| {
            let (_, frame) = candidate_frames[index];
            frame.frame_id
        }),
        next_frame: candidate_frames
            .get(selected_index + 1)
            .map(|(_, frame)| frame.frame_id),
    });
    session.visible_events = visible_events;

    if session.visible_events.is_empty() {
        push_replay_inspection_issue(
            &mut session,
            ReplayDebuggerIssueSeverity::Warning,
            "filters_matched_no_events",
            "filters",
            "replay inspection filters matched frames but no events",
        );
    } else if selected_visible_event_count == 0 {
        push_replay_inspection_issue(
            &mut session,
            ReplayDebuggerIssueSeverity::Info,
            "selected_frame_has_no_visible_events",
            format!("frame:{}", selected_summary.frame_id),
            "selected replay frame has no events visible under the active filters",
        );
    }

    session.exports =
        replay_inspection_exports(&candidate_frames, &session.visible_events, filters);
    session
}

fn replay_inspection_frame_matches(
    filters: &ReplayInspectionFilters,
    frame: &ReplayFrameSummary,
) -> bool {
    filters
        .frame_window
        .is_none_or(|window| (window.start..=window.end).contains(&frame.frame_id))
}

fn replay_inspection_rows_for_frame(
    filters: &ReplayInspectionFilters,
    frame: &ReplayFrameSummary,
) -> Vec<ReplayEventInspectionRow> {
    frame
        .event_fingerprints
        .iter()
        .enumerate()
        .filter(|(_, event)| replay_inspection_event_matches(filters, event))
        .map(|(index, event)| ReplayEventInspectionRow {
            index,
            frame: frame.frame_id,
            tick: frame.tick,
            event_id: event.event_id,
            kind_label: event.kind_label.clone(),
            category: replay_event_category(event),
            has_source_link: replay_event_has_source_link(event),
            evidence_count: event.evidence_count,
            narrative_tag_count: event.narrative_tags.len(),
            actor_count: event.actors.len(),
            fingerprint: event.kind_fingerprint.clone(),
        })
        .collect()
}

fn replay_inspection_event_matches(
    filters: &ReplayInspectionFilters,
    event: &ReplayEventFingerprint,
) -> bool {
    if filters
        .event_kind
        .as_deref()
        .is_some_and(|event_kind| event.kind_label != event_kind)
    {
        return false;
    }
    if filters
        .category
        .is_some_and(|category| replay_event_category(event) != category)
    {
        return false;
    }
    if filters.require_source_link && !replay_event_has_source_link(event) {
        return false;
    }

    true
}

fn replay_event_category(event: &ReplayEventFingerprint) -> ReplayEventCategory {
    if replay_event_is_material(&event.kind_label) {
        ReplayEventCategory::Material
    } else if replay_event_is_voice(&event.kind_label, &event.kind_fingerprint) {
        ReplayEventCategory::VoiceAudio
    } else if replay_event_is_asset(&event.kind_label) {
        ReplayEventCategory::AssetStreaming
    } else if replay_event_is_ai_story(&event.kind_label) {
        ReplayEventCategory::AiStory
    } else if replay_event_is_physics(&event.kind_label) {
        ReplayEventCategory::Physics
    } else if matches!(
        event.kind_label.as_str(),
        "TransformChanged" | "AgentStateChanged" | "NavigationMoveBlocked" | "AssetBecameResident"
    ) {
        ReplayEventCategory::WorldState
    } else {
        ReplayEventCategory::Unknown
    }
}

fn replay_inspection_exports(
    frames: &[(usize, &ReplayFrameSummary)],
    events: &[ReplayEventInspectionRow],
    filters: &ReplayInspectionFilters,
) -> Vec<ReplayInspectionExport> {
    if events.is_empty() {
        return Vec::new();
    }

    [
        (
            ReplayInspectionExportFormat::DebugText,
            "debug.txt",
            "human-readable replay debugger text",
        ),
        (
            ReplayInspectionExportFormat::EventJsonLines,
            "events.jsonl",
            "event fingerprint rows as json lines",
        ),
        (
            ReplayInspectionExportFormat::TimelineCsv,
            "timeline.csv",
            "timeline rows for spreadsheet inspection",
        ),
    ]
    .into_iter()
    .map(|(format, extension, label)| ReplayInspectionExport {
        format,
        target: replay_inspection_export_target(extension, label, frames),
        frame_count: frames.len(),
        event_count: events.len(),
        deterministic_hash: replay_inspection_export_hash(format, frames, events, filters),
    })
    .collect()
}

fn replay_inspection_export_target(
    extension: &str,
    label: &str,
    frames: &[(usize, &ReplayFrameSummary)],
) -> String {
    let first_frame = frames
        .first()
        .map(|(_, frame)| frame.frame_id)
        .unwrap_or_default();
    let last_frame = frames
        .last()
        .map(|(_, frame)| frame.frame_id)
        .unwrap_or(first_frame);
    format!("replay://frames/{first_frame}-{last_frame}/{extension} ({label})")
}

fn replay_inspection_export_hash(
    format: ReplayInspectionExportFormat,
    frames: &[(usize, &ReplayFrameSummary)],
    events: &[ReplayEventInspectionRow],
    filters: &ReplayInspectionFilters,
) -> u128 {
    let mut parts = vec![
        format!("{format:?}").into_bytes(),
        format!("{filters:?}").into_bytes(),
    ];
    for (_, frame) in frames {
        parts.push(format!("frame:{}:{}", frame.frame_id, frame.tick).into_bytes());
        for command in &frame.queued_command_fingerprints {
            parts.push(command.as_bytes().to_vec());
        }
    }
    for event in events {
        parts.push(format!("event:{}:{}", event.frame, event.event_id).into_bytes());
        parts.push(event.kind_label.as_bytes().to_vec());
        parts.push(event.fingerprint.as_bytes().to_vec());
    }

    stable_hash128(parts.iter().map(Vec::as_slice))
}

fn push_replay_inspection_issue(
    session: &mut ReplayInspectionSession,
    severity: ReplayDebuggerIssueSeverity,
    code: impl Into<String>,
    subject: impl Into<String>,
    message: impl Into<String>,
) {
    session.issues.push(ReplayInspectionIssue {
        severity,
        code: code.into(),
        subject: subject.into(),
        message: message.into(),
    });
}

pub fn ai_story_inspector_report_from_frames(
    frame_reports: &[FrameReport],
) -> AiStoryInspectorReport {
    let events = frame_reports
        .iter()
        .flat_map(|report| report.events.iter())
        .collect::<Vec<_>>();
    let mut report = ai_story_inspector_report_from_events(events);
    report.rumor_network = ai_rumor_network_debug_from_frames(frame_reports);
    report.opportunity_network = ai_story_opportunity_network_debug_from_frames(frame_reports);
    report
}

pub fn ai_story_inspector_report_from_events<'a>(
    events: impl IntoIterator<Item = &'a WorldEvent>,
) -> AiStoryInspectorReport {
    let mut report = AiStoryInspectorReport::default();
    let mut summaries = BTreeMap::<EntityId, AiAgentSummaryDebug>::new();
    let mut memory_context = BTreeMap::<EntityId, Vec<AiAgentMemoryDebug>>::new();
    let mut decision_context = BTreeMap::<EntityId, Vec<AiAgentDecisionDebug>>::new();
    let mut intent_context = BTreeMap::<EntityId, Vec<AiAgentIntentDebug>>::new();
    let mut conversation_speakers = BTreeSet::<EntityId>::new();
    let mut conversation_source_events = BTreeSet::<WorldEventId>::new();
    let mut voice_line_count = 0usize;
    let mut speech_synthesis_count = 0usize;
    let mut face_sync_count = 0usize;

    for event in events {
        match &event.kind {
            WorldEventKind::AgentDecisionExplained {
                agent,
                source_event,
                goal,
                selected_lod,
                available_actions,
                accepted_actions,
                rejected_actions,
                reasons,
            } => {
                report.agent_decisions.push(AiAgentDecisionDebug {
                    agent: *agent,
                    source_event: *source_event,
                    goal: goal.clone(),
                    selected_lod: selected_lod.clone(),
                    available_actions: available_actions.clone(),
                    accepted_actions: accepted_actions.clone(),
                    rejected_actions: rejected_actions.clone(),
                    reasons: reasons.clone(),
                });
                if let Some(decision) = report.agent_decisions.last().cloned() {
                    decision_context.entry(*agent).or_default().push(decision);
                }
                let summary = summaries
                    .entry(*agent)
                    .or_insert_with(|| AiAgentSummaryDebug {
                        agent: *agent,
                        decision_count: 0,
                        memory_count: 0,
                        accepted_intent_count: 0,
                        rejected_intent_count: 0,
                        latest_goal: None,
                    });
                summary.decision_count += 1;
                summary.latest_goal = Some(goal.clone());
                report.rejected_intent_count += rejected_actions.len();
                summary.rejected_intent_count += rejected_actions.len();
            }
            WorldEventKind::AgentMemoryUpdated {
                agent,
                source_event,
                memory_kind,
                content,
                importance,
                confidence,
            } => {
                report.agent_memories.push(AiAgentMemoryDebug {
                    agent: *agent,
                    source_event: *source_event,
                    memory_kind: memory_kind.clone(),
                    content: content.clone(),
                    importance: *importance,
                    confidence: *confidence,
                });
                if let Some(memory) = report.agent_memories.last().cloned() {
                    memory_context.entry(*agent).or_default().push(memory);
                }
                let summary = summaries
                    .entry(*agent)
                    .or_insert_with(|| AiAgentSummaryDebug {
                        agent: *agent,
                        decision_count: 0,
                        memory_count: 0,
                        accepted_intent_count: 0,
                        rejected_intent_count: 0,
                        latest_goal: None,
                    });
                summary.memory_count += 1;
            }
            WorldEventKind::AgentIntentProposed {
                agent,
                action,
                source_event,
                validation_passed,
            } => {
                report.agent_intents.push(AiAgentIntentDebug {
                    agent: *agent,
                    action: action.clone(),
                    source_event: *source_event,
                    validation_passed: *validation_passed,
                });
                if let Some(intent) = report.agent_intents.last().cloned() {
                    intent_context.entry(*agent).or_default().push(intent);
                }
                let summary = summaries
                    .entry(*agent)
                    .or_insert_with(|| AiAgentSummaryDebug {
                        agent: *agent,
                        decision_count: 0,
                        memory_count: 0,
                        accepted_intent_count: 0,
                        rejected_intent_count: 0,
                        latest_goal: None,
                    });
                if *validation_passed {
                    report.accepted_intent_count += 1;
                    summary.accepted_intent_count += 1;
                } else {
                    report.rejected_intent_count += 1;
                    summary.rejected_intent_count += 1;
                }
            }
            WorldEventKind::DialogueEmitted {
                speaker,
                target,
                text,
                emotion,
                voice_persona,
            } => {
                report.dialogues.push(AiDialogueDebug {
                    speaker: *speaker,
                    target: *target,
                    text: text.clone(),
                    voice_persona: *voice_persona,
                    urgency: emotion.urgency,
                    fear: emotion.fear,
                    anger: emotion.anger,
                });
                let grounding = ai_dialogue_grounding_debug(AiDialogueGroundingInput {
                    speaker: *speaker,
                    target: *target,
                    text,
                    voice_persona: *voice_persona,
                    emotion,
                    memories: memory_context
                        .get(speaker)
                        .map(Vec::as_slice)
                        .unwrap_or(&[]),
                    decisions: decision_context
                        .get(speaker)
                        .map(Vec::as_slice)
                        .unwrap_or(&[]),
                    intents: intent_context
                        .get(speaker)
                        .map(Vec::as_slice)
                        .unwrap_or(&[]),
                });
                conversation_speakers.insert(*speaker);
                conversation_source_events.extend(grounding.source_events.iter().copied());
                report.dialogue_grounding.push(grounding);
            }
            WorldEventKind::StoryEventEmitted { label } => {
                report.story_events.push(AiStoryEventDebug {
                    label: label.clone(),
                });
            }
            WorldEventKind::FactionReputationChanged {
                faction,
                subject,
                delta,
                reason,
            } => report
                .faction_events
                .push(AiFactionEventDebug::ReputationChanged {
                    faction: *faction,
                    subject: *subject,
                    delta: *delta,
                    reason: reason.clone(),
                }),
            WorldEventKind::SecurityAlertRaised {
                faction,
                source_event,
                threat,
                severity,
            } => report
                .faction_events
                .push(AiFactionEventDebug::SecurityAlert {
                    faction: *faction,
                    source_event: *source_event,
                    threat: *threat,
                    severity: *severity,
                }),
            WorldEventKind::SurveillanceIncreased {
                location,
                source_event,
                amount,
            } => report
                .faction_events
                .push(AiFactionEventDebug::SurveillanceIncreased {
                    location: *location,
                    source_event: *source_event,
                    amount: *amount,
                }),
            WorldEventKind::NpcHeardSound {
                listener,
                event,
                source_entity,
                confidence,
            } => report.sound_reports.push(AiSoundReportDebug {
                listener: *listener,
                event: *event,
                source_entity: *source_entity,
                confidence: *confidence,
            }),
            WorldEventKind::NpcWitnessedCrime { witness, event } => {
                report.witness_reports.push(AiWitnessReportDebug {
                    witness: *witness,
                    event: *event,
                });
            }
            WorldEventKind::VoiceLineSpoken { .. } => {
                voice_line_count += 1;
            }
            WorldEventKind::SpeechSynthesized { .. } => {
                speech_synthesis_count += 1;
            }
            WorldEventKind::FacialAnimationApplied { .. } => {
                face_sync_count += 1;
            }
            _ => {}
        }
    }

    report.agent_summaries = summaries.into_values().collect();
    report.conversation_replay = ai_conversation_replay_debug(
        &report.dialogue_grounding,
        conversation_speakers.len(),
        conversation_source_events.len(),
        voice_line_count,
        speech_synthesis_count,
        face_sync_count,
    );
    report
}

struct AiDialogueGroundingInput<'a> {
    speaker: EntityId,
    target: Option<EntityId>,
    text: &'a str,
    voice_persona: Option<VoicePersonaId>,
    emotion: &'a ashfall_core::core::EmotionState,
    memories: &'a [AiAgentMemoryDebug],
    decisions: &'a [AiAgentDecisionDebug],
    intents: &'a [AiAgentIntentDebug],
}

fn ai_dialogue_grounding_debug(input: AiDialogueGroundingInput<'_>) -> AiDialogueGroundingDebug {
    let mut source_events = BTreeSet::<WorldEventId>::new();
    for memory in input.memories {
        if let Some(source_event) = memory.source_event {
            source_events.insert(source_event);
        }
    }
    for decision in input.decisions {
        if let Some(source_event) = decision.source_event {
            source_events.insert(source_event);
        }
    }
    let linked_intent_count = input
        .intents
        .iter()
        .filter(|intent| {
            if let Some(source_event) = intent.source_event {
                source_events.insert(source_event);
            }
            intent.validation_passed
        })
        .count();

    let source_events = source_events.into_iter().collect::<Vec<_>>();
    let unsupported_claim_count = if source_events.is_empty() {
        dialogue_grounding_claim_count(input.text)
    } else {
        0
    };
    let confidence_floor = input
        .memories
        .iter()
        .map(|memory| memory.confidence)
        .filter(|confidence| confidence.is_finite())
        .reduce(f32::min)
        .unwrap_or(0.0);

    AiDialogueGroundingDebug {
        speaker: input.speaker,
        target: input.target,
        text_preview: truncate_debug_text(input.text, 96),
        voice_persona: input.voice_persona,
        source_events,
        linked_memory_count: input.memories.len(),
        linked_decision_count: input.decisions.len(),
        linked_intent_count,
        confidence_floor,
        emotional_load: input.emotion.urgency + input.emotion.fear + input.emotion.anger,
        unsupported_claim_count,
        grounded: unsupported_claim_count == 0,
    }
}

fn dialogue_grounding_claim_count(text: &str) -> usize {
    let lower = text.to_ascii_lowercase();
    [
        "saw", "witness", "heard", "security", "gas", "clear", "report", "crime", "alarm", "flood",
        "power",
    ]
    .into_iter()
    .filter(|term| lower.contains(term))
    .count()
}

fn ai_conversation_replay_debug(
    dialogue_grounding: &[AiDialogueGroundingDebug],
    unique_speaker_count: usize,
    linked_source_event_count: usize,
    voice_line_count: usize,
    speech_synthesis_count: usize,
    face_sync_count: usize,
) -> AiConversationReplayDebug {
    let line_count = dialogue_grounding.len();
    let grounded_line_count = dialogue_grounding
        .iter()
        .filter(|grounding| grounding.grounded)
        .count();
    let ungrounded_line_count = line_count.saturating_sub(grounded_line_count);
    let memory_context_count = dialogue_grounding
        .iter()
        .map(|grounding| grounding.linked_memory_count)
        .sum();
    let decision_context_count = dialogue_grounding
        .iter()
        .map(|grounding| grounding.linked_decision_count)
        .sum();

    AiConversationReplayDebug {
        line_count,
        grounded_line_count,
        ungrounded_line_count,
        unique_speaker_count,
        linked_source_event_count,
        memory_context_count,
        decision_context_count,
        voice_line_count,
        speech_synthesis_count,
        face_sync_count,
        fully_voiced_line_count: line_count.min(voice_line_count).min(speech_synthesis_count),
        replay_available: line_count > 0,
        passed: line_count == 0 || ungrounded_line_count == 0,
    }
}

fn ai_rumor_network_debug_from_frames(frame_reports: &[FrameReport]) -> AiRumorNetworkDebug {
    let mut debug = AiRumorNetworkDebug::default();

    for frame in frame_reports {
        debug.propagation_pass_count += frame
            .gpu_passes
            .iter()
            .filter(|pass| pass.name == "story_rumor_propagation")
            .count();

        for resource in &frame.gpu_registered_resource_usage {
            if resource.owner != Some(55) {
                continue;
            }
            match resource.label.as_str() {
                "story grounded rumor table" => {
                    debug.grounded_table_resource_count += 1;
                    debug.estimated_rumor_bytes = debug
                        .estimated_rumor_bytes
                        .saturating_add(resource.byte_len);
                }
                "story rumor propagation buffer" => {
                    debug.propagation_buffer_resource_count += 1;
                    debug.estimated_rumor_bytes = debug
                        .estimated_rumor_bytes
                        .saturating_add(resource.byte_len);
                }
                _ => {}
            }
        }

        for pipeline in &frame.gpu_pipeline_report.pipelines {
            if pipeline.label != "story_rumor_propagation" {
                continue;
            }
            debug.pipeline_available = true;
            debug.knowledge_grounding_define |= pipeline
                .permutation_defines
                .iter()
                .any(|define| define == "KNOWLEDGE_GROUNDING");
            debug.no_global_knowledge_define |= pipeline
                .permutation_defines
                .iter()
                .any(|define| define == "NO_GLOBAL_KNOWLEDGE");
            debug.incomplete_rumor_define |= pipeline
                .permutation_defines
                .iter()
                .any(|define| define == "INCOMPLETE_RUMORS");
        }
    }

    debug.viewer_available = debug.propagation_pass_count > 0
        && debug.grounded_table_resource_count > 0
        && debug.propagation_buffer_resource_count > 0;
    debug
}

fn ai_story_opportunity_network_debug_from_frames(
    frame_reports: &[FrameReport],
) -> AiStoryOpportunityNetworkDebug {
    let mut debug = AiStoryOpportunityNetworkDebug::default();

    for frame in frame_reports {
        debug.index_pass_count += frame
            .gpu_passes
            .iter()
            .filter(|pass| pass.name == "story_grounded_opportunity_index")
            .count();

        for resource in &frame.gpu_registered_resource_usage {
            if resource.owner != Some(55) {
                continue;
            }
            match resource.label.as_str() {
                "story director opportunity table" => {
                    debug.opportunity_table_resource_count += 1;
                    debug.estimated_opportunity_bytes = debug
                        .estimated_opportunity_bytes
                        .saturating_add(resource.byte_len);
                }
                "story grounded opportunity index" => {
                    debug.opportunity_index_resource_count += 1;
                    debug.estimated_opportunity_bytes = debug
                        .estimated_opportunity_bytes
                        .saturating_add(resource.byte_len);
                }
                _ => {}
            }
        }

        for pipeline in &frame.gpu_pipeline_report.pipelines {
            if pipeline.label != "story_grounded_opportunity_index" {
                continue;
            }
            debug.pipeline_available = true;
            debug.grounded_opportunity_define |= pipeline
                .permutation_defines
                .iter()
                .any(|define| define == "GROUNDED_OPPORTUNITIES");
            debug.director_opportunities_define |= pipeline
                .permutation_defines
                .iter()
                .any(|define| define == "DIRECTOR_OPPORTUNITIES");
            debug.world_validated_offers_define |= pipeline
                .permutation_defines
                .iter()
                .any(|define| define == "WORLD_VALIDATED_OFFERS");
        }
    }

    debug.viewer_available = debug.index_pass_count > 0
        && debug.opportunity_table_resource_count > 0
        && debug.opportunity_index_resource_count > 0;
    debug
}

pub fn voice_audio_lab_report_from_frames(frame_reports: &[FrameReport]) -> VoiceAudioLabReport {
    let events = frame_reports
        .iter()
        .flat_map(|report| report.events.iter())
        .collect::<Vec<_>>();
    let generated_captures = generated_performance_capture_clips_from_voice_events(&events);
    if generated_captures.is_empty() {
        return voice_audio_lab_report_from_events(events);
    }

    let mut report = voice_audio_lab_report_from_events(events.iter().copied());
    add_performance_capture_clips_to_report(
        &mut report,
        generated_captures
            .iter()
            .map(|(request, clip)| (request, clip)),
    );
    finalize_voice_audio_policy_report(&mut report);
    report
}

fn generated_performance_capture_clips_from_voice_events(
    events: &[&WorldEvent],
) -> Vec<(SpeechRequest, PerformanceCaptureClip)> {
    events
        .iter()
        .filter_map(|event| {
            let WorldEventKind::DialogueEmitted {
                speaker,
                text,
                emotion,
                voice_persona,
                ..
            } = &event.kind
            else {
                return None;
            };
            let voice_persona = (*voice_persona)?;
            let emotional_load = emotion.urgency + emotion.fear + emotion.anger;
            let request = SpeechRequest {
                request_id: event.event_id,
                speaker: *speaker,
                voice_persona,
                text: text.clone(),
                emotion: emotion.clone(),
                intent: "runtime_dialogue".to_string(),
                urgency: emotion.urgency,
                loudness: (0.65 + emotion.urgency * 0.15).clamp(0.35, 1.0),
                language: 1,
                interruption_policy: "finish_current".to_string(),
                location: Some(event.location_meters),
                priority: if emotional_load >= 1.25 {
                    SpeechPriority::Important
                } else {
                    SpeechPriority::Normal
                },
                mode: SpeechGenerationMode::CachedGenerated,
                max_latency_ms: 45,
                safety_context: VoiceSafetyContext::default(),
            };
            let result = synthesize_speech(&request);
            let clip = generated_performance_capture_clip_from_speech_result(&request, &result);
            Some((request, clip))
        })
        .collect()
}

pub fn voice_audio_lab_report_from_events_and_performance_captures<'a, 'b>(
    events: impl IntoIterator<Item = &'a WorldEvent>,
    captures: impl IntoIterator<Item = (&'b SpeechRequest, &'b PerformanceCaptureClip)>,
) -> VoiceAudioLabReport {
    let mut report = voice_audio_lab_report_from_events(events);
    add_performance_capture_clips_to_report(&mut report, captures);
    finalize_voice_audio_policy_report(&mut report);
    report
}

pub fn voice_audio_lab_report_from_performance_capture_clips<'a>(
    captures: impl IntoIterator<Item = (&'a SpeechRequest, &'a PerformanceCaptureClip)>,
) -> VoiceAudioLabReport {
    let mut report = VoiceAudioLabReport::default();
    add_performance_capture_clips_to_report(&mut report, captures);
    report.comfort = build_voice_comfort_projection(&report);
    finalize_voice_audio_policy_report(&mut report);
    report
}

pub fn voice_audio_lab_report_from_events<'a>(
    events: impl IntoIterator<Item = &'a WorldEvent>,
) -> VoiceAudioLabReport {
    let events = events.into_iter().collect::<Vec<_>>();
    let mut report = VoiceAudioLabReport::default();
    let mut voice_personas = BTreeSet::<VoicePersonaId>::new();
    let mut facial_events = Vec::<(EntityId, usize, f32)>::new();

    for event in events.iter().copied() {
        match &event.kind {
            WorldEventKind::DialogueEmitted {
                speaker,
                target,
                text,
                emotion,
                voice_persona,
            } => {
                if let Some(persona) = voice_persona {
                    voice_personas.insert(*persona);
                } else {
                    push_voice_audio_issue(
                        &mut report,
                        VoiceAudioIssueSeverity::Warning,
                        VoiceAudioIssueCategory::Provenance,
                        "missing_voice_persona",
                        format!("speaker:{speaker}"),
                        "dialogue should identify the voice persona used for speech",
                    );
                }
                if text.trim().is_empty() {
                    push_voice_audio_issue(
                        &mut report,
                        VoiceAudioIssueSeverity::Error,
                        VoiceAudioIssueCategory::Comfort,
                        "empty_dialogue",
                        format!("speaker:{speaker}"),
                        "speech generation should not receive empty dialogue text",
                    );
                }
                let emotional_load = emotion.urgency + emotion.fear + emotion.anger;
                if emotional_load > 2.45 {
                    push_voice_audio_issue(
                        &mut report,
                        VoiceAudioIssueSeverity::Warning,
                        VoiceAudioIssueCategory::Comfort,
                        "high_emotional_load",
                        format!("speaker:{speaker}"),
                        "dialogue delivery may become tiring if urgency, fear, and anger are all high",
                    );
                }

                report.dialogues.push(VoiceDialogueLabDebug {
                    speaker: *speaker,
                    target: *target,
                    voice_persona: *voice_persona,
                    text_preview: truncate_debug_text(text, 96),
                    character_count: text.chars().count(),
                    urgency: emotion.urgency,
                    fear: emotion.fear,
                    anger: emotion.anger,
                    emotional_load,
                });
            }
            WorldEventKind::SpeechSynthesized {
                speaker,
                audio_clip,
                duration_seconds,
                phoneme_count,
                viseme_count,
            } => {
                let phonemes_per_second = rate_per_second(*phoneme_count, *duration_seconds);
                let visemes_per_second = rate_per_second(*viseme_count, *duration_seconds);
                let has_lip_sync_data = *phoneme_count > 0 && *viseme_count > 0;

                if *duration_seconds <= 0.0 || !duration_seconds.is_finite() {
                    push_voice_audio_issue(
                        &mut report,
                        VoiceAudioIssueSeverity::Error,
                        VoiceAudioIssueCategory::LipSync,
                        "invalid_speech_duration",
                        format!("speaker:{speaker}"),
                        "speech synthesis must report a positive finite duration",
                    );
                }
                if !has_lip_sync_data {
                    push_voice_audio_issue(
                        &mut report,
                        VoiceAudioIssueSeverity::Error,
                        VoiceAudioIssueCategory::LipSync,
                        "missing_lip_sync_tracks",
                        format!("speaker:{speaker}"),
                        "speech synthesis must produce phoneme and viseme timing data",
                    );
                }
                if has_lip_sync_data && !(2.0..=22.0).contains(&phonemes_per_second) {
                    push_voice_audio_issue(
                        &mut report,
                        VoiceAudioIssueSeverity::Warning,
                        VoiceAudioIssueCategory::Comfort,
                        "unusual_phoneme_rate",
                        format!("speaker:{speaker}"),
                        "phoneme density is outside the expected comfort range",
                    );
                }

                report.speech_events.push(VoiceSpeechSynthesisDebug {
                    speaker: *speaker,
                    audio_clip: *audio_clip,
                    duration_seconds: *duration_seconds,
                    phoneme_count: *phoneme_count,
                    viseme_count: *viseme_count,
                    phonemes_per_second,
                    visemes_per_second,
                    has_lip_sync_data,
                });
            }
            WorldEventKind::FacialAnimationApplied {
                entity,
                viseme_count,
                duration_seconds,
            } => {
                facial_events.push((*entity, *viseme_count, *duration_seconds));
            }
            WorldEventKind::SoundEmitted {
                kind,
                source_entity,
                material_id,
                intensity,
                radius_meters,
                occlusion_hint,
            } => {
                let physical = audio_kind_is_physical(*kind);
                let material_aware = material_id.is_some();
                if physical {
                    report.physics_sound_count += 1;
                }
                if *kind == AudioEventKind::VoiceSpeech {
                    report.voice_sound_count += 1;
                }
                if material_aware {
                    report.material_aware_sound_count += 1;
                } else if physical {
                    push_voice_audio_issue(
                        &mut report,
                        VoiceAudioIssueSeverity::Warning,
                        VoiceAudioIssueCategory::PhysicsSound,
                        "missing_material_context",
                        format!("{kind:?}"),
                        "physical sound events should carry material context for synthesis",
                    );
                }
                if !intensity.is_finite() || *intensity < 0.0 || *intensity > 1.25 {
                    push_voice_audio_issue(
                        &mut report,
                        VoiceAudioIssueSeverity::Error,
                        VoiceAudioIssueCategory::Propagation,
                        "invalid_sound_intensity",
                        format!("{kind:?}"),
                        "sound intensity should stay within a normalized runtime range",
                    );
                }

                report.sound_events.push(AudioSoundEventDebug {
                    kind: *kind,
                    source_entity: *source_entity,
                    material_id: *material_id,
                    intensity: *intensity,
                    radius_meters: *radius_meters,
                    occlusion_hint: *occlusion_hint,
                    material_aware,
                    physical,
                    perceived_loudness: perceived_loudness(*intensity, *occlusion_hint),
                });
            }
            WorldEventKind::AudioFrameMixed {
                active_sound_count,
                material_aware_sound_count,
                peak_intensity,
                mixed_audio_buffer,
            } => {
                report.peak_mix_intensity = report.peak_mix_intensity.max(*peak_intensity);
                report.peak_active_sound_count =
                    report.peak_active_sound_count.max(*active_sound_count);
                if *material_aware_sound_count > *active_sound_count {
                    push_voice_audio_issue(
                        &mut report,
                        VoiceAudioIssueSeverity::Error,
                        VoiceAudioIssueCategory::Mixing,
                        "invalid_material_aware_count",
                        "audio_mix",
                        "material-aware sound count cannot exceed active sound count",
                    );
                }
                if !peak_intensity.is_finite() || *peak_intensity > 1.0 {
                    push_voice_audio_issue(
                        &mut report,
                        VoiceAudioIssueSeverity::Error,
                        VoiceAudioIssueCategory::Mixing,
                        "mix_peak_clipped",
                        "audio_mix",
                        "audio mix peak exceeded the normalized output range",
                    );
                } else if *peak_intensity > 0.98 {
                    push_voice_audio_issue(
                        &mut report,
                        VoiceAudioIssueSeverity::Warning,
                        VoiceAudioIssueCategory::Comfort,
                        "mix_peak_hot",
                        "audio_mix",
                        "audio mix is close to clipping and may reduce dialogue comfort",
                    );
                }

                report.mix_frames.push(AudioMixFrameDebug {
                    active_sound_count: *active_sound_count,
                    material_aware_sound_count: *material_aware_sound_count,
                    peak_intensity: *peak_intensity,
                    mixed_audio_buffer: *mixed_audio_buffer,
                    voice_readability_score: voice_readability_score(*peak_intensity),
                });
            }
            _ => {}
        }
    }

    build_face_sync_report(&mut report, &facial_events);
    report.soundscape = build_district_soundscape_lab_report(&events);
    if report.soundscape.layer_count > 0 && !report.soundscape.validation_passed {
        push_voice_audio_issue(
            &mut report,
            VoiceAudioIssueSeverity::Error,
            VoiceAudioIssueCategory::Soundscape,
            "invalid_district_soundscape",
            "district:0",
            "state-driven district soundscape failed validation",
        );
    }
    if report.soundscape.layer_count > 0 && !report.soundscape.score_validation_passed {
        push_voice_audio_issue(
            &mut report,
            VoiceAudioIssueSeverity::Error,
            VoiceAudioIssueCategory::Soundscape,
            "invalid_adaptive_score",
            "district:0",
            "adaptive score failed validation for the current city/story state",
        );
    }
    report.unique_voice_personas = voice_personas.into_iter().collect();
    report.speech_count = report.speech_events.len();
    report.dialogue_count = report.dialogues.len();
    report.comfort = build_voice_comfort_projection(&report);
    finalize_voice_audio_policy_report(&mut report);
    report
}

fn build_face_sync_report(
    report: &mut VoiceAudioLabReport,
    facial_events: &[(EntityId, usize, f32)],
) {
    let mut used_facial_events = vec![false; facial_events.len()];
    let speech_events = report.speech_events.clone();
    for speech in speech_events {
        let match_index = facial_events
            .iter()
            .enumerate()
            .find(|(index, (entity, _, _))| {
                !used_facial_events[*index] && *entity == speech.speaker
            })
            .map(|(index, _)| index);

        let Some(index) = match_index else {
            report.unsynced_speech_count += 1;
            push_voice_audio_issue(
                report,
                VoiceAudioIssueSeverity::Error,
                VoiceAudioIssueCategory::LipSync,
                "missing_face_sync",
                format!("speaker:{}", speech.speaker),
                "synthesized speech must be paired with facial animation timing",
            );
            continue;
        };

        used_facial_events[index] = true;
        let (_, face_viseme_count, face_duration_seconds) = facial_events[index];
        let duration_delta_seconds = (speech.duration_seconds - face_duration_seconds).abs();
        let viseme_count_delta = speech.viseme_count.abs_diff(face_viseme_count);
        let synchronized = duration_delta_seconds <= 0.075 && viseme_count_delta <= 1;
        if synchronized {
            report.synced_speech_count += 1;
        } else {
            report.unsynced_speech_count += 1;
            push_voice_audio_issue(
                report,
                VoiceAudioIssueSeverity::Error,
                VoiceAudioIssueCategory::LipSync,
                "face_sync_mismatch",
                format!("speaker:{}", speech.speaker),
                "facial animation timing does not match synthesized speech",
            );
        }

        report.face_sync.push(VoiceFaceSyncDebug {
            speaker: speech.speaker,
            audio_clip: speech.audio_clip,
            speech_duration_seconds: speech.duration_seconds,
            face_duration_seconds,
            duration_delta_seconds,
            speech_viseme_count: speech.viseme_count,
            face_viseme_count,
            viseme_count_delta,
            synchronized,
        });
    }
}

fn build_district_soundscape_lab_report(events: &[&WorldEvent]) -> DistrictSoundscapeLabReport {
    let state = district_audio_state_from_events(0, events.iter().copied());
    if state.active_events.is_empty() {
        return DistrictSoundscapeLabReport {
            weather: soundscape_weather_label(SoundscapeWeatherState::Clear).to_string(),
            power_level: 1.0,
            score_transition: music_transition_label(MusicTransitionKind::Hold).to_string(),
            score_validation_passed: true,
            validation_passed: true,
            ..DistrictSoundscapeLabReport::default()
        };
    }

    let output = generate_district_soundscape(&state);
    DistrictSoundscapeLabReport {
        layer_count: output.layers.len(),
        event_driven_layer_count: output
            .layers
            .iter()
            .filter(|layer| layer.event_driven)
            .count(),
        weather: soundscape_weather_label(output.state.weather).to_string(),
        power_level: output.state.power_level,
        alertness: output.state.alertness,
        pollution_level: output.state.pollution_level,
        tension_score: output.tension_score,
        music_ducking: output.music_ducking,
        adaptive_score_stem_count: output.adaptive_score.stems.len(),
        diegetic_music_source_count: output.adaptive_score.diegetic_sources.len(),
        score_transition: music_transition_label(output.adaptive_score.transition).to_string(),
        silence_tension: output.adaptive_score.silence_tension,
        radio_station_enabled: output.adaptive_score.radio_station.enabled,
        radio_signal_strength: output.adaptive_score.radio_station.signal_strength,
        score_validation_passed: output.adaptive_score.validation_report.passed,
        score_issue_count: output.adaptive_score.validation_report.issues.len(),
        emergency_layer_present: output
            .layers
            .iter()
            .any(|layer| layer.kind == SoundscapeLayerKind::EmergencyAlarm),
        ventilation_layer_present: output
            .layers
            .iter()
            .any(|layer| layer.kind == SoundscapeLayerKind::Ventilation),
        police_scanner_present: output
            .layers
            .iter()
            .any(|layer| layer.kind == SoundscapeLayerKind::PoliceScanner),
        validation_passed: output.validation_report.passed,
        issue_count: output.validation_report.issues.len(),
    }
}

fn soundscape_weather_label(weather: SoundscapeWeatherState) -> &'static str {
    match weather {
        SoundscapeWeatherState::Clear => "clear",
        SoundscapeWeatherState::Rain => "rain",
        SoundscapeWeatherState::Flooding => "flooding",
        SoundscapeWeatherState::GasHazard => "gas_hazard",
    }
}

fn music_transition_label(transition: MusicTransitionKind) -> &'static str {
    match transition {
        MusicTransitionKind::Hold => "hold",
        MusicTransitionKind::LayerIn => "layer_in",
        MusicTransitionKind::LayerOut => "layer_out",
        MusicTransitionKind::Crossfade => "crossfade",
        MusicTransitionKind::Stinger => "stinger",
        MusicTransitionKind::SilenceDrop => "silence_drop",
    }
}

fn add_performance_capture_clips_to_report<'a>(
    report: &mut VoiceAudioLabReport,
    captures: impl IntoIterator<Item = (&'a SpeechRequest, &'a PerformanceCaptureClip)>,
) {
    for (request, clip) in captures {
        let validation = validate_performance_capture_clip(request, clip);
        let memory_bytes = voice_performance_capture_memory_bytes(clip);
        report.unique_voice_personas.push(clip.voice_persona);
        report
            .performance_captures
            .push(VoicePerformanceCaptureDebug {
                clip_id: clip.clip_id,
                speaker: clip.speaker,
                voice_persona: clip.voice_persona,
                source_label: performance_capture_source_label(clip.source).to_string(),
                actor_or_source_label: clip.provenance.actor_or_source_label.clone(),
                session_label: clip.provenance.session_label.clone(),
                audio_clip: clip.audio_track,
                duration_seconds: clip.duration_seconds,
                phoneme_count: clip.phonemes.len(),
                viseme_count: clip.visemes.len(),
                face_curve_count: clip.face_curves.len(),
                body_curve_count: clip.body_curves.len(),
                mapped_face_channel_count: clip.target_rig.mapped_face_channels.len(),
                mapped_body_channel_count: clip.target_rig.mapped_body_channels.len(),
                validation_note_count: clip.validation_notes.len(),
                audio_sample_rate_hz: clip.calibration.audio_sample_rate_hz,
                video_frame_rate: clip.calibration.video_frame_rate,
                capture_timecode_frame_rate: clip.timecode.frame_rate,
                audio_video_offset_seconds: clip.calibration.audio_video_offset_seconds,
                face_solve_confidence: clip.calibration.face_solve_confidence,
                body_solve_confidence: clip.calibration.body_solve_confidence,
                rights_verified: clip.provenance.rights_verified,
                consent_verified: clip.provenance.consent_verified,
                retargeting_allowed: clip.provenance.retargeting_allowed,
                validation_passed: validation.passed,
                issue_count: validation.issues.len(),
                memory_bytes,
            });

        for issue in validation.issues {
            push_voice_audio_issue(
                report,
                voice_audio_severity_from_speech(issue.severity),
                VoiceAudioIssueCategory::PerformanceCapture,
                issue.code,
                format!("capture:{}", clip.clip_id),
                issue.message,
            );
        }
    }

    report.unique_voice_personas.sort_unstable();
    report.unique_voice_personas.dedup();
    report.performance_capture_count = report.performance_captures.len();
    report.validated_performance_capture_count = report
        .performance_captures
        .iter()
        .filter(|capture| capture.validation_passed)
        .count();
}

fn finalize_voice_audio_policy_report(report: &mut VoiceAudioLabReport) {
    report.performance_capture_count = report.performance_captures.len();
    report.validated_performance_capture_count = report
        .performance_captures
        .iter()
        .filter(|capture| capture.validation_passed)
        .count();
    report.performance = build_voice_audio_performance_policy(report);

    if !report.is_empty() && !report.performance.budget_visible {
        push_voice_audio_issue(
            report,
            VoiceAudioIssueSeverity::Warning,
            VoiceAudioIssueCategory::PerformancePolicy,
            "missing_audio_budget_visibility",
            "voice_audio",
            "voice/audio inspection should publish mix, memory, or capture budget data",
        );
        report.performance = build_voice_audio_performance_policy(report);
    }
}

fn build_voice_audio_performance_policy(
    report: &VoiceAudioLabReport,
) -> VoiceAudioPerformancePolicyDebug {
    let capture_memory_bytes = report
        .performance_captures
        .iter()
        .map(|capture| capture.memory_bytes)
        .sum::<u64>();
    let max_capture_sync_error_seconds = report
        .performance_captures
        .iter()
        .map(|capture| capture.audio_video_offset_seconds.abs())
        .fold(0.0_f32, f32::max);
    let max_lip_sync_error_seconds = report
        .face_sync
        .iter()
        .map(|sync| sync.duration_delta_seconds)
        .fold(0.0_f32, f32::max);
    let average_occlusion = if report.sound_events.is_empty() {
        0.0
    } else {
        report
            .sound_events
            .iter()
            .map(|sound| sound.occlusion_hint.clamp(0.0, 1.0))
            .sum::<f32>()
            / report.sound_events.len() as f32
    };
    let reverb_occlusion_cost_score = (average_occlusion
        * (report.peak_active_sound_count as f32 / 32.0).clamp(0.0, 1.0))
    .clamp(0.0, 1.0);
    let active_speech_stream_count = report.voice_sound_count.max(report.speech_events.len());
    let budget_visible = !report.mix_frames.is_empty() || capture_memory_bytes > 0;
    let speech_generation_nonblocking = report
        .speech_events
        .iter()
        .all(|speech| speech.duration_seconds.is_finite() && speech.duration_seconds > 0.0);
    let passed = budget_visible
        && report.unsynced_speech_count == 0
        && max_lip_sync_error_seconds <= 0.075
        && report.performance_capture_count == report.validated_performance_capture_count
        && report.critical_issue_count() == 0;

    VoiceAudioPerformancePolicyDebug {
        budget_visible,
        active_sound_voice_count: report.peak_active_sound_count,
        active_speech_stream_count,
        dropped_or_virtualized_sound_count: 0,
        material_aware_sound_count: report.material_aware_sound_count,
        reverb_occlusion_cost_score,
        max_lip_sync_error_seconds,
        unsynced_speech_count: report.unsynced_speech_count,
        performance_capture_count: report.performance_capture_count,
        validated_performance_capture_count: report.validated_performance_capture_count,
        capture_memory_bytes,
        max_capture_sync_error_seconds,
        speech_generation_nonblocking,
        passed,
    }
}

fn voice_performance_capture_memory_bytes(clip: &PerformanceCaptureClip) -> u64 {
    let track_count = clip.phonemes.len()
        + clip.visemes.len()
        + clip.prosody.frames.len()
        + clip.emotion_curve.len()
        + clip.face_curves.len()
        + clip.body_curves.len();
    (track_count as u64)
        .saturating_mul(48)
        .saturating_add(64 * 1024)
}

fn performance_capture_source_label(source: PerformanceCaptureSource) -> &'static str {
    match source {
        PerformanceCaptureSource::ActorSession => "actor_session",
        PerformanceCaptureSource::ManualAnimation => "manual_animation",
        PerformanceCaptureSource::AiGeneratedAnimationHints => "ai_generated_animation_hints",
        PerformanceCaptureSource::Placeholder => "placeholder",
    }
}

fn voice_audio_severity_from_speech(severity: SpeechValidationSeverity) -> VoiceAudioIssueSeverity {
    match severity {
        SpeechValidationSeverity::Info => VoiceAudioIssueSeverity::Info,
        SpeechValidationSeverity::Warning => VoiceAudioIssueSeverity::Warning,
        SpeechValidationSeverity::Error => VoiceAudioIssueSeverity::Error,
    }
}

fn push_voice_audio_issue(
    report: &mut VoiceAudioLabReport,
    severity: VoiceAudioIssueSeverity,
    category: VoiceAudioIssueCategory,
    code: impl Into<String>,
    subject: impl Into<String>,
    message: impl Into<String>,
) {
    report.issues.push(VoiceAudioLabIssue {
        severity,
        category,
        code: code.into(),
        subject: subject.into(),
        message: message.into(),
    });
}

fn rate_per_second(count: usize, duration_seconds: f32) -> f32 {
    if duration_seconds > 0.0 && duration_seconds.is_finite() {
        count as f32 / duration_seconds
    } else {
        0.0
    }
}

fn perceived_loudness(intensity: f32, occlusion_hint: f32) -> f32 {
    (intensity.clamp(0.0, 1.25) * (1.0 - occlusion_hint.clamp(0.0, 1.0) * 0.65)).clamp(0.0, 1.0)
}

fn voice_readability_score(peak_intensity: f32) -> f32 {
    (1.0 - (peak_intensity.clamp(0.0, 1.0) * 0.45)).clamp(0.0, 1.0)
}

fn build_voice_comfort_projection(report: &VoiceAudioLabReport) -> VoiceConversationComfortDebug {
    let line_count = report.speech_events.len();
    let total_speech_seconds = report
        .speech_events
        .iter()
        .map(|speech| speech.duration_seconds.max(0.0))
        .sum::<f32>();
    let total_phonemes = report
        .speech_events
        .iter()
        .map(|speech| speech.phoneme_count)
        .sum::<usize>();
    let total_visemes = report
        .speech_events
        .iter()
        .map(|speech| speech.viseme_count)
        .sum::<usize>();
    let average_phonemes_per_second = rate_per_second(total_phonemes, total_speech_seconds);
    let average_visemes_per_second = rate_per_second(total_visemes, total_speech_seconds);
    let average_voice_readability_score = if report.mix_frames.is_empty() {
        1.0
    } else {
        report
            .mix_frames
            .iter()
            .map(|mix| mix.voice_readability_score)
            .sum::<f32>()
            / report.mix_frames.len() as f32
    };
    let average_emotional_load = if report.dialogues.is_empty() {
        0.0
    } else {
        report
            .dialogues
            .iter()
            .map(|dialogue| dialogue.emotional_load)
            .sum::<f32>()
            / report.dialogues.len() as f32
    };
    let high_emotional_load_count = report
        .dialogues
        .iter()
        .filter(|dialogue| dialogue.emotional_load > 2.1)
        .count();
    let comfort_issue_count = report.comfort_issue_count();
    let critical_issue_count = report.critical_issue_count();

    if line_count == 0 {
        return VoiceConversationComfortDebug {
            passed: false,
            line_count,
            total_speech_seconds,
            projected_ten_minute_score: 0.0,
            average_phonemes_per_second,
            average_visemes_per_second,
            average_voice_readability_score,
            average_emotional_load,
            high_emotional_load_count,
            comfort_issue_count,
        };
    }

    let phoneme_rate_score = comfort_rate_score(average_phonemes_per_second, 7.5, 2.0, 22.0);
    let viseme_rate_score = comfort_rate_score(average_visemes_per_second, 3.5, 0.8, 18.0);
    let sync_score = if report.speech_count > 0 {
        report.synced_speech_count as f32 / report.speech_count as f32
    } else {
        0.0
    };
    let emotional_score = (1.0
        - (average_emotional_load / 3.0).clamp(0.0, 1.0) * 0.22
        - (high_emotional_load_count as f32 / line_count as f32) * 0.18)
        .clamp(0.0, 1.0);
    let issue_score =
        (1.0 - comfort_issue_count as f32 * 0.08 - critical_issue_count as f32 * 0.28)
            .clamp(0.0, 1.0);
    let projected_ten_minute_score = ((phoneme_rate_score
        + viseme_rate_score
        + sync_score
        + average_voice_readability_score
        + emotional_score
        + issue_score)
        / 6.0)
        .clamp(0.0, 1.0);

    VoiceConversationComfortDebug {
        passed: projected_ten_minute_score >= 0.75 && critical_issue_count == 0,
        line_count,
        total_speech_seconds,
        projected_ten_minute_score,
        average_phonemes_per_second,
        average_visemes_per_second,
        average_voice_readability_score,
        average_emotional_load,
        high_emotional_load_count,
        comfort_issue_count,
    }
}

fn comfort_rate_score(rate: f32, target: f32, min: f32, max: f32) -> f32 {
    if !rate.is_finite() || rate <= 0.0 {
        return 0.0;
    }
    if !(min..=max).contains(&rate) {
        return 0.35;
    }
    let spread = (max - min).max(1.0);
    (1.0 - ((rate - target).abs() / spread) * 1.8).clamp(0.55, 1.0)
}

fn truncate_debug_text(text: &str, max_chars: usize) -> String {
    let mut truncated = text.chars().take(max_chars).collect::<String>();
    if text.chars().count() > max_chars {
        truncated.push_str("...");
    }
    truncated
}

fn audio_kind_is_physical(kind: AudioEventKind) -> bool {
    !matches!(
        kind,
        AudioEventKind::VoiceSpeech
            | AudioEventKind::HumanBreath
            | AudioEventKind::NeonHum
            | AudioEventKind::ElectricBuzz
    )
}

type HumanDialogueEventSeed = (
    EntityId,
    Option<EntityId>,
    String,
    Option<VoicePersonaId>,
    f32,
    f32,
    f32,
);
type HumanSpeechEventSeed = (EntityId, AudioClipHandle, f32, usize);
type HumanFacialEventSeed = (EntityId, WorldEventId, usize, f32);

pub fn human_lab_report_from_frames(frame_reports: &[FrameReport]) -> HumanLabReport {
    let events = frame_reports
        .iter()
        .flat_map(|report| report.events.iter())
        .collect::<Vec<_>>();
    human_lab_report_from_events(events)
}

pub fn human_lab_report_from_events<'a>(
    events: impl IntoIterator<Item = &'a WorldEvent>,
) -> HumanLabReport {
    let events = events.into_iter().collect::<Vec<_>>();
    let mut report = HumanLabReport::default();
    let mut dialogue_events = Vec::<HumanDialogueEventSeed>::new();
    let mut voice_line_entities = BTreeSet::<EntityId>::new();
    let mut voice_line_count = 0usize;
    let mut speech_events = Vec::<HumanSpeechEventSeed>::new();
    let mut facial_events = Vec::<HumanFacialEventSeed>::new();
    let mut bundle_entities = BTreeSet::<EntityId>::new();

    for event in &events {
        match &event.kind {
            WorldEventKind::DialogueEmitted {
                speaker,
                target,
                text,
                emotion,
                voice_persona,
            } => {
                dialogue_events.push((
                    *speaker,
                    *target,
                    text.clone(),
                    *voice_persona,
                    emotion.urgency,
                    emotion.fear,
                    emotion.anger,
                ));
            }
            WorldEventKind::VoiceLineSpoken { speaker } => {
                voice_line_entities.insert(*speaker);
                voice_line_count += 1;
            }
            WorldEventKind::SpeechSynthesized {
                speaker,
                audio_clip,
                duration_seconds,
                viseme_count,
                ..
            } => {
                speech_events.push((*speaker, *audio_clip, *duration_seconds, *viseme_count));
            }
            WorldEventKind::FacialAnimationApplied {
                entity,
                viseme_count,
                duration_seconds,
            } => {
                if *viseme_count == 0 || *duration_seconds <= 0.0 || !duration_seconds.is_finite() {
                    push_human_lab_issue(
                        &mut report,
                        HumanLabIssueSeverity::Error,
                        HumanLabIssueCategory::FacialAnimation,
                        "invalid_facial_animation",
                        format!("entity:{entity}"),
                        "facial animation should carry positive duration and viseme data",
                    );
                }
                facial_events.push((*entity, event.event_id, *viseme_count, *duration_seconds));
            }
            WorldEventKind::HumanAppearanceUpdated {
                entity,
                skin_wetness,
                injury_overlay,
                bruising,
                dirt,
            } => {
                let values = [*skin_wetness, *injury_overlay, *bruising, *dirt];
                if values
                    .iter()
                    .any(|value| !value.is_finite() || !(0.0..=1.0).contains(value))
                {
                    push_human_lab_issue(
                        &mut report,
                        HumanLabIssueSeverity::Error,
                        HumanLabIssueCategory::SurfaceResponse,
                        "invalid_human_surface_response",
                        format!("entity:{entity}"),
                        "human skin, injury, bruising, and dirt response values should stay normalized",
                    );
                }
                report.appearance_updates.push(HumanAppearanceDebug {
                    entity: *entity,
                    event: event.event_id,
                    tick: event.tick,
                    skin_wetness: *skin_wetness,
                    injury_overlay: *injury_overlay,
                    bruising: *bruising,
                    dirt: *dirt,
                    material_responsive: *skin_wetness > 0.0
                        || *injury_overlay > 0.0
                        || *bruising > 0.0
                        || *dirt > 0.0
                        || event
                            .physical_evidence
                            .iter()
                            .chain(event.narrative_tags.iter())
                            .any(|tag| tag.contains("human_material_response")),
                });
            }
            WorldEventKind::AssetStreamingRequested {
                asset_id,
                requester,
                requested_quality,
                priority,
                reason,
            } if is_human_asset_request(reason) => {
                let entity = event.actors.first().copied();
                if let Some(entity) = entity {
                    bundle_entities.insert(entity);
                }
                let runtime_bundle = *requester == 40 || human_text_contains_bundle(reason);
                let renderer_detail =
                    *requester == 10 || human_text_contains_renderer_detail(reason);
                report.bundle_requests.push(HumanBundleRequestDebug {
                    event: event.event_id,
                    tick: event.tick,
                    entity,
                    asset_id: *asset_id,
                    requester: *requester,
                    requested_quality: *requested_quality,
                    priority: *priority,
                    reason: reason.clone(),
                    runtime_bundle,
                    renderer_detail,
                });
            }
            _ => {}
        }
    }

    build_human_speech_performances(
        &mut report,
        &speech_events,
        &facial_events,
        &bundle_entities,
    );
    build_human_dialogue_performances(
        &mut report,
        &dialogue_events,
        &voice_line_entities,
        &speech_events,
        &facial_events,
        &bundle_entities,
    );

    report.voice_line_count = voice_line_count;
    report.dialogue_count = report.dialogues.len();
    report.speech_performance_count = report.speech_performances.len();
    report.appearance_update_count = report.appearance_updates.len();
    report.bundle_request_count = report.bundle_requests.len();
    report
}

fn build_human_speech_performances(
    report: &mut HumanLabReport,
    speech_events: &[HumanSpeechEventSeed],
    facial_events: &[HumanFacialEventSeed],
    bundle_entities: &BTreeSet<EntityId>,
) {
    let mut used_facial_events = vec![false; facial_events.len()];
    for (speaker, audio_clip, duration_seconds, viseme_count) in speech_events {
        let matched_face = facial_events
            .iter()
            .enumerate()
            .find(|(index, (entity, _, _, _))| !used_facial_events[*index] && entity == speaker);
        let (face_duration_seconds, duration_delta_seconds, face_viseme_count, synchronized) =
            if let Some((index, (_, _, face_visemes, face_duration))) = matched_face {
                used_facial_events[index] = true;
                let duration_delta = (*duration_seconds - *face_duration).abs();
                let viseme_delta = viseme_count.abs_diff(*face_visemes);
                let synchronized = duration_delta <= 0.075 && viseme_delta <= 1;
                if synchronized {
                    report.synchronized_face_count += 1;
                } else {
                    report.unsynchronized_face_count += 1;
                    push_human_lab_issue(
                        report,
                        HumanLabIssueSeverity::Error,
                        HumanLabIssueCategory::FacialAnimation,
                        "human_face_sync_mismatch",
                        format!("speaker:{speaker}"),
                        "human facial performance should match synthesized speech timing",
                    );
                }
                (
                    Some(*face_duration),
                    Some(duration_delta),
                    Some(*face_visemes),
                    synchronized,
                )
            } else {
                report.unsynchronized_face_count += 1;
                push_human_lab_issue(
                    report,
                    HumanLabIssueSeverity::Error,
                    HumanLabIssueCategory::FacialAnimation,
                    "human_missing_face_sync",
                    format!("speaker:{speaker}"),
                    "synthesized human speech should produce facial animation",
                );
                (None, None, None, false)
            };

        let has_bundle_request = bundle_entities.contains(speaker);
        if !has_bundle_request {
            push_human_lab_issue(
                report,
                HumanLabIssueSeverity::Warning,
                HumanLabIssueCategory::BundleStreaming,
                "human_missing_bundle_request",
                format!("speaker:{speaker}"),
                "speaking humans should request body, face, clothing, and rig detail bundles",
            );
        }
        report
            .speech_performances
            .push(HumanSpeechPerformanceDebug {
                speaker: *speaker,
                audio_clip: *audio_clip,
                speech_duration_seconds: *duration_seconds,
                face_duration_seconds,
                duration_delta_seconds,
                speech_viseme_count: *viseme_count,
                face_viseme_count,
                synchronized,
                has_bundle_request,
            });
    }
}

fn build_human_dialogue_performances(
    report: &mut HumanLabReport,
    dialogue_events: &[HumanDialogueEventSeed],
    voice_line_entities: &BTreeSet<EntityId>,
    speech_events: &[HumanSpeechEventSeed],
    facial_events: &[HumanFacialEventSeed],
    bundle_entities: &BTreeSet<EntityId>,
) {
    for (speaker, target, text, voice_persona, urgency, fear, anger) in dialogue_events {
        let emotional_load = *urgency + *fear + *anger;
        let has_voice_line = voice_line_entities.contains(speaker);
        let has_speech = speech_events
            .iter()
            .any(|(entity, _, _, _)| entity == speaker);
        let has_facial_animation = facial_events
            .iter()
            .any(|(entity, _, _, _)| entity == speaker);
        let has_bundle_request = bundle_entities.contains(speaker);
        if emotional_load >= 1.0 {
            report.emotionally_loaded_dialogue_count += 1;
        }
        if !has_speech {
            push_human_lab_issue(
                report,
                HumanLabIssueSeverity::Error,
                HumanLabIssueCategory::VoiceEmotion,
                "human_dialogue_missing_speech",
                format!("speaker:{speaker}"),
                "human dialogue should be connected to synthesized speech",
            );
        }
        if !has_facial_animation {
            push_human_lab_issue(
                report,
                HumanLabIssueSeverity::Error,
                HumanLabIssueCategory::FacialAnimation,
                "human_dialogue_missing_expression",
                format!("speaker:{speaker}"),
                "human dialogue should drive facial animation and expression",
            );
        }
        if !has_voice_line {
            push_human_lab_issue(
                report,
                HumanLabIssueSeverity::Warning,
                HumanLabIssueCategory::VoiceEmotion,
                "human_dialogue_missing_voice_line",
                format!("speaker:{speaker}"),
                "dialogue should create a voice line event for replay and cinematic tooling",
            );
        }
        if emotional_load >= 1.0 && !has_facial_animation {
            push_human_lab_issue(
                report,
                HumanLabIssueSeverity::Error,
                HumanLabIssueCategory::VoiceEmotion,
                "emotional_dialogue_missing_face",
                format!("speaker:{speaker}"),
                "emotional dialogue should be visible on the human face",
            );
        }
        report.dialogues.push(HumanDialoguePerformanceDebug {
            speaker: *speaker,
            target: *target,
            text_preview: truncate_debug_text(text, 96),
            voice_persona: *voice_persona,
            urgency: *urgency,
            fear: *fear,
            anger: *anger,
            emotional_load,
            has_voice_line,
            has_speech,
            has_facial_animation,
            has_bundle_request,
        });
    }
}

fn is_human_asset_request(reason: &str) -> bool {
    let normalized = reason.to_ascii_lowercase();
    [
        "body", "clothing", "eye", "eyes", "face", "facial", "hair", "human", "morph", "rig",
        "skin",
    ]
    .iter()
    .any(|word| text_has_word(&normalized, word))
}

fn human_text_contains_bundle(reason: &str) -> bool {
    let normalized = reason.to_ascii_lowercase();
    ["body", "bundle", "clothing", "rig"]
        .iter()
        .any(|word| text_has_word(&normalized, word))
}

fn human_text_contains_renderer_detail(reason: &str) -> bool {
    let normalized = reason.to_ascii_lowercase();
    ["eye", "eyes", "face", "hair", "renderer", "skin"]
        .iter()
        .any(|word| text_has_word(&normalized, word))
}

fn text_has_word(text: &str, expected: &str) -> bool {
    text.split(|character: char| !character.is_ascii_alphanumeric())
        .any(|word| word == expected)
}

fn push_human_lab_issue(
    report: &mut HumanLabReport,
    severity: HumanLabIssueSeverity,
    category: HumanLabIssueCategory,
    code: impl Into<String>,
    subject: impl Into<String>,
    message: impl Into<String>,
) {
    report.issues.push(HumanLabIssue {
        severity,
        category,
        code: code.into(),
        subject: subject.into(),
        message: message.into(),
    });
}

pub fn cinematic_timeline_report_from_frames(
    frame_reports: &[FrameReport],
) -> CinematicTimelineReport {
    let events = frame_reports
        .iter()
        .flat_map(|report| report.events.iter())
        .collect::<Vec<_>>();
    let mut report = cinematic_timeline_report_from_events(events);
    report.frame_count = frame_reports.len();
    report
}

pub fn cinematic_timeline_report_from_events<'a>(
    events: impl IntoIterator<Item = &'a WorldEvent>,
) -> CinematicTimelineReport {
    let events = events.into_iter().collect::<Vec<_>>();
    let mut report = CinematicTimelineReport::default();
    let mut track_counts = BTreeMap::<CinematicTrackKind, usize>::new();
    let mut track_first_tick = BTreeMap::<CinematicTrackKind, u64>::new();
    let mut track_last_tick = BTreeMap::<CinematicTrackKind, u64>::new();
    let mut fracture_seen = false;

    for event in &events {
        let Some(track) = cinematic_track_for_event(&event.kind) else {
            continue;
        };
        if matches!(event.kind, WorldEventKind::GlassWallFractured { .. }) {
            fracture_seen = true;
        }
        let beat = CinematicTimelineBeatDebug {
            event: event.event_id,
            tick: event.tick,
            track,
            label: cinematic_label_for_event(&event.kind),
            actor_count: event.actors.len(),
            location: vec3_debug(event.location_meters),
            source_event: cinematic_source_event(&event.kind),
        };
        *track_counts.entry(track).or_default() += 1;
        track_first_tick
            .entry(track)
            .and_modify(|tick| *tick = (*tick).min(event.tick))
            .or_insert(event.tick);
        track_last_tick
            .entry(track)
            .and_modify(|tick| *tick = (*tick).max(event.tick))
            .or_insert(event.tick);
        report.beats.push(beat);
    }

    report
        .beats
        .sort_by_key(|beat| (beat.tick, beat.event, beat.track));
    report.tracks = track_counts
        .into_iter()
        .map(|(kind, beat_count)| CinematicTrackDebug {
            kind,
            beat_count,
            first_tick: track_first_tick.get(&kind).copied().unwrap_or_default(),
            last_tick: track_last_tick.get(&kind).copied().unwrap_or_default(),
        })
        .collect();
    report.tracks.sort_by_key(|track| track.kind);

    report.beat_count = report.beats.len();
    report.track_count = report.tracks.len();
    report.physics_beat_count =
        cinematic_track_count(&report.tracks, CinematicTrackKind::PhysicsPlayback);
    report.material_beat_count =
        cinematic_track_count(&report.tracks, CinematicTrackKind::MaterialState);
    report.voice_beat_count = cinematic_track_count(&report.tracks, CinematicTrackKind::Voice);
    report.facial_beat_count =
        cinematic_track_count(&report.tracks, CinematicTrackKind::FacialPerformance);
    report.character_beat_count =
        cinematic_track_count(&report.tracks, CinematicTrackKind::CharacterAnimation);
    report.ai_story_beat_count = cinematic_track_count(&report.tracks, CinematicTrackKind::AiStory);
    report.world_event_beat_count =
        cinematic_track_count(&report.tracks, CinematicTrackKind::WorldEvent);
    report.asset_streaming_beat_count =
        cinematic_track_count(&report.tracks, CinematicTrackKind::AssetStreaming);

    validate_cinematic_timeline_tracks(&mut report, fracture_seen);
    report
}

fn validate_cinematic_timeline_tracks(report: &mut CinematicTimelineReport, fracture_seen: bool) {
    if report.beats.is_empty() {
        push_cinematic_timeline_issue(
            report,
            CinematicTimelineIssueSeverity::Error,
            CinematicTimelineIssueCategory::TrackCoverage,
            "empty_cinematic_timeline",
            "timeline",
            "cinematic timeline needs runtime events to inspect",
        );
        return;
    }

    for (kind, code, message) in [
        (
            CinematicTrackKind::PhysicsPlayback,
            "missing_physics_playback_track",
            "cinematic timeline should expose gameplay physics playback",
        ),
        (
            CinematicTrackKind::MaterialState,
            "missing_material_state_track",
            "cinematic timeline should expose material state changes",
        ),
        (
            CinematicTrackKind::Voice,
            "missing_voice_track",
            "cinematic timeline should expose voice and dialogue beats",
        ),
        (
            CinematicTrackKind::FacialPerformance,
            "missing_facial_performance_track",
            "cinematic timeline should expose facial performance beats",
        ),
        (
            CinematicTrackKind::AiStory,
            "missing_ai_story_track",
            "cinematic timeline should expose AI/story beats",
        ),
        (
            CinematicTrackKind::WorldEvent,
            "missing_world_event_track",
            "cinematic timeline should expose story/world event beats",
        ),
        (
            CinematicTrackKind::AssetStreaming,
            "missing_asset_streaming_track",
            "cinematic timeline should expose runtime asset streaming beats",
        ),
    ] {
        if report.track(kind).is_none() {
            push_cinematic_timeline_issue(
                report,
                CinematicTimelineIssueSeverity::Error,
                CinematicTimelineIssueCategory::TrackCoverage,
                code,
                format!("{kind:?}"),
                message,
            );
        }
    }

    if fracture_seen {
        for (kind, code, message) in [
            (
                CinematicTrackKind::MaterialState,
                "fracture_timeline_missing_material_track",
                "fracture beats should line up with material state tracks",
            ),
            (
                CinematicTrackKind::AssetStreaming,
                "fracture_timeline_missing_streaming_track",
                "fracture beats should line up with generated asset streaming",
            ),
            (
                CinematicTrackKind::AiStory,
                "fracture_timeline_missing_ai_story_track",
                "fracture beats should line up with AI/story reactions",
            ),
        ] {
            if report.track(kind).is_none() {
                push_cinematic_timeline_issue(
                    report,
                    CinematicTimelineIssueSeverity::Error,
                    CinematicTimelineIssueCategory::ConsequenceContinuity,
                    code,
                    "fracture",
                    message,
                );
            }
        }
    }
}

fn cinematic_track_for_event(kind: &WorldEventKind) -> Option<CinematicTrackKind> {
    match kind {
        WorldEventKind::ForceApplied { .. }
        | WorldEventKind::DamageApplied { .. }
        | WorldEventKind::GlassWallFractured { .. }
        | WorldEventKind::MetalBent { .. }
        | WorldEventKind::FlexibleConstraintResolved { .. }
        | WorldEventKind::PowerTransformerOverheated { .. }
        | WorldEventKind::StreetFlooded
        | WorldEventKind::ToxicGasReleased
        | WorldEventKind::MeshReplaced { .. } => Some(CinematicTrackKind::PhysicsPlayback),
        WorldEventKind::SoundEmitted { kind, .. } if audio_kind_is_physical(*kind) => {
            Some(CinematicTrackKind::PhysicsPlayback)
        }
        WorldEventKind::MaterialStateChanged { .. } => Some(CinematicTrackKind::MaterialState),
        WorldEventKind::DialogueEmitted { .. }
        | WorldEventKind::VoiceLineSpoken { .. }
        | WorldEventKind::SpeechSynthesized { .. }
        | WorldEventKind::AudioFrameMixed { .. }
        | WorldEventKind::SoundEmitted {
            kind: AudioEventKind::VoiceSpeech,
            ..
        } => Some(CinematicTrackKind::Voice),
        WorldEventKind::FacialAnimationApplied { .. } => {
            Some(CinematicTrackKind::FacialPerformance)
        }
        WorldEventKind::HumanAppearanceUpdated { .. }
        | WorldEventKind::AgentStateChanged { .. }
        | WorldEventKind::TransformChanged { .. } => Some(CinematicTrackKind::CharacterAnimation),
        WorldEventKind::AgentDecisionExplained { .. }
        | WorldEventKind::AgentIntentProposed { .. }
        | WorldEventKind::AgentMemoryUpdated { .. }
        | WorldEventKind::NpcHeardSound { .. }
        | WorldEventKind::NpcWitnessedCrime { .. } => Some(CinematicTrackKind::AiStory),
        WorldEventKind::StoryEventEmitted { .. }
        | WorldEventKind::PlayerIdentityExposed
        | WorldEventKind::SecurityAlertRaised { .. }
        | WorldEventKind::FactionReputationChanged { .. }
        | WorldEventKind::FactionLostTerritory { .. }
        | WorldEventKind::SurveillanceIncreased { .. } => Some(CinematicTrackKind::WorldEvent),
        WorldEventKind::AssetStreamingRequested { .. }
        | WorldEventKind::AssetBecameResident { .. } => Some(CinematicTrackKind::AssetStreaming),
        _ => None,
    }
}

fn cinematic_label_for_event(kind: &WorldEventKind) -> String {
    match kind {
        WorldEventKind::ForceApplied { entity } => format!("force applied to entity {entity}"),
        WorldEventKind::DamageApplied { entity, amount } => {
            format!("damage {amount:.2} applied to entity {entity}")
        }
        WorldEventKind::GlassWallFractured { entity } => {
            format!("glass wall fractured entity {entity}")
        }
        WorldEventKind::MaterialStateChanged { entity } => {
            format!("material state changed entity {entity}")
        }
        WorldEventKind::MeshReplaced { entity } => format!("mesh replaced entity {entity}"),
        WorldEventKind::StreetFlooded => "street flooded".to_string(),
        WorldEventKind::ToxicGasReleased => "toxic gas released".to_string(),
        WorldEventKind::DialogueEmitted { speaker, text, .. } => {
            format!(
                "dialogue entity {speaker}: {}",
                truncate_debug_text(text, 48)
            )
        }
        WorldEventKind::VoiceLineSpoken { speaker } => format!("voice line entity {speaker}"),
        WorldEventKind::SpeechSynthesized {
            speaker,
            viseme_count,
            ..
        } => format!("speech synthesized entity {speaker} with {viseme_count} viseme(s)"),
        WorldEventKind::FacialAnimationApplied {
            entity,
            viseme_count,
            ..
        } => format!("facial performance entity {entity} with {viseme_count} viseme(s)"),
        WorldEventKind::AgentDecisionExplained { agent, goal, .. } => {
            format!(
                "AI decision entity {agent}: {}",
                truncate_debug_text(goal, 48)
            )
        }
        WorldEventKind::AgentIntentProposed {
            agent,
            action,
            validation_passed,
            ..
        } => format!("AI intent entity {agent}: {action} accepted {validation_passed}"),
        WorldEventKind::AgentMemoryUpdated {
            agent, memory_kind, ..
        } => format!("AI memory entity {agent}: {memory_kind}"),
        WorldEventKind::NpcHeardSound { listener, .. } => {
            format!("NPC {listener} heard sound")
        }
        WorldEventKind::NpcWitnessedCrime { witness, .. } => {
            format!("NPC {witness} witnessed crime")
        }
        WorldEventKind::StoryEventEmitted { label } => format!("story event {label}"),
        WorldEventKind::SecurityAlertRaised {
            faction, severity, ..
        } => format!("security alert faction {faction} severity {severity:.2}"),
        WorldEventKind::FactionReputationChanged {
            faction,
            subject,
            delta,
            ..
        } => format!("faction {faction} reputation subject {subject} delta {delta:.2}"),
        WorldEventKind::SurveillanceIncreased {
            location, amount, ..
        } => format!("surveillance location {location} +{amount:.2}"),
        WorldEventKind::SoundEmitted {
            kind,
            source_entity,
            ..
        } => format!("sound {kind:?} source {source_entity:?}"),
        WorldEventKind::AudioFrameMixed {
            active_sound_count, ..
        } => format!("audio mix {active_sound_count} active sound(s)"),
        WorldEventKind::AssetStreamingRequested {
            asset_id,
            requester,
            ..
        } => format!("asset {asset_id} requested by module {requester}"),
        WorldEventKind::AssetBecameResident { asset_id, .. } => {
            format!("asset {asset_id} became resident")
        }
        WorldEventKind::HumanAppearanceUpdated { entity, .. } => {
            format!("human appearance updated entity {entity}")
        }
        WorldEventKind::TransformChanged { entity } => format!("transform changed entity {entity}"),
        WorldEventKind::AgentStateChanged { entity } => {
            format!("agent state changed entity {entity}")
        }
        WorldEventKind::PlayerIdentityExposed => "player identity exposed".to_string(),
        WorldEventKind::FactionLostTerritory { faction } => {
            format!("faction {faction} lost territory")
        }
        WorldEventKind::MetalBent {
            entity,
            plastic_strain,
        } => format!("metal bent entity {entity} strain {plastic_strain:.2}"),
        WorldEventKind::FlexibleConstraintResolved {
            entity,
            correction_meters,
        } => format!("constraint resolved entity {entity} by {correction_meters:.2}m"),
        WorldEventKind::PowerTransformerOverheated { entity } => {
            format!("power transformer overheated entity {entity}")
        }
        _ => format!("{kind:?}"),
    }
}

fn cinematic_source_event(kind: &WorldEventKind) -> Option<WorldEventId> {
    match kind {
        WorldEventKind::AgentDecisionExplained { source_event, .. }
        | WorldEventKind::AgentIntentProposed { source_event, .. }
        | WorldEventKind::AgentMemoryUpdated { source_event, .. } => *source_event,
        WorldEventKind::NpcHeardSound { event, .. }
        | WorldEventKind::NpcWitnessedCrime { event, .. }
        | WorldEventKind::SecurityAlertRaised {
            source_event: event,
            ..
        }
        | WorldEventKind::SurveillanceIncreased {
            source_event: event,
            ..
        } => Some(*event),
        _ => None,
    }
}

fn cinematic_track_count(tracks: &[CinematicTrackDebug], kind: CinematicTrackKind) -> usize {
    tracks
        .iter()
        .find(|track| track.kind == kind)
        .map(|track| track.beat_count)
        .unwrap_or_default()
}

fn push_cinematic_timeline_issue(
    report: &mut CinematicTimelineReport,
    severity: CinematicTimelineIssueSeverity,
    category: CinematicTimelineIssueCategory,
    code: impl Into<String>,
    subject: impl Into<String>,
    message: impl Into<String>,
) {
    report.issues.push(CinematicTimelineIssue {
        severity,
        category,
        code: code.into(),
        subject: subject.into(),
        message: message.into(),
    });
}

pub fn physics_consequence_lab_report_from_frames(
    frame_reports: &[FrameReport],
) -> PhysicsConsequenceLabReport {
    let events = frame_reports
        .iter()
        .flat_map(|report| report.events.iter())
        .collect::<Vec<_>>();
    let mut report = physics_consequence_lab_report_from_events(events);
    report.frame_count = frame_reports.len();
    report.simulation_lod = physics_simulation_lod_lab_report_from_frames(frame_reports);
    if report.frame_count > 0 && !report.simulation_lod.viewer_available {
        push_physics_lab_issue(
            &mut report,
            PhysicsLabIssueSeverity::Warning,
            PhysicsLabIssueCategory::SimulationLod,
            "missing_physics_lod_viewer",
            "physics_simulation_lod_selection",
            "physics lab should expose simulation LOD selection passes and decision buffers",
        );
    }
    report
}

pub fn physics_consequence_lab_report_from_events<'a>(
    events: impl IntoIterator<Item = &'a WorldEvent>,
) -> PhysicsConsequenceLabReport {
    let events = events.into_iter().collect::<Vec<_>>();
    let mut report = PhysicsConsequenceLabReport::default();
    let mut material_updates_by_entity = BTreeMap::<EntityId, Vec<WorldEventId>>::new();
    let mut mesh_replacements_by_entity = BTreeMap::<EntityId, Vec<WorldEventId>>::new();
    let mut physical_audio_by_entity = BTreeMap::<EntityId, Vec<WorldEventId>>::new();
    let mut ai_story_entities = BTreeSet::<EntityId>::new();
    let mut ai_story_source_events = BTreeSet::<WorldEventId>::new();
    let mut fracture_asset_streaming_requested = false;

    for event in &events {
        if let Some(physical_type) = event.kind.physical_type() {
            report.physical_events.push(PhysicsWorldEventDebug {
                event: event.event_id,
                tick: event.tick,
                physical_type,
                entity: physics_event_entity(&event.kind),
                location: vec3_debug(event.location_meters),
                evidence_count: event.physical_evidence.len(),
                narrative_tag_count: event.narrative_tags.len(),
            });
        }

        match &event.kind {
            WorldEventKind::MaterialStateChanged { entity } => {
                material_updates_by_entity
                    .entry(*entity)
                    .or_default()
                    .push(event.event_id);
                report.material_updates.push(PhysicsMaterialUpdateDebug {
                    entity: *entity,
                    event: event.event_id,
                    tick: event.tick,
                });
            }
            WorldEventKind::MeshReplaced { entity } => {
                mesh_replacements_by_entity
                    .entry(*entity)
                    .or_default()
                    .push(event.event_id);
                report.mesh_replacements.push(PhysicsMeshReplacementDebug {
                    entity: *entity,
                    event: event.event_id,
                    tick: event.tick,
                });
            }
            WorldEventKind::GlassWallFractured { entity } => {
                report.fractures.push(PhysicsFractureDebug {
                    event: event.event_id,
                    entity: *entity,
                    tick: event.tick,
                    material_updated: false,
                    mesh_replaced: false,
                    audio_emitted: false,
                    ai_or_story_reacted: false,
                    asset_streaming_requested: false,
                    evidence_refs: event.physical_evidence.clone(),
                });
            }
            WorldEventKind::StreetFlooded => {
                report.volume_events.push(PhysicsVolumeEventDebug {
                    kind: PhysicsVolumeKind::Fluid,
                    event: event.event_id,
                    tick: event.tick,
                    source_entities: event.actors.clone(),
                    location: vec3_debug(event.location_meters),
                    evidence_refs: event.physical_evidence.clone(),
                    medium: Some("water".to_string()),
                    density: None,
                    visibility_blocking: None,
                    hazard_level: None,
                    density_cell_count: None,
                    temperature_cell_count: None,
                    pressure_cell_count: None,
                    linked_material_update_count: 0,
                    linked_audio_count: 0,
                    linked_ai_reaction_count: 0,
                });
            }
            WorldEventKind::ToxicGasReleased => {
                let density = evidence_f32(&event.physical_evidence, "gas_density");
                let visibility_blocking =
                    evidence_f32(&event.physical_evidence, "visibility_blocking");
                let hazard_level = evidence_f32(&event.physical_evidence, "hazard_level");
                if density.is_none() || visibility_blocking.is_none() || hazard_level.is_none() {
                    push_physics_lab_issue(
                        &mut report,
                        PhysicsLabIssueSeverity::Warning,
                        PhysicsLabIssueCategory::Volume,
                        "gas_volume_missing_field_diagnostics",
                        format!("event:{}", event.event_id),
                        "gas/smoke test room needs density, visibility, and hazard evidence",
                    );
                }
                report.volume_events.push(PhysicsVolumeEventDebug {
                    kind: PhysicsVolumeKind::Gas,
                    event: event.event_id,
                    tick: event.tick,
                    source_entities: event.actors.clone(),
                    location: vec3_debug(event.location_meters),
                    evidence_refs: event.physical_evidence.clone(),
                    medium: evidence_string(&event.physical_evidence, "gas_kind"),
                    density,
                    visibility_blocking,
                    hazard_level,
                    density_cell_count: evidence_u64(&event.physical_evidence, "density_cells"),
                    temperature_cell_count: evidence_u64(
                        &event.physical_evidence,
                        "temperature_cells",
                    ),
                    pressure_cell_count: evidence_u64(&event.physical_evidence, "pressure_cells"),
                    linked_material_update_count: 0,
                    linked_audio_count: 0,
                    linked_ai_reaction_count: 0,
                });
            }
            WorldEventKind::SoundEmitted {
                kind,
                source_entity,
                material_id,
                intensity,
                radius_meters,
                occlusion_hint,
            } if audio_kind_is_physical(*kind) => {
                if let Some(entity) = source_entity {
                    physical_audio_by_entity
                        .entry(*entity)
                        .or_default()
                        .push(event.event_id);
                }
                if material_id.is_none() {
                    push_physics_lab_issue(
                        &mut report,
                        PhysicsLabIssueSeverity::Warning,
                        PhysicsLabIssueCategory::AudioBridge,
                        "physical_audio_missing_material",
                        format!("{kind:?}"),
                        "physics-origin sounds should carry material identity for synthesis",
                    );
                }
                report.audio_bridges.push(PhysicsAudioBridgeDebug {
                    event: event.event_id,
                    kind: *kind,
                    source_entity: *source_entity,
                    material_id: *material_id,
                    intensity: *intensity,
                    radius_meters: *radius_meters,
                    perceived_loudness: perceived_loudness(*intensity, *occlusion_hint),
                });
            }
            WorldEventKind::NpcHeardSound {
                event: source_event,
                source_entity,
                ..
            } => {
                ai_story_source_events.insert(*source_event);
                if let Some(entity) = source_entity {
                    ai_story_entities.insert(*entity);
                }
            }
            WorldEventKind::NpcWitnessedCrime { event, .. }
            | WorldEventKind::AgentMemoryUpdated {
                source_event: Some(event),
                ..
            }
            | WorldEventKind::AgentIntentProposed {
                source_event: Some(event),
                ..
            }
            | WorldEventKind::AgentDecisionExplained {
                source_event: Some(event),
                ..
            } => {
                ai_story_source_events.insert(*event);
            }
            WorldEventKind::StoryEventEmitted { .. }
            | WorldEventKind::SecurityAlertRaised { .. }
            | WorldEventKind::FactionReputationChanged { .. }
            | WorldEventKind::SurveillanceIncreased { .. } => {
                report.cross_system.story_events += 1;
            }
            WorldEventKind::AssetStreamingRequested { reason, .. } => {
                report.cross_system.asset_streaming_requests += 1;
                let normalized = reason.to_ascii_lowercase();
                if normalized.contains("fracture")
                    || normalized.contains("crack")
                    || normalized.contains("damage")
                {
                    fracture_asset_streaming_requested = true;
                }
            }
            _ => {}
        }
    }

    report.cross_system.material_updates = report.material_updates.len();
    report.cross_system.renderer_mesh_replacements = report.mesh_replacements.len();
    report.cross_system.physical_audio_events = report.audio_bridges.len();
    report.cross_system.ai_reactions = ai_story_entities.len() + ai_story_source_events.len();

    let fluid_material_updates = report.material_updates.len();
    let fluid_audio_count = report
        .audio_bridges
        .iter()
        .filter(|audio| matches!(audio.kind, AudioEventKind::WaterSplash))
        .count();
    let gas_audio_count = report
        .audio_bridges
        .iter()
        .filter(|audio| matches!(audio.kind, AudioEventKind::SteamLeak))
        .count();
    for volume in &mut report.volume_events {
        match volume.kind {
            PhysicsVolumeKind::Fluid => {
                volume.linked_material_update_count = fluid_material_updates;
                volume.linked_audio_count = fluid_audio_count;
                volume.linked_ai_reaction_count = ai_story_entities.len();
            }
            PhysicsVolumeKind::Gas => {
                volume.linked_audio_count = gas_audio_count;
                volume.linked_ai_reaction_count = ai_story_source_events.len();
            }
        }
    }

    let mut fracture_issues = Vec::new();
    for fracture in &mut report.fractures {
        fracture.material_updated = material_updates_by_entity.contains_key(&fracture.entity);
        fracture.mesh_replaced = mesh_replacements_by_entity.contains_key(&fracture.entity);
        fracture.audio_emitted = physical_audio_by_entity.contains_key(&fracture.entity);
        fracture.ai_or_story_reacted = ai_story_entities.contains(&fracture.entity)
            || ai_story_source_events.contains(&fracture.event);
        fracture.asset_streaming_requested = fracture_asset_streaming_requested;

        if !fracture.material_updated {
            fracture_issues.push(physics_lab_issue(
                PhysicsLabIssueSeverity::Error,
                PhysicsLabIssueCategory::MaterialState,
                "fracture_missing_material_state",
                format!("entity:{}", fracture.entity),
                "fracture should update material state so render/audio/AI see the damage",
            ));
        }
        if !fracture.mesh_replaced {
            fracture_issues.push(physics_lab_issue(
                PhysicsLabIssueSeverity::Error,
                PhysicsLabIssueCategory::RendererBridge,
                "fracture_missing_mesh_replacement",
                format!("entity:{}", fracture.entity),
                "fracture should produce a renderer-visible mesh replacement",
            ));
        }
        if !fracture.audio_emitted {
            fracture_issues.push(physics_lab_issue(
                PhysicsLabIssueSeverity::Error,
                PhysicsLabIssueCategory::AudioBridge,
                "fracture_missing_audio",
                format!("entity:{}", fracture.entity),
                "fracture should emit a physics-driven sound event",
            ));
        }
        if !fracture.ai_or_story_reacted {
            fracture_issues.push(physics_lab_issue(
                PhysicsLabIssueSeverity::Warning,
                PhysicsLabIssueCategory::AiStoryBridge,
                "fracture_missing_ai_story_reaction",
                format!("entity:{}", fracture.entity),
                "important physical consequences should be visible to AI or story systems",
            ));
        }
        if !fracture.asset_streaming_requested {
            fracture_issues.push(physics_lab_issue(
                PhysicsLabIssueSeverity::Warning,
                PhysicsLabIssueCategory::ConsequenceLink,
                "fracture_missing_streaming_request",
                format!("entity:{}", fracture.entity),
                "fracture should request generated/streamed assets when visual detail changes",
            ));
        }
    }
    report.issues.extend(fracture_issues);

    report.physical_event_count = report.physical_events.len();
    report.fracture_count = report.fractures.len();
    report.fluid_event_count = report
        .volume_events
        .iter()
        .filter(|volume| volume.kind == PhysicsVolumeKind::Fluid)
        .count();
    report.gas_event_count = report
        .volume_events
        .iter()
        .filter(|volume| volume.kind == PhysicsVolumeKind::Gas)
        .count();
    report.material_update_count = report.material_updates.len();
    report.mesh_replacement_count = report.mesh_replacements.len();
    report.physics_sound_count = report.audio_bridges.len();
    report
}

fn physics_simulation_lod_lab_report_from_frames(
    frame_reports: &[FrameReport],
) -> PhysicsSimulationLodLabReport {
    let mut report = PhysicsSimulationLodLabReport {
        frame_count: frame_reports.len(),
        ..PhysicsSimulationLodLabReport::default()
    };
    for frame in frame_reports {
        report.lod_pass_count += frame
            .gpu_passes
            .iter()
            .filter(|pass| pass.name == "physics_simulation_lod_selection")
            .count();
        report.physics_pipeline_count += frame
            .gpu_pipeline_report
            .pipelines
            .iter()
            .filter(|pipeline| pipeline.label.starts_with("physics_"))
            .count();
        for resource in &frame.gpu_registered_resource_usage {
            if resource.owner != Some(20) {
                continue;
            }
            report.physics_gpu_resource_count += 1;
            if resource.label == "physics simulation lod signal buffer" {
                report.lod_signal_resource_count += 1;
            }
            if resource.label == "physics simulation lod decision buffer" {
                report.lod_decision_resource_count += 1;
                report.estimated_decision_bytes = report
                    .estimated_decision_bytes
                    .saturating_add(resource.byte_len);
            }
        }
    }
    report.viewer_available = report.lod_pass_count > 0
        && report.lod_signal_resource_count > 0
        && report.lod_decision_resource_count > 0;
    report
}

fn physics_event_entity(kind: &WorldEventKind) -> Option<EntityId> {
    match kind {
        WorldEventKind::ForceApplied { entity }
        | WorldEventKind::DamageApplied { entity, .. }
        | WorldEventKind::MaterialStateChanged { entity }
        | WorldEventKind::GlassWallFractured { entity }
        | WorldEventKind::MetalBent { entity, .. }
        | WorldEventKind::FlexibleConstraintResolved { entity, .. }
        | WorldEventKind::PowerTransformerOverheated { entity } => Some(*entity),
        _ => None,
    }
}

fn push_physics_lab_issue(
    report: &mut PhysicsConsequenceLabReport,
    severity: PhysicsLabIssueSeverity,
    category: PhysicsLabIssueCategory,
    code: impl Into<String>,
    subject: impl Into<String>,
    message: impl Into<String>,
) {
    report.issues.push(physics_lab_issue(
        severity, category, code, subject, message,
    ));
}

fn physics_lab_issue(
    severity: PhysicsLabIssueSeverity,
    category: PhysicsLabIssueCategory,
    code: impl Into<String>,
    subject: impl Into<String>,
    message: impl Into<String>,
) -> PhysicsLabIssue {
    PhysicsLabIssue {
        severity,
        category,
        code: code.into(),
        subject: subject.into(),
        message: message.into(),
    }
}

pub fn material_lab_report_from_frames(frame_reports: &[FrameReport]) -> MaterialLabReport {
    let events = frame_reports
        .iter()
        .flat_map(|report| report.events.iter())
        .collect::<Vec<_>>();
    let mut report = material_lab_report_from_events(events);
    report.frame_count = frame_reports.len();
    report
}

pub fn material_lab_report_from_events<'a>(
    events: impl IntoIterator<Item = &'a WorldEvent>,
) -> MaterialLabReport {
    let events = events.into_iter().collect::<Vec<_>>();
    let mut report = MaterialLabReport::default();
    let mut material_update_events = Vec::<&WorldEvent>::new();
    let mut damage_entities = BTreeSet::<EntityId>::new();
    let mut wet_entities = BTreeSet::<EntityId>::new();
    let mut contamination_entities = BTreeSet::<EntityId>::new();
    let mut thermal_entities = BTreeSet::<EntityId>::new();
    let mut physical_cause_entities = BTreeSet::<EntityId>::new();
    let mut mesh_replacement_entities = BTreeSet::<EntityId>::new();
    let mut audio_by_entity = BTreeMap::<EntityId, Vec<WorldEventId>>::new();
    let mut cache_categories = BTreeSet::<MaterialStateChangeCategory>::new();
    let mut renderer_cache_categories = BTreeSet::<MaterialStateChangeCategory>::new();

    for event in events.iter().copied() {
        if event.kind.physical_type().is_some()
            && !matches!(&event.kind, WorldEventKind::MaterialStateChanged { .. })
            && let Some(entity) = physics_event_entity(&event.kind)
        {
            physical_cause_entities.insert(entity);
        }

        match &event.kind {
            WorldEventKind::DamageApplied { entity, .. }
            | WorldEventKind::GlassWallFractured { entity }
            | WorldEventKind::MetalBent { entity, .. } => {
                damage_entities.insert(*entity);
            }
            WorldEventKind::PowerTransformerOverheated { entity } => {
                thermal_entities.insert(*entity);
            }
            WorldEventKind::MaterialStateChanged { entity } => {
                material_update_events.push(event);
                match material_category_from_event_context(event) {
                    MaterialStateChangeCategory::Damage => {
                        damage_entities.insert(*entity);
                    }
                    MaterialStateChangeCategory::Wetness => {
                        wet_entities.insert(*entity);
                    }
                    MaterialStateChangeCategory::Contamination => {
                        contamination_entities.insert(*entity);
                    }
                    MaterialStateChangeCategory::ThermalElectrical => {
                        thermal_entities.insert(*entity);
                    }
                    MaterialStateChangeCategory::Unknown => {}
                }
            }
            WorldEventKind::MeshReplaced { entity } => {
                mesh_replacement_entities.insert(*entity);
                damage_entities.insert(*entity);
            }
            WorldEventKind::StreetFlooded => {
                report.cross_system.wetness_or_fluid_events += 1;
                let category = material_category_from_event_context(event);
                let affected_actors = if event.actors.len() > 1 {
                    &event.actors[1..]
                } else {
                    event.actors.as_slice()
                };
                match category {
                    MaterialStateChangeCategory::Wetness => {
                        wet_entities.extend(affected_actors.iter().copied());
                    }
                    MaterialStateChangeCategory::Contamination => {
                        contamination_entities.extend(affected_actors.iter().copied());
                        report.cross_system.contamination_or_residue_events += 1;
                    }
                    MaterialStateChangeCategory::Damage
                    | MaterialStateChangeCategory::ThermalElectrical
                    | MaterialStateChangeCategory::Unknown => {}
                }
            }
            WorldEventKind::SoundEmitted {
                kind,
                source_entity,
                ..
            } => {
                if audio_kind_is_physical(*kind)
                    && let Some(entity) = source_entity
                {
                    audio_by_entity
                        .entry(*entity)
                        .or_default()
                        .push(event.event_id);
                    match material_category_from_audio_event(event) {
                        MaterialStateChangeCategory::Wetness => {
                            wet_entities.insert(*entity);
                        }
                        MaterialStateChangeCategory::Contamination => {
                            contamination_entities.insert(*entity);
                        }
                        MaterialStateChangeCategory::ThermalElectrical => {
                            thermal_entities.insert(*entity);
                        }
                        MaterialStateChangeCategory::Damage
                        | MaterialStateChangeCategory::Unknown => {}
                    }
                }
            }
            WorldEventKind::AssetStreamingRequested {
                asset_id,
                requester,
                requested_quality,
                priority,
                reason,
            } if is_material_cache_request(reason) => {
                let category = material_category_from_text(reason);
                cache_categories.insert(category);
                if *requester == 10 {
                    renderer_cache_categories.insert(category);
                }
                report.cache_requests.push(MaterialCacheRequestDebug {
                    event: event.event_id,
                    tick: event.tick,
                    asset_id: *asset_id,
                    requester: *requester,
                    requested_quality: *requested_quality,
                    priority: *priority,
                    reason: reason.clone(),
                    category,
                });
            }
            _ => {}
        }
    }

    let mut update_issues = Vec::new();
    for event in material_update_events {
        let WorldEventKind::MaterialStateChanged { entity } = &event.kind else {
            continue;
        };
        let entity = *entity;
        let category = material_category_for_update(
            event,
            entity,
            &damage_entities,
            &wet_entities,
            &contamination_entities,
            &thermal_entities,
        );
        let has_cache_request = material_category_has_cache(category, &cache_categories);
        let has_render_link = mesh_replacement_entities.contains(&entity)
            || material_category_has_cache(category, &renderer_cache_categories);
        let has_audio_link = audio_by_entity.contains_key(&entity);
        let has_physics_cause = physical_cause_entities.contains(&entity)
            || damage_entities.contains(&entity)
            || wet_entities.contains(&entity)
            || thermal_entities.contains(&entity)
            || !event.physical_evidence.is_empty();

        match category {
            MaterialStateChangeCategory::Damage => report.damage_update_count += 1,
            MaterialStateChangeCategory::Wetness => report.wetness_update_count += 1,
            MaterialStateChangeCategory::Contamination => report.contamination_update_count += 1,
            MaterialStateChangeCategory::ThermalElectrical => report.thermal_update_count += 1,
            MaterialStateChangeCategory::Unknown => report.unknown_update_count += 1,
        }
        if has_render_link {
            report.render_link_count += 1;
        }
        if has_audio_link {
            report.audio_link_count += 1;
        }
        if has_physics_cause {
            report.physics_cause_count += 1;
        }

        if category == MaterialStateChangeCategory::Unknown {
            update_issues.push(material_lab_issue(
                MaterialLabIssueSeverity::Warning,
                MaterialLabIssueCategory::StateClassification,
                "unknown_material_state_category",
                format!("entity:{entity}"),
                "material state update should expose whether it changed damage, wetness, or another physical channel",
            ));
        }
        if matches!(
            category,
            MaterialStateChangeCategory::Damage
                | MaterialStateChangeCategory::Wetness
                | MaterialStateChangeCategory::Contamination
        ) && !has_cache_request
        {
            update_issues.push(material_lab_issue(
                MaterialLabIssueSeverity::Error,
                MaterialLabIssueCategory::Cache,
                "material_state_missing_cache_request",
                format!("entity:{entity}"),
                "damage, wetness, and contamination changes should request or reuse a generated material cache",
            ));
        }
        if matches!(
            category,
            MaterialStateChangeCategory::Damage
                | MaterialStateChangeCategory::Wetness
                | MaterialStateChangeCategory::Contamination
        ) && !has_render_link
        {
            update_issues.push(material_lab_issue(
                MaterialLabIssueSeverity::Error,
                MaterialLabIssueCategory::RendererBridge,
                "material_state_missing_renderer_link",
                format!("entity:{entity}"),
                "visible material changes should be connected to renderer mesh or material-cache work",
            ));
        }
        if matches!(
            category,
            MaterialStateChangeCategory::Damage
                | MaterialStateChangeCategory::Wetness
                | MaterialStateChangeCategory::Contamination
        ) && !has_audio_link
        {
            update_issues.push(material_lab_issue(
                MaterialLabIssueSeverity::Warning,
                MaterialLabIssueCategory::AudioBridge,
                "material_state_missing_audio_link",
                format!("entity:{entity}"),
                "important material changes should have material-aware audio when they are player-visible",
            ));
        }
        if !has_physics_cause {
            update_issues.push(material_lab_issue(
                MaterialLabIssueSeverity::Warning,
                MaterialLabIssueCategory::PhysicsBridge,
                "material_state_missing_physics_cause",
                format!("entity:{entity}"),
                "material state should be traceable back to a physical cause or evidence reference",
            ));
        }

        report.material_updates.push(MaterialStateUpdateDebug {
            entity,
            event: event.event_id,
            tick: event.tick,
            category,
            physical_evidence: event.physical_evidence.clone(),
            has_cache_request,
            has_render_link,
            has_audio_link,
            has_physics_cause,
        });
    }

    report.issues.extend(update_issues);
    report.material_update_count = report.material_updates.len();
    report.cache_request_count = report.cache_requests.len();
    report.cross_system.material_cache_requests = report.cache_request_count;
    report.cross_system.renderer_links = report.render_link_count;
    report.cross_system.audio_links = report.audio_link_count;
    report.cross_system.physics_causes = report.physics_cause_count;
    report.cross_system.mesh_replacements = mesh_replacement_entities.len();
    report.cross_system.damage_or_fracture_events = damage_entities.len();
    report.cross_system.wetness_or_fluid_events += wet_entities.len();
    report.cross_system.contamination_or_residue_events += contamination_entities.len();
    report
}

fn material_category_for_update(
    event: &WorldEvent,
    entity: EntityId,
    damage_entities: &BTreeSet<EntityId>,
    wet_entities: &BTreeSet<EntityId>,
    contamination_entities: &BTreeSet<EntityId>,
    thermal_entities: &BTreeSet<EntityId>,
) -> MaterialStateChangeCategory {
    let direct = material_category_from_event_context(event);
    if direct != MaterialStateChangeCategory::Unknown {
        return direct;
    }
    if damage_entities.contains(&entity) {
        MaterialStateChangeCategory::Damage
    } else if wet_entities.contains(&entity) {
        MaterialStateChangeCategory::Wetness
    } else if contamination_entities.contains(&entity) {
        MaterialStateChangeCategory::Contamination
    } else if thermal_entities.contains(&entity) {
        MaterialStateChangeCategory::ThermalElectrical
    } else {
        MaterialStateChangeCategory::Unknown
    }
}

fn material_category_from_audio_event(event: &WorldEvent) -> MaterialStateChangeCategory {
    let direct = material_category_from_event_context(event);
    if direct != MaterialStateChangeCategory::Unknown {
        return direct;
    }
    match &event.kind {
        WorldEventKind::SoundEmitted {
            kind: AudioEventKind::WaterSplash,
            ..
        } => MaterialStateChangeCategory::Wetness,
        WorldEventKind::SoundEmitted {
            kind: AudioEventKind::SteamLeak,
            ..
        } => MaterialStateChangeCategory::ThermalElectrical,
        _ => MaterialStateChangeCategory::Unknown,
    }
}

fn material_category_from_event_context(event: &WorldEvent) -> MaterialStateChangeCategory {
    let mut best = MaterialStateChangeCategory::Unknown;
    for text in event
        .physical_evidence
        .iter()
        .chain(event.narrative_tags.iter())
    {
        let category = material_category_from_text(text);
        if category == MaterialStateChangeCategory::Damage {
            return category;
        }
        if best == MaterialStateChangeCategory::Unknown
            && category != MaterialStateChangeCategory::Unknown
        {
            best = category;
        }
    }
    best
}

fn material_category_from_text(text: &str) -> MaterialStateChangeCategory {
    let normalized = text.to_ascii_lowercase();
    if contains_any(
        &normalized,
        &[
            "break", "broken", "chip", "crack", "damage", "fracture", "interior", "shard",
            "shatter",
        ],
    ) {
        MaterialStateChangeCategory::Damage
    } else if contains_any(
        &normalized,
        &[
            "darkening",
            "fluid",
            "moist",
            "puddle",
            "rain",
            "reflection",
            "splash",
            "water",
            "wet",
        ],
    ) {
        MaterialStateChangeCategory::Wetness
    } else if contains_any(
        &normalized,
        &[
            "burn", "electric", "heat", "overheat", "power", "steam", "thermal",
        ],
    ) {
        MaterialStateChangeCategory::ThermalElectrical
    } else if contains_any(
        &normalized,
        &[
            "biohazard",
            "biological",
            "blood",
            "contaminated",
            "contamination",
            "corrosion",
            "dirt",
            "fuel",
            "grease",
            "grime",
            "hydraulic",
            "oil",
            "patina",
            "pollution",
            "residue",
            "rust",
            "slick",
            "soot",
        ],
    ) {
        MaterialStateChangeCategory::Contamination
    } else {
        MaterialStateChangeCategory::Unknown
    }
}

fn material_category_has_cache(
    category: MaterialStateChangeCategory,
    cache_categories: &BTreeSet<MaterialStateChangeCategory>,
) -> bool {
    if cache_categories.contains(&category) {
        return true;
    }
    category == MaterialStateChangeCategory::Unknown && !cache_categories.is_empty()
}

fn is_material_cache_request(reason: &str) -> bool {
    let normalized = reason.to_ascii_lowercase();
    material_category_from_text(&normalized) != MaterialStateChangeCategory::Unknown
        || contains_any(&normalized, &["cache", "material", "procedural", "surface"])
}

fn contains_any(text: &str, needles: &[&str]) -> bool {
    needles.iter().any(|needle| text.contains(needle))
}

fn material_lab_issue(
    severity: MaterialLabIssueSeverity,
    category: MaterialLabIssueCategory,
    code: impl Into<String>,
    subject: impl Into<String>,
    message: impl Into<String>,
) -> MaterialLabIssue {
    MaterialLabIssue {
        severity,
        category,
        code: code.into(),
        subject: subject.into(),
        message: message.into(),
    }
}

pub fn city_generation_inspector_report_from_template(
    template: &WorldTemplate,
) -> CityGenerationInspectorReport {
    let package_manifests = build_world_template_package_manifests(template);
    let city_cell_manifest_validation_error_count = package_manifests
        .iter()
        .map(|manifest| manifest.validate(TOOLS_SYSTEM_ID).errors.len())
        .sum();
    let city_cell_manifest_total_bytes = package_manifests
        .iter()
        .map(|manifest| manifest.total_uncompressed_bytes)
        .sum();
    let unique_streaming_dependencies = template
        .chunks
        .iter()
        .flat_map(|chunk| chunk.streaming_dependencies.iter().copied())
        .collect::<BTreeSet<_>>();
    let estimated_streaming_memory_bytes = unique_streaming_dependencies
        .iter()
        .map(|asset| estimated_city_streaming_asset_bytes(*asset))
        .sum();
    let material_cache_dependency_count = unique_streaming_dependencies
        .iter()
        .filter(|asset| is_worldgen_material_cache_asset(**asset))
        .count();
    let packaged_geometry_chunk_count = template
        .city_cell_packages
        .iter()
        .map(|package| package.geometry_chunks.len())
        .sum();
    let packaged_material_package_count = template
        .city_cell_packages
        .iter()
        .map(|package| package.material_packages.len())
        .sum();
    let material_package_descriptor_count = template
        .city_cell_packages
        .iter()
        .map(|package| package.material_package_descriptors.len())
        .sum();
    let material_package_validation_passed_count = template
        .city_cell_packages
        .iter()
        .flat_map(|package| package.material_package_descriptors.iter())
        .filter(|descriptor| descriptor.validation_passed)
        .count();
    let material_package_capture_evidence_count = template
        .city_cell_packages
        .iter()
        .flat_map(|package| package.material_package_descriptors.iter())
        .filter(|descriptor| descriptor.capture_confidence >= 0.65)
        .count();
    let material_package_scan_set_count = template
        .city_cell_packages
        .iter()
        .flat_map(|package| package.material_package_descriptors.iter())
        .map(|descriptor| descriptor.scan_set_count)
        .sum();
    let material_package_state_response_count = template
        .city_cell_packages
        .iter()
        .flat_map(|package| package.material_package_descriptors.iter())
        .map(|descriptor| descriptor.state_response_channels.len())
        .sum();
    let average_material_package_capture_confidence = if material_package_descriptor_count == 0 {
        0.0
    } else {
        template
            .city_cell_packages
            .iter()
            .flat_map(|package| package.material_package_descriptors.iter())
            .map(|descriptor| descriptor.capture_confidence)
            .sum::<f32>()
            / material_package_descriptor_count as f32
    };
    let story_opportunities = city_story_opportunities(template);
    let streaming_cells = city_streaming_cells(template, &package_manifests);
    let population_summary_validation_passed_count = streaming_cells
        .iter()
        .filter(|cell| cell.population_summary_validation_passed)
        .count();
    let population_summary_issue_count = streaming_cells
        .iter()
        .map(|cell| cell.population_summary_issue_count)
        .sum();
    let average_population_activity = if streaming_cells.is_empty() {
        0.0
    } else {
        streaming_cells
            .iter()
            .map(|cell| cell.population_activity)
            .sum::<f32>()
            / streaming_cells.len() as f32
    };
    let districts = city_districts(template, &story_opportunities);
    let infrastructure = city_infrastructure_systems(template);
    let faction_territory = city_faction_territory(template);
    let material_placements = city_material_placements(template);
    let validation_issues = template
        .validation_report
        .issues
        .iter()
        .map(|issue| CityValidationIssueDebug {
            severity: city_validation_severity(issue.severity),
            code: issue.code.clone(),
            message: issue.message.clone(),
        })
        .collect::<Vec<_>>();
    let budget = &template.validation_report.budget;

    CityGenerationInspectorReport {
        city_id: template.city_id,
        seed: template.seed,
        validation_passed: template.validation_report.passed,
        district_count: template.districts.len(),
        material_variant_count: template.materials.len(),
        assigned_material_variant_count: material_placements.len(),
        streaming_cell_count: template.chunks.len(),
        city_cell_package_count: template.city_cell_packages.len(),
        city_cell_manifest_count: package_manifests.len(),
        city_cell_manifest_validation_error_count,
        city_cell_manifest_total_bytes,
        packaged_geometry_chunk_count,
        packaged_material_package_count,
        material_package_descriptor_count,
        material_package_validation_passed_count,
        material_package_capture_evidence_count,
        material_package_scan_set_count,
        material_package_state_response_count,
        average_material_package_capture_confidence,
        faction_count: template.factions.len(),
        story_seed_count: story_opportunities.len(),
        crowd_spawn_rule_count: budget.crowd_spawn_rule_count,
        traffic_rule_count: budget.traffic_rule_count,
        expected_background_crowd_count: budget.expected_background_crowd_count,
        expected_vehicle_or_transit_count: budget.expected_vehicle_or_transit_count,
        population_summary_validation_passed_count,
        population_summary_issue_count,
        average_population_activity,
        unique_streaming_dependency_count: unique_streaming_dependencies.len(),
        material_cache_dependency_count,
        estimated_streaming_memory_bytes,
        budget: CityBudgetDebug {
            entity_count: budget.entity_count,
            unique_material_count: budget.unique_material_count,
            dynamic_light_count: budget.dynamic_light_count,
            physics_active_object_count: budget.physics_active_object_count,
            destructible_count: budget.destructible_count,
            liquid_zone_count: budget.liquid_zones,
            npc_count: budget.npc_count,
            crowd_spawn_rule_count: budget.crowd_spawn_rule_count,
            traffic_rule_count: budget.traffic_rule_count,
            expected_background_crowd_count: budget.expected_background_crowd_count,
            expected_vehicle_or_transit_count: budget.expected_vehicle_or_transit_count,
            streaming_dependency_count: budget.streaming_dependency_count,
            streaming_memory_bytes: budget.streaming_memory_bytes,
            target_platform_budget: budget.target_platform_budget,
        },
        districts,
        streaming_cells,
        infrastructure,
        faction_territory,
        story_opportunities,
        material_placements,
        validation_issues,
    }
}

pub fn city_streaming_planner_report_from_plan(
    plan: &CityStreamingPlan,
) -> CityStreamingPlannerReport {
    let mut unique_requested_assets = BTreeSet::new();
    let mut report = CityStreamingPlannerReport {
        cell_count: plan.cell_count,
        loaded_cell_count: plan.loaded_cell_count,
        hero_loaded_count: plan.hero_loaded_count,
        render_high_detail_count: plan.render_high_detail_count,
        gameplay_loaded_count: plan.gameplay_loaded_count,
        summary_loaded_count: plan.summary_loaded_count,
        unloaded_count: plan.unloaded_count,
        requested_asset_count: plan.requested_asset_count,
        requested_streaming_bytes: plan.requested_streaming_bytes,
        max_loaded_bytes: plan.max_loaded_bytes,
        ..CityStreamingPlannerReport::default()
    };

    for cell in &plan.cells {
        unique_requested_assets.extend(cell.requested_assets.iter().copied());
        report.peak_priority_score = report.peak_priority_score.max(cell.priority_score);
        report.cells.push(city_streaming_plan_cell_debug(cell));
    }
    report.unique_requested_asset_count = unique_requested_assets.len();
    report.cells.sort_by(|left, right| {
        right
            .priority_score
            .partial_cmp(&left.priority_score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then(left.chunk.cmp(&right.chunk))
    });
    report.issues = plan
        .issues
        .iter()
        .map(|issue| CityStreamingPlannerIssueDebug {
            severity: city_persistence_issue_severity(issue.severity),
            code: issue.code.clone(),
            subject: "city_streaming".to_string(),
            message: issue.message.clone(),
        })
        .collect();
    report
}

