pub fn city_navigation_inspector_report_from_events(
    template: &WorldTemplate,
    events: &[WorldEvent],
) -> CityNavigationInspectorReport {
    let persistence = persistent_city_state_from_events(template, events);
    let states = navigation_cell_states_from_persistence(template, &persistence);
    city_navigation_inspector_report_from_states(template, &states)
}

pub fn city_navigation_inspector_report_from_states(
    template: &WorldTemplate,
    states: &[NavigationCellState],
) -> CityNavigationInspectorReport {
    let mut report = CityNavigationInspectorReport {
        city_id: template.city_id,
        seed: template.seed,
        ..CityNavigationInspectorReport::default()
    };

    for state in states {
        let cell = city_navigation_cell_debug(state);
        report.total_node_count += cell.node_count;
        report.total_edge_count += cell.edge_count;
        report.important_location_count += cell.important_location_count;
        report.reachable_important_location_count += cell.reachable_important_location_count;
        report.dynamic_blocker_count += cell.dynamic_blocker_count;
        report.danger_field_count += cell.danger_field_count;
        report.restricted_zone_count += cell.restricted_zone_count;
        report.route_update_count += cell.route_update_count;
        report.blocked_route_count += cell.blocked_route_count;
        report.dangerous_route_count += cell.dangerous_route_count;
        report.restricted_route_count += cell.restricted_route_count;
        if cell.reachable_important_location_count < cell.important_location_count {
            report.partially_unreachable_cell_count += 1;
        }
        if state.is_changed() {
            report.changed_cell_count += 1;
        }

        for issue in &state.issues {
            report.issues.push(CityNavigationIssueDebug {
                severity: city_persistence_issue_severity(issue.severity),
                code: issue.code.clone(),
                subject: format!("cell:{}", state.cell_id),
                message: issue.message.clone(),
            });
        }
        report.cells.push(cell);
    }

    report.cell_count = report.cells.len();
    report.cells.sort_by(|left, right| {
        right
            .route_update_count
            .cmp(&left.route_update_count)
            .then(right.dynamic_blocker_count.cmp(&left.dynamic_blocker_count))
            .then(left.chunk.cmp(&right.chunk))
    });
    report
}

fn city_navigation_cell_debug(state: &NavigationCellState) -> CityNavigationCellDebug {
    let blocked_route_count = state
        .route_updates
        .iter()
        .filter(|route| route.status == NavigationRouteStatus::Blocked)
        .count();
    let dangerous_route_count = state
        .route_updates
        .iter()
        .filter(|route| route.status == NavigationRouteStatus::Dangerous)
        .count();
    let restricted_route_count = state
        .route_updates
        .iter()
        .filter(|route| route.status == NavigationRouteStatus::Restricted)
        .count();
    let danger_kinds = state
        .danger_fields
        .iter()
        .map(|field| field.kind)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();

    CityNavigationCellDebug {
        chunk: state.cell_id,
        district: state.district_id,
        node_count: state.node_count,
        edge_count: state.edge_count,
        important_location_count: state.important_location_count,
        reachable_important_location_count: state.reachable_important_location_count,
        dynamic_blocker_count: state.dynamic_blockers.len(),
        danger_field_count: state.danger_fields.len(),
        restricted_zone_count: state.restricted_zones.len(),
        route_update_count: state.route_updates.len(),
        blocked_route_count,
        dangerous_route_count,
        restricted_route_count,
        danger_kinds,
        issue_count: state.issues.len(),
    }
}

