    #[test]
    fn asset_pipeline_builds_versioned_package_and_registers_runtime_asset() {
        let request = AssetBuildRequest {
            source_asset: 44,
            target_kind: AssetKind::MaterialGraph,
            build_profile: BuildProfile::Editor,
            validation_level: ValidationLevel::Editor,
            dependency_policy: DependencyPolicy::RequireDeclared,
        };
        let result = build_runtime_package(&request, &source_asset(), &schema_registry());

        assert!(result.validation_report.passed);
        assert_eq!(result.package.header.magic, ASSET_PACKAGE_MAGIC);
        assert_eq!(result.package.header.dependency_count, 2);
        assert_eq!(
            result.package.chunks[0].usage,
            AssetChunkUsage::MaterialGraph
        );
        assert_eq!(result.package.total_uncompressed_bytes(), 4096);

        let mut registry = AssetRegistry::default();
        assert_eq!(
            register_built_asset(&mut registry, &result),
            Some(result.asset_id)
        );
        let record = registry
            .get(result.asset_id)
            .expect("built asset should be registered");
        assert!(record.generated);
        assert_eq!(record.kind, AssetKind::MaterialGraph);
        assert_eq!(record.dependencies, vec![1001, 1002]);
        assert_eq!(record.load_state, AssetLoadState::Unloaded);
    }

    #[test]
    fn asset_inventory_reports_load_states_kinds_and_missing_dependencies() {
        let mut registry = AssetRegistry::default();
        registry.register_known(AssetRecord {
            id: 200,
            kind: AssetKind::Mesh,
            label: "broken test mesh".to_string(),
            provenance: "test".to_string(),
            dependencies: vec![999],
            byte_len: Some(2048),
            generated: false,
            quality_tier: QualityTier::NormalRuntime,
            load_state: AssetLoadState::Failed,
        });
        registry.register_known(AssetRecord {
            id: 201,
            kind: AssetKind::MaterialGraph,
            label: "generated material".to_string(),
            provenance: "test".to_string(),
            dependencies: Vec::new(),
            byte_len: Some(1024),
            generated: true,
            quality_tier: QualityTier::NormalRuntime,
            load_state: AssetLoadState::Resident,
        });

        let inventory = inventory_registered_assets(&registry);

        assert_eq!(inventory.total_assets, 2);
        assert_eq!(inventory.generated_assets, 1);
        assert_eq!(inventory.failed_assets, 1);
        assert_eq!(inventory.resident_assets, 1);
        assert_eq!(inventory.total_known_bytes, 3072);
        assert_eq!(
            inventory.missing_dependency_edges,
            vec![AssetDependencyIssue {
                asset_id: 200,
                missing_dependency: 999
            }]
        );
        assert!(!inventory.passed());
        assert!(
            inventory
                .by_kind
                .iter()
                .any(|kind| kind.kind_label == "Mesh" && kind.asset_count == 1)
        );
        assert!(
            inventory
                .by_kind
                .iter()
                .any(|kind| kind.kind_label == "MaterialGraph" && kind.known_bytes == 1024)
        );
    }

    #[test]
    fn asset_browser_reports_packages_runtime_assets_schemas_and_dependencies() {
        let request = AssetBuildRequest {
            source_asset: 44,
            target_kind: AssetKind::MaterialGraph,
            build_profile: BuildProfile::Editor,
            validation_level: ValidationLevel::Editor,
            dependency_policy: DependencyPolicy::RequireDeclared,
        };
        let result = build_runtime_package(&request, &source_asset(), &schema_registry());
        let mut registry = AssetRegistry::default();
        registry.register_known(AssetRecord {
            id: 1001,
            kind: AssetKind::Texture,
            label: "albedo reference".to_string(),
            provenance: "artist:test".to_string(),
            dependencies: Vec::new(),
            byte_len: Some(2048),
            generated: false,
            quality_tier: QualityTier::NormalRuntime,
            load_state: AssetLoadState::Resident,
        });
        registry.register_known(AssetRecord {
            id: 1002,
            kind: AssetKind::Mesh,
            label: "scan reference".to_string(),
            provenance: "scan:test".to_string(),
            dependencies: Vec::new(),
            byte_len: Some(4096),
            generated: false,
            quality_tier: QualityTier::NormalRuntime,
            load_state: AssetLoadState::Resident,
        });
        assert_eq!(
            register_built_asset(&mut registry, &result),
            Some(result.asset_id)
        );

        let report = asset_browser_report_from_runtime(std::slice::from_ref(&result), &registry);

        assert!(report.passed());
        assert_eq!(report.package_count, 1);
        assert_eq!(report.runtime_asset_count, 3);
        assert_eq!(report.generated_runtime_asset_count, 1);
        assert_eq!(report.resident_runtime_asset_count, 2);
        assert_eq!(report.dependency_edge_count, 4);
        assert_eq!(report.missing_runtime_dependency_count, 0);
        assert_eq!(report.schema_count, 1);
        assert_eq!(report.validation_error_count, 0);
        assert_eq!(report.packages[0].source_asset, 44);
        assert_eq!(report.packages[0].schema_name, "ProceduralMaterialGraph");
        assert_eq!(report.packages[0].schema_version, 2);
        assert_eq!(report.packages[0].dependency_count, 2);
        assert!(
            report
                .runtime_assets
                .iter()
                .any(|asset| asset.asset_id == result.asset_id
                    && asset.generated
                    && asset.schema_name.as_deref() == Some("ProceduralMaterialGraph"))
        );
        assert!(
            report
                .kind("MaterialGraph")
                .is_some_and(|kind| kind.package_count == 1
                    && kind.runtime_asset_count == 1
                    && kind.generated_runtime_asset_count == 1)
        );
        assert!(
            report
                .schemas
                .iter()
                .any(|schema| schema.schema_name == "ProceduralMaterialGraph"
                    && schema.package_count == 1
                    && schema.runtime_asset_count == 1)
        );

        let mut broken_registry = registry;
        broken_registry.register_known(AssetRecord {
            id: 300,
            kind: AssetKind::Shader,
            label: "dangling shader".to_string(),
            provenance: "test".to_string(),
            dependencies: vec![999],
            byte_len: Some(512),
            generated: false,
            quality_tier: QualityTier::NormalRuntime,
            load_state: AssetLoadState::Resident,
        });
        let broken_report =
            asset_browser_report_from_runtime(std::slice::from_ref(&result), &broken_registry);

        assert!(!broken_report.passed());
        assert_eq!(broken_report.missing_runtime_dependency_count, 1);
        assert!(
            broken_report
                .issues
                .iter()
                .any(|issue| issue.code == "missing_runtime_dependency")
        );
    }

    #[test]
    fn schema_inspector_reports_registered_requirements_packages_and_migrations() {
        let mut schemas = schema_registry();
        schemas.register_migration(SchemaMigrationStep {
            schema_name: "ProceduralMaterialGraph".to_string(),
            from_version: 2,
            to_version: 3,
            description: "promote material graph metadata without data loss".to_string(),
            lossless: true,
        });
        let request = AssetBuildRequest {
            source_asset: 44,
            target_kind: AssetKind::MaterialGraph,
            build_profile: BuildProfile::Editor,
            validation_level: ValidationLevel::Editor,
            dependency_policy: DependencyPolicy::RequireDeclared,
        };
        let result = build_runtime_package(&request, &source_asset(), &schemas);
        let requirements = vec![SchemaRequirement::required(
            90,
            "ProceduralMaterialGraph",
            3,
            "editor material lab wants migrated graph metadata",
        )];
        let module_registry = ModuleRegistryReport {
            static_module_count: 1,
            dynamic_module_api_version: 1,
            modules: vec![ashfall_core::runtime::RegisteredModuleReport {
                descriptor: ModuleDescriptor {
                    module_id: 90,
                    name: "editor_material_lab",
                    schema: SchemaVersion {
                        name: "EditorMaterialLab",
                        version: 1,
                    },
                    default_quality: QualityTier::NormalRuntime,
                },
                schema_requirements: requirements.clone(),
            }],
            schema_compatibility: schemas.check_requirements(&requirements),
        };

        let report = schema_inspector_report_from_runtime(
            std::slice::from_ref(&result),
            &schemas,
            &module_registry,
            &[],
        );

        assert!(report.passed());
        assert_eq!(report.registered_schema_count, 1);
        assert_eq!(report.module_requirement_count, 1);
        assert_eq!(report.package_schema_count, 1);
        assert_eq!(report.owner_count, 1);
        assert_eq!(report.migration_step_count, 1);
        assert_eq!(report.validation_error_count, 0);
        assert_eq!(report.compatibility_issue_count, 1);
        assert!(
            report
                .registered_schema("ProceduralMaterialGraph")
                .is_some_and(|schema| schema.owner == 30
                    && schema.version == 2
                    && schema.required_by_count == 1
                    && schema.package_count == 1
                    && schema.migration_step_count == 1)
        );
        assert!(
            report
                .module_requirements
                .iter()
                .any(
                    |requirement| requirement.schema_name == "ProceduralMaterialGraph"
                        && requirement.minimum_version == 3
                        && requirement.satisfied
                        && requirement.migration_available
                        && requirement.registered_version == Some(2)
                )
        );
        assert!(
            report
                .package_schemas
                .iter()
                .any(|schema| schema.asset_id == result.asset_id
                    && schema.schema_name == "ProceduralMaterialGraph"
                    && schema.schema_version == 2
                    && schema.validation_passed)
        );
        assert!(
            report
                .issues
                .iter()
                .any(|issue| issue.severity == SchemaInspectorSeverity::Warning
                    && issue.code == "schema_migration_available")
        );

        let broken = schema_inspector_report_from_pipeline(&[build_runtime_package(
            &request,
            &source_asset(),
            &SchemaRegistry::default(),
        )]);

        assert!(!broken.passed());
        assert_eq!(broken.validation_error_count, 1);
        assert!(
            broken
                .issues
                .iter()
                .any(|issue| issue.code == "package_schema_schema_missing")
        );
    }

    #[test]
    fn asset_validation_rejects_bad_package_metadata_and_schema_mismatch() {
        let request = AssetBuildRequest {
            source_asset: 44,
            target_kind: AssetKind::MaterialGraph,
            build_profile: BuildProfile::Research,
            validation_level: ValidationLevel::Reference,
            dependency_policy: DependencyPolicy::RequireDeclared,
        };
        let mut result =
            build_runtime_package(&request, &source_asset(), &SchemaRegistry::default());
        result.package.header.magic = *b"NOTREAL!";
        result.package.header.dependency_count = 9;
        result.package.chunks[0].content_hash = 0;
        result.package.validation_score_basis_points = 4_000;

        let report =
            validate_asset_build_package(&request, &result.package, &SchemaRegistry::default());

        assert!(!report.passed);
        assert!(report.issues.iter().any(|issue| issue.code == "bad_magic"));
        assert!(
            report
                .issues
                .iter()
                .any(|issue| issue.code == "dependency_count_mismatch")
        );
        assert!(
            report
                .issues
                .iter()
                .any(|issue| issue.code == "missing_chunk_hash")
        );
        assert!(
            report
                .issues
                .iter()
                .any(|issue| issue.code == "validation_score_too_low")
        );
        assert!(
            report
                .issues
                .iter()
                .any(|issue| issue.code == "schema_schema_missing")
        );
    }

