    #[test]
    fn voice_audio_lab_inspects_performance_capture_contract_and_budget() {
        let request = capture_speech_request();
        let clip = tools_performance_capture_clip(&request);

        let report = voice_audio_lab_report_from_performance_capture_clips([(&request, &clip)]);

        assert_eq!(report.performance_capture_count, 1);
        assert_eq!(report.validated_performance_capture_count, 1);
        assert_eq!(report.unique_voice_personas, vec![request.voice_persona]);
        assert_eq!(report.performance_captures[0].source_label, "actor_session");
        assert_eq!(report.performance_captures[0].phoneme_count, 2);
        assert_eq!(report.performance_captures[0].face_curve_count, 2);
        assert!(report.performance_captures[0].rights_verified);
        assert!(report.performance_captures[0].retargeting_allowed);
        assert!(report.performance.budget_visible);
        assert_eq!(report.performance.performance_capture_count, 1);
        assert_eq!(report.performance.validated_performance_capture_count, 1);
        assert!(report.performance.capture_memory_bytes >= 64 * 1024);
        assert!(report.performance.max_capture_sync_error_seconds < 0.03);
        assert!(report.performance.passed);
        assert_eq!(report.critical_issue_count(), 0);

        let mut unlicensed_clip = clip.clone();
        unlicensed_clip.provenance.rights_verified = false;
        unlicensed_clip.calibration.audio_video_offset_seconds = 0.22;

        let failed_report =
            voice_audio_lab_report_from_performance_capture_clips([(&request, &unlicensed_clip)]);

        assert_eq!(failed_report.performance_capture_count, 1);
        assert_eq!(failed_report.validated_performance_capture_count, 0);
        assert!(!failed_report.performance.passed);
        assert!(failed_report.issues.iter().any(|issue| issue.category
            == VoiceAudioIssueCategory::PerformanceCapture
            && issue.code == "capture_provenance_unverified"));
        assert!(failed_report.issues.iter().any(|issue| issue.category
            == VoiceAudioIssueCategory::PerformanceCapture
            && issue.code == "capture_sync_error"));
    }

    #[test]
    fn human_lab_pairs_dialogue_speech_face_surface_and_bundle_requests() {
        let events = vec![
            WorldEvent {
                event_id: 16,
                tick: 1,
                location_meters: Vec3::ZERO,
                actors: vec![3],
                kind: WorldEventKind::DialogueEmitted {
                    speaker: 3,
                    target: Some(1),
                    text: "I saw that. Security will hear about this.".to_string(),
                    emotion: ashfall_core::core::EmotionState::alarmed(),
                    voice_persona: Some(300),
                },
                physical_evidence: Vec::new(),
                narrative_tags: Vec::new(),
            },
            WorldEvent {
                event_id: 17,
                tick: 1,
                location_meters: Vec3::ZERO,
                actors: vec![3],
                kind: WorldEventKind::VoiceLineSpoken { speaker: 3 },
                physical_evidence: Vec::new(),
                narrative_tags: vec!["voice".to_string()],
            },
            WorldEvent {
                event_id: 18,
                tick: 1,
                location_meters: Vec3::ZERO,
                actors: vec![3],
                kind: WorldEventKind::SpeechSynthesized {
                    speaker: 3,
                    audio_clip: AudioClipHandle(900),
                    duration_seconds: 2.4,
                    phoneme_count: 18,
                    viseme_count: 9,
                },
                physical_evidence: Vec::new(),
                narrative_tags: Vec::new(),
            },
            WorldEvent {
                event_id: 19,
                tick: 1,
                location_meters: Vec3::ZERO,
                actors: vec![3],
                kind: WorldEventKind::FacialAnimationApplied {
                    entity: 3,
                    viseme_count: 9,
                    duration_seconds: 2.42,
                },
                physical_evidence: Vec::new(),
                narrative_tags: vec!["human_animation".to_string(), "lip_sync".to_string()],
            },
            WorldEvent {
                event_id: 20,
                tick: 1,
                location_meters: Vec3::ZERO,
                actors: vec![3],
                kind: WorldEventKind::HumanAppearanceUpdated {
                    entity: 3,
                    skin_wetness: 0.42,
                    injury_overlay: 0.08,
                    bruising: 0.05,
                    dirt: 0.2,
                },
                physical_evidence: vec!["human_material_response".to_string()],
                narrative_tags: vec!["human".to_string(), "appearance".to_string()],
            },
            WorldEvent {
                event_id: 21,
                tick: 1,
                location_meters: Vec3::ZERO,
                actors: vec![3],
                kind: WorldEventKind::AssetStreamingRequested {
                    asset_id: 3_000,
                    requester: 40,
                    requested_quality: QualityTier::HeroHighFidelityRuntime,
                    priority: AssetPriority::Hero,
                    reason: "human body, clothing, rig, and facial detail bundle".to_string(),
                },
                physical_evidence: vec!["human_runtime_bundle".to_string()],
                narrative_tags: vec!["asset_streaming".to_string(), "human".to_string()],
            },
            WorldEvent {
                event_id: 22,
                tick: 1,
                location_meters: Vec3::ZERO,
                actors: vec![3],
                kind: WorldEventKind::AssetStreamingRequested {
                    asset_id: 3_000,
                    requester: 10,
                    requested_quality: QualityTier::HeroHighFidelityRuntime,
                    priority: AssetPriority::Hero,
                    reason: "human renderer needs skin, eyes, hair, and face morph buffers"
                        .to_string(),
                },
                physical_evidence: vec!["render_dependency".to_string()],
                narrative_tags: vec!["asset_streaming".to_string(), "rendering".to_string()],
            },
        ];

        let report = human_lab_report_from_events(&events);

        assert_eq!(report.dialogue_count, 1);
        assert_eq!(report.voice_line_count, 1);
        assert_eq!(report.speech_performance_count, 1);
        assert_eq!(report.synchronized_face_count, 1);
        assert_eq!(report.unsynchronized_face_count, 0);
        assert_eq!(report.appearance_update_count, 1);
        assert_eq!(report.bundle_request_count, 2);
        assert_eq!(report.critical_issue_count(), 0);
        assert_eq!(report.dialogues[0].speaker, 3);
        assert!(report.dialogues[0].has_voice_line);
        assert!(report.dialogues[0].has_speech);
        assert!(report.dialogues[0].has_facial_animation);
        assert!(report.dialogues[0].has_bundle_request);
        assert!(report.speech_performances[0].synchronized);
        assert!(report.speech_performances[0].has_bundle_request);
        assert!(report.appearance_updates[0].material_responsive);
        assert!(report.bundle_requests.iter().any(|request| {
            request.requester == 40 && request.runtime_bundle && !request.renderer_detail
        }));
        assert!(
            report
                .bundle_requests
                .iter()
                .any(|request| { request.requester == 10 && request.renderer_detail })
        );
    }

