    #[test]
    fn city_persistence_inspector_surfaces_dirty_cells_and_save_priority() {
        let template = generate_world_template(&city_generation_request());
        let chunk = &template.chunks[0];
        let location = chunk.local_navigation.nodes[0].position;
        let fractured_entity = chunk
            .entities
            .iter()
            .find(|entity| entity.tags.iter().any(|tag| tag == "destructible"))
            .and_then(|entity| entity.entity_id)
            .expect("generated chunk should contain destructible geometry");
        let agent = chunk
            .entities
            .iter()
            .find(|entity| entity.agent.is_some())
            .and_then(|entity| entity.entity_id)
            .expect("generated chunk should contain an agent");
        let events = vec![
            WorldEvent {
                event_id: 1,
                tick: 1,
                location_meters: location,
                actors: vec![fractured_entity],
                kind: WorldEventKind::MaterialStateChanged {
                    entity: fractured_entity,
                },
                physical_evidence: Vec::new(),
                narrative_tags: vec!["material".to_string()],
            },
            WorldEvent {
                event_id: 2,
                tick: 1,
                location_meters: location,
                actors: vec![fractured_entity],
                kind: WorldEventKind::MeshReplaced {
                    entity: fractured_entity,
                },
                physical_evidence: Vec::new(),
                narrative_tags: vec!["rendering".to_string()],
            },
            WorldEvent {
                event_id: 3,
                tick: 1,
                location_meters: location,
                actors: Vec::new(),
                kind: WorldEventKind::StreetFlooded,
                physical_evidence: Vec::new(),
                narrative_tags: vec!["physics".to_string()],
            },
            WorldEvent {
                event_id: 4,
                tick: 1,
                location_meters: location,
                actors: vec![agent],
                kind: WorldEventKind::AgentMemoryUpdated {
                    agent,
                    source_event: Some(1),
                    memory_kind: "evidence".to_string(),
                    content: "saw fractured glass".to_string(),
                    importance: 0.8,
                    confidence: 0.9,
                },
                physical_evidence: Vec::new(),
                narrative_tags: vec!["ai".to_string()],
            },
            WorldEvent {
                event_id: 5,
                tick: 1,
                location_meters: location,
                actors: Vec::new(),
                kind: WorldEventKind::StoryEventEmitted {
                    label: "district_pressure_changed".to_string(),
                },
                physical_evidence: Vec::new(),
                narrative_tags: vec!["story".to_string()],
            },
            WorldEvent {
                event_id: 6,
                tick: 1,
                location_meters: location,
                actors: Vec::new(),
                kind: WorldEventKind::AssetBecameResident {
                    asset_id: ashfall_worldgen::ALLEY_GLASS_FRACTURED_MESH_ASSET,
                    quality_tier: QualityTier::HeroHighFidelityRuntime,
                },
                physical_evidence: Vec::new(),
                narrative_tags: vec!["asset_streaming".to_string()],
            },
        ];

        let report = city_persistence_inspector_report_from_events(&template, &events);

        assert!(report.passed());
        assert!(report.save_required);
        assert_eq!(report.city_id, template.city_id);
        assert_eq!(report.event_count, events.len());
        assert_eq!(report.persistent_event_count, events.len());
        assert_eq!(report.cell_count, 1);
        assert_eq!(report.material_override_count, 1);
        assert_eq!(report.mesh_replacement_count, 1);
        assert_eq!(report.infrastructure_delta_count, 1);
        assert_eq!(report.story_thread_ref_count, 1);
        assert_eq!(report.ai_memory_ref_count, 1);
        assert_eq!(report.resident_asset_count, 1);
        assert_eq!(report.critical_issue_count(), 0);

        let cell = report
            .most_changed_cell()
            .expect("persistent report should expose the dirty cell");
        assert_eq!(cell.chunk, chunk.chunk_id);
        assert!(cell.save_priority >= CityPersistenceSavePriority::High);
        assert!(
            cell.infrastructure_systems
                .contains(&InfrastructureSystem::Water)
        );
        assert!(
            cell.infrastructure_systems
                .contains(&InfrastructureSystem::Drainage)
        );
        assert!(
            cell.consequence_tags
                .iter()
                .any(|tag| tag == "resident_asset")
        );
    }

    #[test]
    fn city_navigation_inspector_surfaces_dynamic_route_updates() {
        let template = generate_world_template(&city_generation_request());
        let chunk = &template.chunks[0];
        let location = chunk.local_navigation.nodes[0].position;
        let agent = chunk
            .entities
            .iter()
            .find(|entity| entity.agent.is_some())
            .and_then(|entity| entity.entity_id)
            .expect("generated chunk should contain an agent");
        let events = vec![
            WorldEvent {
                event_id: 10,
                tick: 1,
                location_meters: location,
                actors: vec![agent],
                kind: WorldEventKind::NavigationMoveBlocked { entity: agent },
                physical_evidence: vec!["navigation_blocked".to_string()],
                narrative_tags: vec!["navigation".to_string()],
            },
            WorldEvent {
                event_id: 11,
                tick: 1,
                location_meters: location,
                actors: Vec::new(),
                kind: WorldEventKind::StreetFlooded,
                physical_evidence: Vec::new(),
                narrative_tags: vec!["physics".to_string()],
            },
            WorldEvent {
                event_id: 12,
                tick: 1,
                location_meters: location,
                actors: vec![agent],
                kind: WorldEventKind::SecurityAlertRaised {
                    faction: 700,
                    source_event: 10,
                    threat: agent,
                    severity: 0.82,
                },
                physical_evidence: Vec::new(),
                narrative_tags: vec!["security".to_string()],
            },
        ];

        let report = city_navigation_inspector_report_from_events(&template, &events);

        assert!(report.passed());
        assert_eq!(report.city_id, template.city_id);
        assert_eq!(report.cell_count, template.chunks.len());
        assert_eq!(report.changed_cell_count, 1);
        assert!(report.total_node_count >= 12);
        assert!(report.total_edge_count >= 9);
        assert_eq!(report.dynamic_blocker_count, 1);
        assert!(report.danger_field_count >= 1);
        assert_eq!(report.restricted_zone_count, 1);
        assert!(report.route_update_count > 0);
        assert!(report.blocked_route_count > 0);
        assert!(report.dangerous_route_count > 0);
        assert!(report.partially_unreachable_cell_count > 0);

        let cell = report
            .most_changed_cell()
            .expect("navigation report should expose the changed cell");
        assert_eq!(cell.chunk, chunk.chunk_id);
        assert_eq!(cell.dynamic_blocker_count, 1);
        assert!(cell.danger_kinds.contains(&NavigationDangerKind::Flooding));
    }

