    #[test]
    fn runtime_dependency_policy_tracks_v9_shader_and_hidden_gpu_rules() {
        let shader_key = "render/v9_runtime_policy.comp";
        let shader_contract = GpuShaderContract::for_pipeline(
            "v9_runtime_policy_shader",
            shader_key,
            QualityTier::NormalRuntime,
        );
        let resource = GpuResourceHandle(700);
        let frame = FrameReport {
            frame_id: 1,
            sim_time: SimTime::new(1.0 / 60.0, 1),
            events: Vec::new(),
            profiler: FrameProfilerReport {
                frame_id: 1,
                module_costs: Vec::new(),
                total_module_cpu_milliseconds: 0.0,
                total_module_gpu_milliseconds: 0.0,
                gpu_graph_milliseconds: 0.2,
                total_module_memory_bytes: 0,
                asset_streaming_bytes: 0,
                asset_streaming_pending: 0,
                budget_pressure_count: 0,
            },
            gpu_backend: ashfall_core::gpu::GpuBackend::Vulkan,
            gpu_capability_report: ashfall_core::gpu::GpuCapabilities::vulkan_baseline()
                .capability_report(),
            gpu_passes: vec![
                GpuPassDesc::new(
                    "v9_runtime_policy_shader",
                    GpuQueueKind::Compute,
                    GpuDispatchKind::Compute(ComputePipelineHandle(700)),
                    QualityTier::NormalRuntime,
                )
                .writes([resource])
                .owned_by(10)
                .with_estimated_cost(),
            ],
            gpu_barriers: Vec::new(),
            gpu_timing: Vec::new(),
            gpu_validation: GpuGraphValidationReport::default(),
            gpu_resource_usage: Vec::new(),
            gpu_declared_resources: Vec::new(),
            gpu_registered_resource_usage: Vec::new(),
            gpu_pipeline_report: GpuPipelineReport {
                pipelines: vec![GpuPipelineUsage {
                    kind: GpuPipelineKind::Compute,
                    handle: 700,
                    label: "v9_runtime_policy_shader".to_string(),
                    shader_key: shader_key.to_string(),
                    quality_tier: QualityTier::NormalRuntime,
                    permutation_key: "base".to_string(),
                    permutation_defines: Vec::new(),
                    pass_names: vec!["v9_runtime_policy_shader".to_string()],
                    request_count: 1,
                    cache_hit: false,
                }],
                total_pipeline_requests: 1,
                shader_contracts: vec![GpuShaderPipelineContract {
                    kind: GpuPipelineKind::Compute,
                    handle: 700,
                    label: "v9_runtime_policy_shader".to_string(),
                    shader_key: shader_key.to_string(),
                    permutation_key: "base".to_string(),
                    contract: shader_contract,
                    validation: GpuShaderValidationReport::default(),
                }],
                shader_variant_count: 1,
                ..GpuPipelineReport::default()
            },
            gpu_descriptor_report: GpuDescriptorReport::default(),
            gpu_memory_plan: GpuMemoryPlan::default(),
            gpu_execution_plan: GpuExecutionPlan::default(),
            gpu_queue_workloads: Vec::new(),
            gpu_transient_memory_bytes: 0,
            gpu_total_milliseconds: 0.2,
            module_reports: Vec::new(),
            budget_pressure: Vec::new(),
            budget_plan: BudgetFramePlan::default(),
            asset_streaming: AssetStreamingFrameReport::default(),
            schema_compatibility: SchemaCompatibilityReport::default(),
        };
        let mut capture = build_replay_debug_capture(
            &ReplayLog::new(Vec::new()),
            &ReplayCaptureFilter::default(),
            &[],
            &[],
        );
        capture.frame_graphs = vec![frame_graph_debug_report_from_frame(&frame)];
        capture.runtime_policy = runtime_dependency_policy_report_from_capture(&capture);

        assert_eq!(capture.runtime_policy.check_count, 10);
        assert_eq!(
            capture.runtime_policy.hidden_gpu_backend_dependency_count,
            0
        );
        assert_eq!(capture.runtime_policy.ml_gpu_backend_dependency_count, 0);
        assert_eq!(capture.runtime_policy.forbidden_ui_dependency_count, 0);
        assert_eq!(capture.runtime_policy.shader_pipeline_report_count, 1);
        assert_eq!(capture.runtime_policy.shader_pipeline_count, 1);
        assert_eq!(capture.runtime_policy.shader_contract_count, 1);
        assert_eq!(capture.runtime_policy.validated_shader_contract_count, 1);
        assert_eq!(capture.runtime_policy.shader_variant_count, 1);
        assert_eq!(
            capture.runtime_policy.engine_shader_source_artifact_count,
            1
        );
        assert_eq!(capture.runtime_policy.unknown_shader_artifact_count, 0);
        assert_eq!(capture.runtime_policy.shader_validation_error_count, 0);
        assert!(
            capture
                .runtime_policy
                .check(RuntimeDependencyPolicyCheckKind::HiddenGpuBackendBoundary)
                .is_some_and(|check| check.passed)
        );
        assert!(
            capture
                .runtime_policy
                .check(RuntimeDependencyPolicyCheckKind::RustOwnedShaderPipeline)
                .is_some_and(|check| check.passed)
        );
    }

