    #[test]
    fn replay_debug_capture_combines_replay_profiler_and_asset_validation_gate() {
        let replay_log = ReplayLog::new(vec![ReplayFrame {
            frame_id: 1,
            tick: 10,
            queued_commands: vec![WorldCommand::EmitStoryEvent(
                ashfall_core::world::StoryEvent {
                    label: "debug_story".to_string(),
                    actors: vec![1],
                    location: Vec3::ZERO,
                    tags: vec!["debug".to_string()],
                },
            )],
            events: vec![WorldEvent {
                event_id: 99,
                tick: 10,
                location_meters: Vec3::new(1.0, 0.0, 0.0),
                actors: vec![1],
                kind: WorldEventKind::PlayerIdentityExposed,
                physical_evidence: vec!["npc_witness".to_string()],
                narrative_tags: vec!["identity".to_string()],
            }],
        }]);
        let profiler = FrameProfilerReport {
            frame_id: 1,
            module_costs: vec![ModuleCostReport::from_module_report(&ModuleFrameReport {
                descriptor: ModuleDescriptor {
                    module_id: 50,
                    name: "ai_characters_story",
                    schema: SchemaVersion {
                        name: "AiFrameOutput",
                        version: 1,
                    },
                    default_quality: QualityTier::NormalRuntime,
                },
                quality_tier: QualityTier::NormalRuntime,
                counters: PerformanceCounters {
                    cpu_milliseconds: 0.4,
                    gpu_milliseconds: 0.2,
                    memory_bytes: 4096,
                },
                budget: ModuleBudget::for_quality(50, QualityTier::NormalRuntime),
                pressure: Vec::new(),
            })],
            total_module_cpu_milliseconds: 0.4,
            total_module_gpu_milliseconds: 0.2,
            gpu_graph_milliseconds: 0.1,
            total_module_memory_bytes: 4096,
            asset_streaming_bytes: 0,
            asset_streaming_pending: 0,
            budget_pressure_count: 0,
        };
        let request = AssetBuildRequest {
            source_asset: 44,
            target_kind: AssetKind::MaterialGraph,
            build_profile: BuildProfile::Editor,
            validation_level: ValidationLevel::Runtime,
            dependency_policy: DependencyPolicy::RequireDeclared,
        };
        let asset = build_runtime_package(&request, &source_asset(), &schema_registry());

        let capture = build_replay_debug_capture(
            &replay_log,
            &ReplayCaptureFilter::default().with_event_kind_label("PlayerIdentityExposed"),
            &[profiler],
            &[asset],
        );

        assert_eq!(capture.replay.len(), 1);
        assert_eq!(capture.asset_pipeline.built_assets, 1);
        assert!(capture.asset_pipeline.failed_assets == 0);
        assert!(!capture.conformance.is_empty());
        assert!(
            capture
                .notes
                .iter()
                .any(|note| note.contains("replay frame"))
        );

        let gate = AutomatedValidationGate {
            max_cpu_time_us: Some(1000),
            max_gpu_time_us: Some(1000),
            ..AutomatedValidationGate::default()
        };
        assert!(gate.evaluate(&capture).passed);

        let strict_gate = AutomatedValidationGate {
            max_cpu_time_us: Some(100),
            max_gpu_time_us: Some(1000),
            ..AutomatedValidationGate::default()
        };
        let strict_report = strict_gate.evaluate(&capture);
        assert!(!strict_report.passed);
        assert!(
            strict_report
                .issues
                .iter()
                .any(|issue| issue.code == "cpu_budget_exceeded")
        );
    }

