    #[test]
    fn built_asset_projects_to_shared_manifest_and_validation_report() {
        let request = AssetBuildRequest {
            source_asset: 44,
            target_kind: AssetKind::MaterialGraph,
            build_profile: BuildProfile::Editor,
            validation_level: ValidationLevel::Runtime,
            dependency_policy: DependencyPolicy::RequireDeclared,
        };
        let result = build_runtime_package(&request, &source_asset(), &schema_registry());

        let validation = result.validation_report_v4();
        let manifest = result.package_manifest_v4();
        let manifest_validation = manifest.validate(TOOLS_SYSTEM_ID);

        assert!(validation.passed);
        assert_eq!(validation.asset, Some(result.asset_id));
        assert!(
            validation
                .metrics
                .iter()
                .any(|metric| metric.name == "validation_score")
        );
        assert_eq!(manifest.package_asset, result.asset_id);
        assert_eq!(manifest.schema_name, "ProceduralMaterialGraph");
        assert_eq!(manifest.schema_version, 2);
        assert_eq!(manifest.dependencies, vec![1001, 1002]);
        assert_eq!(manifest.chunks.len(), 1);
        assert_eq!(manifest.total_uncompressed_bytes, 4096);
        assert!(manifest_validation.passed);
    }

